window.HACCP_QUIZ_DATA = {"meta":{"title":"HACCP実務クイズ","subtitle":"食品工場の判断力を200問で確認","version":"v014","updated":"2026-07-25","questionCount":200,"categoryCount":14,"sourceWorkbook":"HACCP_QUIZ_MASTER_正マスター_v014_20260725.xlsx","uiStandard":"MARKET_BASE_UI_ALIGNMENT_KIT_R113_1"},"categories":[{"code":"A","name":"HACCPの基本・目的・用語","count":15,"description":"目的、完成品検査との違い、7原則、適用手順、チーム、製品説明、フロー、計画"},{"code":"B","name":"一般衛生管理・GHP","count":15,"description":"手洗い、健康、清掃、洗浄・殺菌、害虫、水、受入れ、保管、交差汚染、アレルゲン"},{"code":"C","name":"危害分析と危害評価","count":15,"description":"生物的・化学的・物理的危害、発生可能性、重大性、後工程での管理"},{"code":"D","name":"CCP・管理基準・監視・是正・検証","count":20,"description":"CCP、管理基準、モニタリング、逸脱、製品隔離、原因調査、検証、妥当性確認"},{"code":"E","name":"食品工場の工程別実務","count":15,"description":"受入れ、保管、解凍、洗浄、切断、混合、加熱、冷却、充填、包装、検出、出荷"},{"code":"F","name":"食品機械・設備・センサー・洗浄設計","count":12,"description":"温度、時間、圧力、流量、校正、警報、インターロック、記録、洗浄性、デッドスペース"},{"code":"G","name":"海外対応・監査・規格との関係","count":8,"description":"Codex、各国法令、輸出条件、ISO 22000、FSSC 22000、監査、英語文書"},{"code":"H","name":"食品別危害分析・製品別ケース","count":15,"description":"食肉、水産、乳、卵、米飯、惣菜、冷凍食品、飲料など"},{"code":"I","name":"工程別トラブル・逸脱判断","count":15,"description":"受入れ、解凍、加熱、冷却、充填、包装、保管、出荷の異常判断"},{"code":"J","name":"衛生設計・洗浄・環境衛生","count":15,"description":"CIP、COP、排水、結露、ゾーニング、環境モニタリング"},{"code":"K","name":"微生物・アレルゲン・異物の深掘り","count":15,"description":"増殖・生残・毒素、交差接触、表示、異物発生源"},{"code":"L","name":"検証・妥当性確認・記録・データ管理","count":15,"description":"妥当性確認、検証、校正、記録レビュー、電子記録"},{"code":"M","name":"トレーサビリティ・回収・供給者・物流","count":10,"description":"ロット追跡、模擬回収、供給者変更、保管輸送、委託先"},{"code":"N","name":"海外制度・監査・総合ケース","count":15,"description":"輸出、顧客監査、ISO・FSSC、複数工程の総合判断"}],"scoreBands":[{"range":"90～100％","label":"現場指導レベル","meaning":"幅広い論点を理解している","note":"正式資格や認定を意味しない"},{"range":"75～89％","label":"実務理解レベル","meaning":"基本と多くの現場判断を理解している","note":"苦手カテゴリーは復習する"},{"range":"60～74％","label":"基本理解レベル","meaning":"基本は理解しているが判断問題に課題がある","note":"ケース問題を重点復習する"},{"range":"40～59％","label":"復習推奨","meaning":"重要概念に抜けがある","note":"基本編と危害分析から見直す"},{"range":"0～39％","label":"基礎から確認","meaning":"HACCPの目的・危害・CCPの基本から確認する","note":"段階的に進める"}],"questions":[{"id":"Q001","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"CCPの決定","difficulty":"レベル1","format":"○×","question":"加熱工程であっても、危害分析の結果によってCCPにならない場合がある。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"加熱工程という名前だけでCCPは決まらない。","explanation":"CCPは、対象危害、前後の工程、別の管理手段などを評価して決定する。加熱工程であっても、自動的にCCPになるわけではない。","wrongReason":"Bは、加熱工程が必ずCCPになると誤解している。","example":"加熱後に別の確実な殺菌工程がある場合や、対象危害が加熱で管理されない場合など、工程全体の条件によって判断が変わる。","terms":"CCP、危害分析、管理手段","process":"加熱","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回で正式問題へ昇格"},{"id":"Q002","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"逸脱時の製品処置","difficulty":"レベル2","format":"四択","question":"加熱後の食品を冷却していたところ、規定の時間内に予定温度まで下がらなかった。最も適切な最初の対応はどれか。","options":[{"key":"A","text":"対象製品を特定して区分し、製品の安全性と原因を確認する"},{"key":"B","text":"翌日の記録に正しい温度を書いておく"},{"key":"C","text":"冷却機の設定温度だけを下げて、そのまま出荷する"},{"key":"D","text":"見た目に異常がなければ問題ない"}],"correct":["A"],"conclusion":"まず対象製品を特定・区分し、安全性と原因を確認する。","explanation":"管理基準から外れた場合は、対象製品を特定し、ほかの製品と混ざらないように管理する。そのうえで再冷却、再加熱、検査、廃棄などの扱いを決定する。","wrongReason":"Bは記録の改ざん、Cは製品評価をせず出荷している、Dは見た目だけで安全性を判断している。","example":"冷却記録に逸脱が見つかった場合、製造時間帯とロットを確認し、保留表示を付けて品質管理担当者が処置を判断する。","terms":"逸脱、改善措置、製品隔離","process":"冷却","hazard":"生物的危害","scope":"製品・工程別に基準を設定","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回で正式問題へ昇格"},{"id":"Q003","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"測定器の精度確認","difficulty":"レベル2","format":"○×","question":"温度記録が毎回正常でも、基準判定に使う温度センサーの精度確認は必要である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"記録が正常でも、センサー自体のずれは別に確認する必要がある。","explanation":"センサーがずれていれば、記録上は正常でも実際の温度が基準を満たしていない可能性がある。校正または精度確認を計画的に行う。","wrongReason":"Bは、表示値が正常であればセンサーのずれはないと誤解している。","example":"基準温度計との比較、氷点・沸点付近での確認、外部校正などを計画に基づいて行い、結果を記録する。","terms":"校正、精度確認、温度センサー","process":"加熱・冷却","hazard":"共通","scope":"国際共通の原則","sourceId":"S008","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回で正式問題へ昇格"},{"id":"Q004","categoryCode":"C","category":"危害分析と危害評価","subtheme":"物理的危害","difficulty":"レベル1","format":"四択","question":"包装機内部でボルトが外れ、製品へ混入する可能性がある。これは主に何に分類されるか。","options":[{"key":"A","text":"生物的危害"},{"key":"B","text":"化学的危害"},{"key":"C","text":"物理的危害"},{"key":"D","text":"品質問題だけであり、危害ではない"}],"correct":["C"],"conclusion":"機械部品の混入は物理的危害として評価する。","explanation":"金属部品の混入は、口腔内のけがなどにつながる可能性があるため、物理的危害として評価する。設備点検、緩み止め、部品管理、検出工程などの管理方法を検討する。","wrongReason":"Aは微生物、Bは化学物質に関する危害。Dは食品安全上の危害となる可能性を無視している。","example":"保守後にボルト本数を確認し、欠品があれば製造を再開せず、機内・製品・周辺を捜索する。","terms":"物理的危害、部品脱落、保守点検","process":"包装","hazard":"物理的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回で正式問題へ昇格"},{"id":"Q005","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCPと食品機械","difficulty":"レベル1","format":"○×","question":"「HACCP対応」と表示された食品機械を導入しても、それだけで工場全体が自動的にHACCPへ適合するわけではない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"機械1台の導入だけで工場全体のHACCP運用は完成しない。","explanation":"HACCPは、食品、原料、工程、作業方法、設備、記録、異常時対応などを含む工場全体の衛生管理である。機械は運用を支援するが、工場全体の適合を保証しない。","wrongReason":"Bは、機械の表示だけで工場全体のHACCP適合が決まると誤解している。","example":"機械メーカーは温度記録、警報、洗浄性などを説明し、食品事業者は自社製品と工程に合わせて危害分析とHACCP計画を作る。","terms":"HACCP計画、食品機械、責任範囲","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回基本編として内容確定"},{"id":"Q006","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCPの目的","difficulty":"レベル1","format":"四択","question":"HACCPの説明として最も適切なものはどれか。","options":[{"key":"A","text":"完成品を検査するだけで安全を保証する方法"},{"key":"B","text":"食品安全上の危害を工程ごとに分析し、重要な管理を予防的に行う仕組み"},{"key":"C","text":"味や色のばらつきをなくす品質管理の手法"},{"key":"D","text":"食品機械の故障を完全になくす保全方法"}],"correct":["B"],"conclusion":"HACCPは、食品安全上の危害を工程の中で予防的に管理する仕組みである。","explanation":"HACCPは、生物的・化学的・物理的な食品安全危害を特定・評価し、必要な管理手段を設定して継続的に管理する考え方である。完成品検査だけに依存する方法ではない。","wrongReason":"Aは工程中の予防管理を省いている。Cは主に品質管理、Dは設備保全の目的であり、HACCPそのものの説明ではない。","example":"加熱不足、洗浄剤残留、金属片混入などを工程ごとに洗い出し、管理方法と確認方法を決める。","terms":"HACCP、危害、予防管理","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q007","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"予防管理と完成品検査","difficulty":"レベル1","format":"○×","question":"完成品検査の結果が合格でも、製造工程中の管理は必要である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"完成品検査だけではなく、工程中で危害を予防・管理することが重要である。","explanation":"完成品検査は一部の製品を確認する方法であり、すべての製品の安全を直接保証するものではない。HACCPでは工程中の予防管理を重視する。","wrongReason":"Bは、完成品検査が工程管理の代わりになると誤解している。","example":"加熱品の一部だけを微生物検査するのではなく、加熱温度や時間を製造中に監視し、基準外を早く検知する。","terms":"完成品検査、予防管理、モニタリング","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q008","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"危害の3分類","difficulty":"レベル1","format":"複数選択","question":"HACCPで食品安全上の危害として扱うものをすべて選んでください。","options":[{"key":"A","text":"製品へ混入した金属片"},{"key":"B","text":"食中毒を起こす病原微生物"},{"key":"C","text":"食品に残留した洗浄剤"},{"key":"D","text":"包装デザインの好みの違い"}],"correct":["A","B","C"],"conclusion":"病原微生物、化学物質、異物は、それぞれ生物的・化学的・物理的危害になり得る。","explanation":"HACCPでは、病原微生物などの生物的危害、洗浄剤やアレルゲンなどの化学的危害、金属片やガラス片などの物理的危害を対象にする。包装デザインの好みは通常、食品安全危害ではない。","wrongReason":"Dは販売やデザイン上の問題であり、病気やけがにつながる食品安全危害とは区別する。","example":"原料、各工程、設備、包装、保管まで確認し、どの種類の危害がどこで発生するかを整理する。","terms":"生物的危害、化学的危害、物理的危害","process":"全工程","hazard":"生物的・化学的・物理的危害","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q009","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCPの7原則","difficulty":"レベル1","format":"四択","question":"次のうち、HACCPの7原則に含まれないものはどれか。","options":[{"key":"A","text":"重要管理点（CCP）を決定する"},{"key":"B","text":"モニタリング方法を設定する"},{"key":"C","text":"危害分析を行う"},{"key":"D","text":"従業員の人事評価制度を設定する"}],"correct":["D"],"conclusion":"人事評価制度はHACCPの7原則には含まれない。","explanation":"HACCPの7原則は、危害分析、CCPの決定、管理基準の設定、モニタリング、改善措置、検証、記録・文書化で構成される。教育や人員配置は運用に重要だが、人事評価制度そのものは7原則ではない。","wrongReason":"A・B・CはいずれもHACCPの原則に含まれる。Dは会社の人事管理に関する事項である。","example":"新しい製品のHACCP計画を作る際は、準備手順の後に7原則を順番に適用する。","terms":"HACCPの7原則、CCP、モニタリング","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q010","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCPチーム","difficulty":"レベル2","format":"四択","question":"HACCP計画を作成する体制として最も適切なものはどれか。","options":[{"key":"A","text":"製品、製造、衛生、設備など必要な知識を持つ人を集め、不足する知識は専門家で補う"},{"key":"B","text":"品質管理担当者一人だけで、現場を確認せずに作る"},{"key":"C","text":"機械メーカーへすべて任せ、食品事業者は内容を確認しない"},{"key":"D","text":"他社の計画書を社名だけ変更して使用する"}],"correct":["A"],"conclusion":"HACCP計画は、製品と工程を理解する複数分野の知識を集めて作る。","explanation":"危害分析には、原料、製造方法、設備、衛生、保管、消費方法などの知識が必要になる。小規模事業者で人数が限られる場合でも、必要に応じて外部専門家や公的手引書を活用し、知識不足を補う。","wrongReason":"Bは現場情報が不足しやすい。Cは食品事業者自身の工程責任を外部へ丸投げしている。Dは製品・設備・運用条件の違いを無視している。","example":"製造、品質管理、設備保全、商品開発の担当者が工程図を確認し、必要に応じて微生物や法令の専門家へ相談する。","terms":"HACCPチーム、専門知識、危害分析","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q011","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"製品説明書","difficulty":"レベル2","format":"四択","question":"HACCP適用前に製品の原材料、包装、保存条件、流通方法などを整理する主な理由はどれか。","options":[{"key":"A","text":"機械の型式を決めるためだけ"},{"key":"B","text":"商品紹介文を作りやすくするため"},{"key":"C","text":"製品の条件によって発生する危害や必要な管理が変わるため"},{"key":"D","text":"製造原価を計算するため"}],"correct":["C"],"conclusion":"製品の性質と扱われ方を理解しなければ、適切な危害分析はできない。","explanation":"同じ名称の食品でも、水分、酸性度、包装、保存温度、賞味期間、流通方法などによって微生物の増殖や汚染の可能性が変わる。製品説明は、危害分析の前提情報になる。","wrongReason":"A・B・Dは業務上必要な場合があるが、HACCPで製品説明を作る中心目的ではない。","example":"常温流通品と冷蔵流通品では、保管中に考えるべき危害や管理方法が異なる。","terms":"製品説明、保存条件、流通方法","process":"製品設計・全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q012","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"意図する用途と対象消費者","difficulty":"レベル2","format":"四択","question":"高齢者向けの加熱済み食品について、食べ方と対象消費者を確認する理由として最も適切なものはどれか。","options":[{"key":"A","text":"包装の色を決めるため"},{"key":"B","text":"食べる前に再加熱されるか、影響を受けやすい人が食べるかによって危害評価が変わるため"},{"key":"C","text":"製造担当者の人数を決めるため"},{"key":"D","text":"宣伝文句を決めるためだけ"}],"correct":["B"],"conclusion":"最終的な食べ方と対象消費者は、危害の重大性や必要な管理に影響する。","explanation":"そのまま食べる食品か、十分に再加熱して食べる食品かで後工程の管理機会が異なる。また、高齢者、乳幼児、免疫機能が低下した人などは、食品由来の危害による影響が大きくなる場合がある。","wrongReason":"A・C・DはHACCP上の危害評価を直接説明していない。","example":"同じ加熱済み食品でも、一般消費者向けと医療・介護施設向けでは、危害の重大性をより慎重に評価する場合がある。","terms":"意図する用途、対象消費者、感受性集団","process":"喫食・製品設計","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q013","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"フローダイアグラム","difficulty":"レベル1","format":"○×","question":"工程図は、実際の製造現場で確認し、現場の流れと一致させる必要がある。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"工程図は現場で確認し、実際の流れと一致させる必要がある。","explanation":"書類上の工程図には、戻し、手直し、一時保管、迂回経路などが抜けることがある。危害分析前に現場を歩いて確認する。","wrongReason":"Bは、事務所で作った工程図だけで実際の工程を正確に表せると誤解している。","example":"通常工程にはない再投入や一時保管が実際には行われていないか、製造中に歩いて確認する。","terms":"工程図、現場確認、再加工","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q014","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"工程図の現場確認","difficulty":"レベル2","format":"現場判断","question":"現場確認で、工程図に書かれていない「不良品を前工程へ戻す経路」が見つかりました。危害分析を始める前に行う対応として最も適切なものはどれか。","options":[{"key":"A","text":"工程図は変更せず、口頭で覚えておく"},{"key":"B","text":"不良品が少量なら無視する"},{"key":"C","text":"戻し経路を工程図へ追加し、条件と実際の運用を確認して記録する"},{"key":"D","text":"監査のときだけ工程図へ追加する"}],"correct":["C"],"conclusion":"実際に存在する戻し工程は、工程図へ反映してから危害分析する。","explanation":"再加工や戻し工程では、滞留時間の増加、異物、アレルゲン、加熱履歴の不明確化など新たな危害が生じる可能性がある。実際の経路、戻せる条件、識別方法を確認し、工程図と関連手順を更新する。","wrongReason":"A・Bは危害分析から工程を落としてしまう。Dは日常運用と文書が一致しない。","example":"加熱前へ戻す製品と加熱後へ戻す製品を混同しないよう、戻し先、量、時間、ロット識別を決める。","terms":"工程図、再加工、リワーク","process":"再加工","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q015","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"経営者の関与","difficulty":"レベル2","format":"四択","question":"HACCPを継続的に機能させるため、経営者・管理者の関与が重要な理由はどれか。","options":[{"key":"A","text":"HACCPチームを解散するため"},{"key":"B","text":"書類へ署名する人が必要だからだけ"},{"key":"C","text":"すべてのモニタリングを社長が行うため"},{"key":"D","text":"人員、教育、設備改善、時間など必要な資源と権限を確保する必要があるため"}],"correct":["D"],"conclusion":"管理者の関与は、計画を実行するための資源と権限を確保するうえで重要である。","explanation":"HACCPは計画書を作るだけでは機能しない。教育、保守、測定器、記録時間、異常品の保留判断などを実行するには、管理者が食品安全を優先し、必要な資源と責任を明確にする必要がある。","wrongReason":"Bは形式だけに限定している。Cは担当者の役割分担を無視している。Aは継続的な管理体制を失わせる。","example":"生産を止めて異常品を保留できる権限を現場責任者へ与え、必要な保守費用を確保する。","terms":"経営者のコミットメント、資源、権限","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q016","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"施設ごとの計画","difficulty":"レベル2","format":"○×","question":"同じ商品名の食品でも、各工場の工程・設備・運用条件に合わせてHACCP計画を確認・作成する必要がある。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"HACCP計画は、各施設の製品、工程、設備、流通条件に合わせて作る。","explanation":"同じ商品名でも、原料、設備能力、作業動線、保存条件、対象消費者が異なる場合がある。他工場の計画は参考にできるが、そのまま使用せず現場に合わせて確認する。","wrongReason":"Bは、商品名が同じなら施設固有の条件を確認しなくてもよいと誤解している。","example":"連続加熱機とバッチ式加熱釜では、監視する値、測定位置、異常時に影響する製品範囲が異なる。","terms":"施設固有、工程条件、HACCP計画","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q017","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCP計画とHACCPシステム","difficulty":"レベル2","format":"四択","question":"「HACCP計画」と「HACCPシステム」の関係として最も適切なものはどれか。","options":[{"key":"A","text":"HACCP計画は手順を示す文書で、HACCPシステムはその計画を実施した管理の仕組みである"},{"key":"B","text":"二つは食品の品質等級を表す"},{"key":"C","text":"どちらも食品機械の名称である"},{"key":"D","text":"HACCP計画は認証書で、HACCPシステムは監査会社である"}],"correct":["A"],"conclusion":"計画書があるだけでなく、実際に実施・維持されてHACCPシステムになる。","explanation":"HACCP計画は、危害、CCP、管理基準、監視、改善措置、検証、記録などの手順を示す文書である。HACCPシステムは、その計画を現場で実施し、維持している状態を指す。","wrongReason":"B・C・Dはいずれも用語の意味を誤っている。","example":"計画書に温度確認を定めていても、実際に測定・記録・逸脱対応をしていなければ、システムは機能していない。","terms":"HACCP計画、HACCPシステム、実施","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q018","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"食品安全と品質","difficulty":"レベル2","format":"四択","question":"必要な加熱条件を満たし安全性に影響がないことが確認されていますが、製品の焼き色が社内規格より薄い状態でした。主にどの問題として扱うべきですか。","options":[{"key":"A","text":"必ず化学的危害"},{"key":"B","text":"必ず物理的危害"},{"key":"C","text":"主に品質上の問題"},{"key":"D","text":"食品安全上の危害だけの問題"}],"correct":["C"],"conclusion":"安全条件を満たしている場合、焼き色の違いは主に品質問題として扱う。","explanation":"HACCPの危害分析では、病気やけがにつながる食品安全上の問題と、色、形、食感などの品質問題を区別する。ただし、焼き色不足が実際には加熱不足を示す工程なら、安全性との関係を別途評価する必要がある。","wrongReason":"Dは安全性への影響がないという条件を無視している。A・Bは危害分類の根拠がない。","example":"外観規格外として選別しながら、加熱記録も確認して品質問題と食品安全問題を混同しない。","terms":"食品安全、品質、危害分析","process":"加熱・検品","hazard":"共通","scope":"条件付きの国際共通原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q019","categoryCode":"A","category":"HACCPの基本・目的・用語","subtheme":"HACCP運用と第三者認証","difficulty":"レベル2","format":"○×","question":"HACCPに基づく管理を実施することと、第三者機関から認証を受けることは別の概念である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"HACCPの運用と第三者認証は別の概念である。","explanation":"HACCPは危害を予防的に管理する仕組みであり、第三者認証は特定の基準への適合を外部機関が審査する仕組みである。法令や取引条件により認証の扱いは異なる。","wrongReason":"Bは、HACCP運用と第三者認証が必ず同じ意味だと誤解している。","example":"取引先が認証書を求める場合は、HACCPを実施しているだけで足りるか、指定された認証制度が必要かを確認する。","terms":"HACCP運用、第三者認証、取引先要求","process":"全工程","hazard":"共通","scope":"概念は共通。認証制度の扱いは国・地域・取引条件により異なる","sourceId":"S005","sourceUrl":"https://www.mhlw.go.jp/content/11130500/000483084.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成／日本の公的Q&Aで認証との違いを確認"},{"id":"Q020","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"前提条件プログラム","difficulty":"レベル1","format":"四択","question":"一般衛生管理や前提条件プログラムの役割として最も適切なものはどれか。","options":[{"key":"A","text":"すべての作業をCCPに変える仕組み"},{"key":"B","text":"工場の基本的な衛生・運用条件を整え、HACCPを機能させる土台"},{"key":"C","text":"完成品の販売価格を決める仕組み"},{"key":"D","text":"HACCPを使わない工場だけが行う管理"}],"correct":["B"],"conclusion":"一般衛生管理は、HACCPを支える基本的な衛生管理の土台である。","explanation":"手洗い、清掃、害虫管理、水、薬剤、設備保守、交差汚染防止などを日常的に安定して行うことで、HACCPでは製品や工程に固有の重要な危害へ集中できる。","wrongReason":"DはHACCPとの関係を逆に理解している。Aは一般管理とCCPを混同している。Cは食品安全管理ではない。","example":"手洗いや清掃が安定していない工場では、加熱CCPだけを管理しても加熱後の再汚染を防げない。","terms":"GHP、前提条件プログラム、一般衛生管理","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q021","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"一般衛生管理とCCP","difficulty":"レベル1","format":"○×","question":"手洗い、清掃、害虫管理などの一般衛生管理項目は、すべてをCCPとして管理する必要はない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"一般衛生管理のすべてをCCPにする必要はない。","explanation":"一般衛生管理はHACCPを支える基礎であり、通常は前提条件プログラムとして管理する。CCPは危害分析で管理が不可欠と判断した工程に設定する。","wrongReason":"Bは、一般衛生管理の全項目をCCPにしなければならないと誤解している。","example":"清掃手順は一般衛生管理で管理し、加熱が重大な病原菌を制御する不可欠な工程なら、加熱をCCPとして管理する場合がある。","terms":"GHP、CCP、一般衛生管理","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q022","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"手洗いと手袋","difficulty":"レベル1","format":"○×","question":"使い捨て手袋は手洗いの代わりにはならない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"手袋は手洗いの代わりにはならない。","explanation":"手袋は装着前の手、破損、交換不足、汚れた表面への接触によって汚染される。適切な手洗いと交換手順が必要である。","wrongReason":"Bは、手袋を着用すれば手洗いが不要になると誤解している。","example":"生肉を扱った手袋のまま加熱済み食品へ触れず、手洗いと手袋交換を行ってから作業を切り替える。","terms":"手洗い、手袋、個人衛生","process":"全工程","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q023","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"従業員の健康管理","difficulty":"レベル1","format":"四択","question":"食品を扱う作業者が出勤後に嘔吐や下痢の症状を申告しました。最も適切な対応はどれか。","options":[{"key":"A","text":"記録せずに別の作業者と交代するだけ"},{"key":"B","text":"本人が働けると言えば、そのまま食品へ触れる作業を続ける"},{"key":"C","text":"手袋を二重にすれば通常作業を続ける"},{"key":"D","text":"症状を報告させ、社内手順と法令に従って食品取扱いから外す、または就業を制限する"}],"correct":["D"],"conclusion":"食品を汚染する可能性のある症状は報告し、定めた手順で就業を制限する。","explanation":"嘔吐や下痢などの症状がある作業者は、食品や食品接触面を汚染する可能性がある。本人の判断だけに任せず、報告ルール、就業制限、復帰条件を定め、地域の法令や公的指針に従う。","wrongReason":"B・Cは汚染リスクを十分に管理していない。Aは原因と対応を追跡できない。","example":"体調不良者を包装外作業へ変更するか帰宅させ、接触した区域や器具の必要な洗浄・消毒を判断する。","terms":"健康管理、就業制限、個人衛生","process":"全工程","hazard":"生物的危害","scope":"国・地域の法令と社内手順を確認","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q024","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"交差汚染防止","difficulty":"レベル2","format":"四択","question":"生の鶏肉を扱った台で、加熱済みの食品を包装する必要があります。最も適切な対応はどれか。","options":[{"key":"A","text":"生肉作業と加熱済み食品を分離し、共用する場合は定めた洗浄・殺菌と切替確認を行う"},{"key":"B","text":"台の上へ紙を敷くだけで使用する"},{"key":"C","text":"加熱済み食品を後で冷蔵すれば問題ない"},{"key":"D","text":"見た目がきれいなら、そのまま包装を始める"}],"correct":["A"],"conclusion":"生の原料から加熱済み食品への交差汚染を防ぐ必要がある。","explanation":"加熱済み食品は、後で危害を除去する工程がない場合がある。区域、時間、器具、人の動線を分離し、共用設備では有効な洗浄・殺菌と切替確認を実施する。","wrongReason":"B・Dは汚染を十分に除去・防止できない。Cは冷蔵しても付着した病原微生物を除去できない。","example":"色分けした器具や専用台を使用し、共用時は切替チェックリストで残渣と洗浄状態を確認する。","terms":"交差汚染、ゾーニング、加熱済み食品","process":"加熱後・包装","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q025","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"洗浄前の汚れ除去","difficulty":"レベル1","format":"○×","question":"食品残渣や汚れを適切に除去してから、必要な殺菌・サニテーションを行う。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"目に見える残渣や汚れを適切に除去してから、必要な殺菌を行う。","explanation":"有機物や食品残渣が残ると、殺菌剤が微生物へ十分作用しない場合がある。洗浄と殺菌は目的と順序を分けて実施する。","wrongReason":"Bは、汚れが残ったまま殺菌剤を使えば洗浄を省略できると誤解している。","example":"撹拌羽根の裏側に固着した食品を除去せずに薬剤を噴霧するだけでは、接触面全体を衛生的にできない。","terms":"洗浄、殺菌、食品残渣","process":"洗浄","hazard":"生物的・化学的危害","scope":"設備・薬剤の手順に従う","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q026","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"洗浄と殺菌の違い","difficulty":"レベル1","format":"四択","question":"「洗浄」と「殺菌・サニテーション」の違いとして最も適切なものはどれか。","options":[{"key":"A","text":"洗浄は微生物だけを除去し、殺菌は金属片を除去する"},{"key":"B","text":"殺菌をすればアレルゲンも必ず完全に除去できる"},{"key":"C","text":"洗浄は汚れや残渣を除去し、殺菌・サニテーションは微生物を管理可能な水準まで低減する"},{"key":"D","text":"どちらも必ず同じ薬剤と時間で行う"}],"correct":["C"],"conclusion":"洗浄と殺菌は目的が異なり、両方が必要になる場合がある。","explanation":"洗浄は食品残渣、油脂、汚れなどを表面から除去する操作である。殺菌・サニテーションは、清浄化された表面などの微生物を安全上許容できる水準へ低減する操作である。薬剤や方法は対象によって異なる。","wrongReason":"Dは対象や薬剤条件の違いを無視している。Aは役割が逆で、金属片除去の説明でもない。Bはアレルゲン除去の検証を省いている。","example":"製品切替では、見た目の汚れ除去だけでなく、必要に応じて微生物やアレルゲンの残留も確認する。","terms":"洗浄、殺菌、サニテーション","process":"洗浄","hazard":"生物的・化学的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q027","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"使用水と氷","difficulty":"レベル1","format":"○×","question":"食品や食品接触面に触れる水と、その水から作る氷は、安全な水質であることを管理する必要がある。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"食品へ触れる水や氷は、食品を汚染しない水質でなければならない。","explanation":"洗浄水、原料水、冷却水、氷などが食品や食品接触面に触れる場合、水が微生物や化学物質の汚染源にならないよう、水源、処理、保管、配管、検査などを管理する。","wrongReason":"Bは、水や氷が食品へ直接または間接に接触することによる汚染リスクを無視している。","example":"製氷機の内部や給水配管も定期的に点検・清掃し、貯氷槽へ汚れたスコップを入れない。","terms":"使用水、氷、水質管理","process":"洗浄・製造・冷却","hazard":"生物的・化学的危害","scope":"国・用途ごとの水質基準を確認","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q028","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"洗浄剤・薬剤管理","difficulty":"レベル2","format":"現場判断","question":"作業場で、中身が分からない無表示のスプレーボトルが見つかりました。最も適切な対応はどれか。","options":[{"key":"A","text":"使用を止めて隔離し、内容を確認できなければ定めた方法で廃棄する"},{"key":"B","text":"色や匂いから薬剤を推定して使う"},{"key":"C","text":"少量だけ食品の近くで試す"},{"key":"D","text":"翌日の担当者へ口頭で伝え、そのまま置いておく"}],"correct":["A"],"conclusion":"内容不明の薬剤は使用せず、識別・保管・廃棄を確実に行う。","explanation":"洗浄剤や殺菌剤などの化学物質は、名称、濃度、用途、注意事項を識別できる状態で保管し、食品や包装材を汚染しないように使用する。内容を確認できない容器は使用を止める。","wrongReason":"B・Cは誤使用や食品への残留につながる。Dは誤使用を防止できない。","example":"小分け容器にも正式な表示を付け、食品用容器へ薬剤を移し替えない。","terms":"薬剤管理、表示、化学的危害","process":"洗浄・保管","hazard":"化学的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q029","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"害虫・害獣管理","difficulty":"レベル1","format":"四択","question":"食品工場の害虫管理として最も適切なものはどれか。","options":[{"key":"A","text":"夜間に虫が出ても製品へ影響しないので記録しない"},{"key":"B","text":"侵入防止、清掃、発生状況の監視、安全な駆除を組み合わせて管理する"},{"key":"C","text":"虫を見つけたときだけ食品の近くで殺虫剤を大量に散布する"},{"key":"D","text":"捕獲器を置けば、侵入口や餌になる汚れは確認しない"}],"correct":["B"],"conclusion":"害虫管理は、侵入・生息・餌を防ぎ、監視と安全な防除を組み合わせる。","explanation":"ドアや配管周りの隙間、排水、廃棄物、こぼれた原料などを管理し、発生状況を記録する。薬剤を使用する場合は、食品や食品接触面を汚染しない方法で行う。","wrongReason":"Cは薬剤汚染の危険がある。Dは発生原因を放置している。Aは傾向分析と製品影響の確認ができない。","example":"捕獲数が増えた区域では、扉の隙間、排水口、原料こぼれ、清掃状態を確認して原因を除く。","terms":"害虫管理、防虫、防鼠","process":"全工程","hazard":"生物的・化学的・物理的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q030","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"設備・器具の保守","difficulty":"レベル2","format":"現場判断","question":"製造終了後、樹脂製スクレーパーの先端が欠けていることに気付きました。最初に行うべき対応として最も適切なものはどれか。","options":[{"key":"A","text":"次回の製造前に新品へ交換するだけ"},{"key":"B","text":"欠けた部分が小さいので記録しない"},{"key":"C","text":"金属検出機を通過していれば問題ないと判断する"},{"key":"D","text":"影響した可能性のある製品を特定・保留し、欠片の捜索と製品影響を確認する"}],"correct":["D"],"conclusion":"器具の欠損が見つかったら、製品への混入可能性を評価して対象品を管理する。","explanation":"保守点検は故障を直すだけではなく、部品や器具の欠損による異物混入を防ぐ管理でもある。いつ欠けたか、どの製品へ影響したか、後工程で検出可能かを確認し、必要な処置を行う。","wrongReason":"Aは既に製造した製品を評価していない。Bは追跡できない。Cは樹脂片を金属検出機で検出できるとは限らない。","example":"始業・終業時に器具の形状と数量を確認し、欠損時の保留範囲を決めておく。","terms":"保守点検、器具管理、異物混入","process":"製造・保守","hazard":"物理的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q031","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"先入先出と保管管理","difficulty":"レベル1","format":"○×","question":"原材料を先入先出で使用していても、保存温度、使用期限、包装の破損を確認する必要がある。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["A"],"conclusion":"先入先出は有効な在庫管理だが、温度・期限・包装状態などの確認も必要である。","explanation":"先入先出だけでは、温度逸脱、期限切れ、包装破損、汚染を検知できない。使用前に原料の状態と保管条件を確認する。","wrongReason":"Bは、在庫順序だけで原料の安全性と使用可否を判断できると誤解している。","example":"入庫日の古さだけでなく、消費期限、温度記録、漏れや膨張、開封状態を確認して使用可否を判断する。","terms":"FIFO、期限管理、保管温度","process":"受入れ・保管","hazard":"共通","scope":"製品・保管条件により異なる","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q032","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"アレルゲン管理","difficulty":"レベル2","format":"複数選択","question":"アレルゲンを含む製品から、含まない製品へ同じラインを切り替える際に必要な対応をすべて選んでください。","options":[{"key":"A","text":"正しい包材・表示へ切り替わったことを確認する"},{"key":"B","text":"対象アレルゲンと使用原料を確認する"},{"key":"C","text":"前製品の残りを少量混ぜて使い切る"},{"key":"D","text":"定めた洗浄を行い、必要に応じて有効性を確認する"}],"correct":["A","B","D"],"conclusion":"アレルゲンの残留と表示間違いの両方を防ぐ必要がある。","explanation":"アレルゲン管理では、原料の識別、保管、投入、製造順序、洗浄、再加工、包材・ラベル照合などを一連で管理する。洗浄方法が残留を十分に除去できるかは、製品と設備に応じて確認する。","wrongReason":"Cは、アレルゲンを含まない製品へ意図せず混入させる行為になる。","example":"ラインクリアランスで原料、半製品、包材、ラベルを回収し、洗浄後にチェックリストで切替状態を確認する。","terms":"アレルゲン、ライン切替、表示確認","process":"切替・包装","hazard":"化学的危害","scope":"対象国の表示対象アレルゲンも確認","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q033","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"結露・設備周辺からの汚染","difficulty":"レベル2","format":"現場判断","question":"加熱済みの食品を冷却している上部配管から結露水が落ちているのを発見しました。最も適切な対応はどれか。","options":[{"key":"A","text":"食品へ直接落ちていなければ記録しない"},{"key":"B","text":"製品を保護・区分し、結露の発生源を止め、影響範囲を評価して清掃する"},{"key":"C","text":"結露水を布で拭くだけで、原因は調べない"},{"key":"D","text":"水なので安全と判断して製造を続ける"}],"correct":["B"],"conclusion":"結露水は微生物や汚れを運ぶ可能性があるため、製品保護と原因除去が必要である。","explanation":"配管や天井の結露は、表面の汚れや微生物を食品・包装・食品接触面へ運ぶ可能性がある。露出食品を保護し、影響した製品を特定し、断熱、換気、温度差、漏れなどの原因を修正する。","wrongReason":"A・Dは水の汚染可能性を無視している。Cは再発防止と製品評価が不足している。","example":"結露が発生した時間を記録し、その下を通過した製品ロットを保留して品質管理が処置を判断する。","terms":"結露、環境衛生、交差汚染","process":"加熱後・冷却・包装","hazard":"生物的・化学的危害","scope":"国際共通の原則","sourceId":"S004","sourceUrl":"https://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q034","categoryCode":"B","category":"一般衛生管理・GHP","subtheme":"廃棄物管理","difficulty":"レベル1","format":"四択","question":"露出した食品のすぐ横に、ふたのない廃棄物容器が置かれています。最も適切な対応はどれか。","options":[{"key":"A","text":"容器の上に段ボールを置くだけでよい"},{"key":"B","text":"終業時に捨てるので、そのままでよい"},{"key":"C","text":"臭いがなければ問題ない"},{"key":"D","text":"食品から分離し、適切な容器・搬出頻度・清掃方法で管理する"}],"correct":["D"],"conclusion":"廃棄物は、食品汚染や害虫発生の原因にならないよう分離して管理する。","explanation":"廃棄物やこぼれた食品は、微生物、異物、害虫の発生源になり得る。食品や食品接触面から離し、用途に合った容器を使用し、あふれる前に搬出し、容器と周辺を清掃する。","wrongReason":"B・Cは汚染と害虫のリスクを無視している。Aは適切な密閉・清掃・分離にならない。","example":"廃棄物の搬出経路が清潔区域を横切らないようにし、回収後は床や容器を清掃する。","terms":"廃棄物管理、清掃、害虫管理","process":"全工程","hazard":"生物的・物理的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第2回作成"},{"id":"Q035","categoryCode":"C","category":"危害分析と危害評価","subtheme":"生物的危害","difficulty":"レベル1","format":"四択","question":"原料の鶏肉にサルモネラ属菌が存在する可能性を評価しています。この危害の分類として最も適切なものはどれか。","options":[{"key":"A","text":"生物的危害"},{"key":"B","text":"物理的危害"},{"key":"C","text":"品質上の問題だけ"},{"key":"D","text":"化学的危害"}],"correct":["A"],"conclusion":"病原性細菌は生物的危害として評価する。","explanation":"生物的危害には、病原性細菌、ウイルス、寄生虫などが含まれる。原料に存在する可能性だけでなく、工程中の増殖、残存、加熱後の再汚染も工程ごとに検討する。","wrongReason":"Dは洗浄剤やアレルゲンなど、Bは金属片やガラス片などの分類である。Cは食品安全上の健康被害を無視している。","example":"生肉の受入れ、保管、解凍、加熱の各工程で、病原性細菌が増える・残る条件と管理方法を確認する。","terms":"生物的危害、病原性細菌、サルモネラ","process":"受入れ・保管・加熱","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q036","categoryCode":"C","category":"危害分析と危害評価","subtheme":"アレルゲン危害","difficulty":"レベル1","format":"四択","question":"アレルゲンを含む原料を使用したのに、誤ったラベルを貼り、アレルゲン表示が抜けました。HACCPの危害分類として最も適切なものはどれか。","options":[{"key":"A","text":"生物的危害"},{"key":"B","text":"物理的危害"},{"key":"C","text":"化学的危害"},{"key":"D","text":"表示の見た目だけの問題"}],"correct":["C"],"conclusion":"未表示アレルゲンは化学的危害として評価する。","explanation":"食品アレルゲンは、感受性のある人に健康被害を起こす可能性があるため、一般に化学的危害として扱う。原料混入だけでなく、交差接触や包材・ラベルの取り違えも評価する。","wrongReason":"Aは微生物など、Bは異物などの分類である。Dは健康被害につながる表示不備を単なる外観問題としている。","example":"製品切替時に残った包材を回収し、製品名、原料、アレルゲン表示、ロットを照合してから包装を再開する。","terms":"アレルゲン、交差接触、表示確認","process":"原料投入・切替・包装","hazard":"化学的危害","scope":"対象国の表示対象アレルゲンを別途確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q037","categoryCode":"C","category":"危害分析と危害評価","subtheme":"食品安全と品質の区別","difficulty":"レベル1","format":"四択","question":"次のうち、食品安全上の危害として優先して評価すべきものはどれか。","options":[{"key":"A","text":"外箱の印刷色が少し異なる"},{"key":"B","text":"硬質プラスチック片が製品へ混入する可能性がある"},{"key":"C","text":"焼き色が予定より薄い"},{"key":"D","text":"製品の重量が目標より少し軽い"}],"correct":["B"],"conclusion":"健康被害につながる異物混入は、品質のばらつきとは分けて評価する。","explanation":"危害分析では、人の健康に悪影響を与える可能性のある生物的・化学的・物理的要因を対象にする。色、重量、印刷などの品質問題も重要だが、食品安全危害とは区別して管理する。","wrongReason":"A・C・Dは通常は品質や規格の問題であり、提示条件だけでは健康被害を示していない。Bは口腔内のけがなどにつながり得る。","example":"樹脂スクレーパーの欠けが見つかった場合、品質不良として処理するだけでなく、物理的危害として対象製品を保留・評価する。","terms":"食品安全、品質、物理的危害","process":"製造・包装","hazard":"物理的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q038","categoryCode":"C","category":"危害分析と危害評価","subtheme":"危害と管理手段","difficulty":"レベル2","format":"四択","question":"「危害」と「管理手段」の組合せとして正しいものはどれか。","options":[{"key":"A","text":"加熱装置が生物的危害、病原菌が管理手段"},{"key":"B","text":"洗浄記録が化学的危害、洗浄剤残留が管理手段"},{"key":"C","text":"金属検出機が危害、金属片が管理手段"},{"key":"D","text":"金属片が危害、金属検出や部品管理が管理手段"}],"correct":["D"],"conclusion":"危害そのものと、それを防止・除去・低減する管理手段を分けて考える。","explanation":"危害は健康被害を起こし得る要因であり、管理手段はその危害を予防、除去、または許容可能な水準まで低減するための行動や設備である。","wrongReason":"A・B・Cは危害と管理手段を逆にしている。設備や記録は管理を支援するものであり、それ自体が対象危害とは限らない。","example":"ボルト脱落という物理的危害に対し、緩み止め、始業点検、部品本数管理、検出工程などを組み合わせる。","terms":"危害、管理手段、予防","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q039","categoryCode":"C","category":"危害分析と危害評価","subtheme":"重要な危害の評価","difficulty":"レベル2","format":"複数選択","question":"危害を重要なものとして管理すべきか評価する際、考慮すべき項目をすべて選んでください。","options":[{"key":"A","text":"発生した場合の健康影響の重大性"},{"key":"B","text":"その危害が発生する可能性"},{"key":"C","text":"商品の販売価格"},{"key":"D","text":"包装デザインの好み"}],"correct":["A","B"],"conclusion":"発生可能性と重大性を中心に、用途や消費者条件も踏まえて評価する。","explanation":"危害分析では、合理的に予想される危害を洗い出し、発生する可能性と健康影響の重大性を評価する。乳幼児、高齢者、免疫が低下した人などが主な消費者であれば、評価が変わる場合がある。","wrongReason":"Dは包装デザイン、Cは販売価格であり、食品安全上の危害評価とは直接関係しない。","example":"同じ加熱済み食品でも、一般消費者向けか病院食向けかによって、病原微生物への許容や管理の厳しさを再検討する。","terms":"発生可能性、重大性、意図する用途、消費者","process":"危害分析","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q040","categoryCode":"C","category":"危害分析と危害評価","subtheme":"意図する用途と消費者","difficulty":"レベル3","format":"現場判断","question":"同じ製品を、健康な成人向けから高齢者施設向けへ変更する計画があります。危害分析で最も適切な対応はどれか。","options":[{"key":"A","text":"製造設備が同じなので見直さない"},{"key":"B","text":"販売先だけの変更なので記録しない"},{"key":"C","text":"意図する用途と対象消費者を更新し、危害の重大性や管理手段を再評価する"},{"key":"D","text":"ラベルの色だけ変更する"}],"correct":["C"],"conclusion":"対象消費者が変われば、危害分析も見直す必要がある。","explanation":"HACCPでは、製品の意図する用途と想定消費者を明確にする。重症化しやすい人が主な消費者になる場合、原料、加熱後汚染、保存、喫食方法などの危害評価と管理方法を再確認する。","wrongReason":"A・Bは消費者条件が食品安全評価へ与える影響を無視している。Dだけでは危害分析の見直しにならない。","example":"高齢者施設向けの冷蔵調理品では、加熱後の取扱い、冷却、保存期間、再加熱指示などを再評価する。","terms":"意図する用途、対象消費者、感受性集団","process":"製品設計・危害分析","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q041","categoryCode":"C","category":"危害分析と危害評価","subtheme":"危害分析の基本手順","difficulty":"レベル2","format":"手順並べ替え","question":"危害分析の基本的な流れとして、次の項目を適切な順序に並べてください。A：必要な管理手段を検討する　B：工程ごとに潜在的な危害を洗い出す　C：発生可能性と重大性を評価する　D：判断理由を記録する","options":[{"key":"A","text":"A→B→C→D"},{"key":"B","text":"C→B→D→A"},{"key":"C","text":"B→A→D→C"},{"key":"D","text":"B→C→A→D"}],"correct":["D"],"conclusion":"危害を洗い出し、重要性を評価し、管理手段を検討して根拠を残す。","explanation":"危害分析では、原材料と各工程で起こり得る危害を列挙し、その重要性を評価する。重要な危害には管理手段を対応させ、採用・不採用の判断理由を記録する。","wrongReason":"A・B・Dの並びは、危害を十分に特定・評価する前に管理手段や結論を決めている。","example":"フローダイアグラムの各工程を順に確認し、危害分析表へ危害、評価、管理手段、判断理由を記入する。","terms":"危害分析表、発生可能性、重大性、管理手段","process":"危害分析","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q042","categoryCode":"C","category":"危害分析と危害評価","subtheme":"加熱後の再汚染","difficulty":"レベル3","format":"現場判断","question":"加熱で病原菌を十分に低減した食品を、洗浄不十分な搬送ベルトへ移しています。危害分析で最も重要な見方はどれか。","options":[{"key":"A","text":"再加熱工程がないため、ベルトからの再汚染を重要な危害として評価する"},{"key":"B","text":"加熱済みなので、その後の微生物危害は考えなくてよい"},{"key":"C","text":"ベルトの色が製品と違えば安全である"},{"key":"D","text":"製品の味に変化がなければ問題ない"}],"correct":["A"],"conclusion":"危害を除去した後の再汚染も、工程別に評価する。","explanation":"加熱で原料由来の病原微生物を低減しても、加熱後の設備、人、空気、水、器具などから再汚染する可能性がある。後工程で除去できない場合は、重要な危害となり得る。","wrongReason":"Bは工程後半の汚染経路を無視している。C・Dは衛生状態や安全性の根拠にならない。","example":"加熱後区域の専用化、ベルト洗浄の有効性確認、作業者動線の分離、環境モニタリングなどを検討する。","terms":"再汚染、加熱後区域、交差汚染","process":"加熱後・搬送・包装","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q043","categoryCode":"C","category":"危害分析と危害評価","subtheme":"微生物の増殖","difficulty":"レベル3","format":"現場判断","question":"加熱済み食品を大量に深い容器へ入れたため、中心部の冷却が遅れています。危害分析として最も適切な説明はどれか。","options":[{"key":"A","text":"表面温度だけ低ければ中心部は確認しなくてよい"},{"key":"B","text":"加熱済みなので微生物は増殖しない"},{"key":"C","text":"容器が重いことだけを危害として評価する"},{"key":"D","text":"冷却中に生き残った菌や再汚染した菌が増殖する可能性を評価する"}],"correct":["D"],"conclusion":"冷却工程では、時間と温度の経過による微生物増殖を評価する。","explanation":"加熱後でも芽胞形成菌が生き残る場合や、取扱い中に再汚染する場合がある。食品の量、厚さ、容器、冷却能力、中心温度の推移を踏まえ、増殖や毒素産生の可能性を評価する。","wrongReason":"Bは加熱後の残存・再汚染を無視している。Cは作業性の問題に限定している。Aは最も冷えにくい部分を確認していない。","example":"浅い容器への小分け、急速冷却機の使用、中心部測定位置の設定などを管理手段として検討する。","terms":"冷却、微生物増殖、中心温度","process":"冷却","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q044","categoryCode":"C","category":"危害分析と危害評価","subtheme":"潤滑油・化学物質","difficulty":"レベル3","format":"現場判断","question":"食品の真上にある駆動部から潤滑油がにじんでいます。危害分析と初動として最も適切なものはどれか。","options":[{"key":"A","text":"油の色が透明なら問題ない"},{"key":"B","text":"化学的危害として混入可能性を評価し、製品を保護・区分して漏れを止める"},{"key":"C","text":"製造後に外箱を交換すればよい"},{"key":"D","text":"食品用潤滑油なら無制限に混入しても安全なので続行する"}],"correct":["B"],"conclusion":"食品用潤滑油であっても、意図しない混入は管理対象になる。","explanation":"潤滑油、洗浄剤、冷媒などは化学的危害になり得る。食品グレードの選定は対策の一つだが、漏れ防止、滴下防止、使用量管理、保守、影響製品の評価が必要である。","wrongReason":"Dは食品用という表示を無制限な混入許可と誤解している。Aは安全性の根拠にならない。Cは製品汚染を解決しない。","example":"漏れ発見時刻から対象ロットを特定して保留し、シール交換後に清掃・点検してから再開する。","terms":"潤滑油、化学的危害、予防保全","process":"製造・保守","hazard":"化学的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q045","categoryCode":"C","category":"危害分析と危害評価","subtheme":"ガラス・脆性材料","difficulty":"レベル2","format":"四択","question":"露出食品の上にあるガラス製照明カバーが割れました。危害分析上、最も適切な考え方はどれか。","options":[{"key":"A","text":"ガラス片は物理的危害として、飛散範囲と影響製品を評価する"},{"key":"B","text":"照明は設備なので食品危害にはならない"},{"key":"C","text":"小さな破片は目に見えないため記録しない"},{"key":"D","text":"床だけ清掃すれば製品確認は不要"}],"correct":["A"],"conclusion":"ガラス破損は、飛散と製品混入の範囲を物理的危害として評価する。","explanation":"ガラスや脆性プラスチックの破損は、けがにつながる異物混入を起こし得る。破損場所、高さ、製品の露出状態、飛散範囲、時間帯を確認し、保留・捜索・清掃・再開判定を行う。","wrongReason":"B・C・Dは製品への飛散可能性と追跡を無視している。","example":"ガラス・脆性材料台帳を作り、定期点検と破損時の隔離範囲・再開条件を定める。","terms":"ガラス管理、脆性材料、物理的危害","process":"製造・包装","hazard":"物理的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q046","categoryCode":"C","category":"危害分析と危害評価","subtheme":"再加工品とアレルゲン","difficulty":"レベル3","format":"複数選択","question":"アレルゲンを含む製品の再加工品を別製品へ戻す場合、危害分析で確認すべき項目をすべて選んでください。","options":[{"key":"A","text":"再加工品の識別と使用量を追跡できるか"},{"key":"B","text":"見た目が似ていれば製品名を確認しなくてよい"},{"key":"C","text":"交差接触や誤投入を防ぐ保管・投入方法があるか"},{"key":"D","text":"戻し先製品に同じアレルゲンが適切に表示されているか"}],"correct":["A","C","D"],"conclusion":"再加工品は、アレルゲン、識別、追跡、誤投入を一体で評価する。","explanation":"再加工品は原料と同様に危害を持ち込む可能性がある。含有アレルゲン、戻し先の表示、保管区分、使用期限、投入量、ロット追跡、誤投入防止を確認する。","wrongReason":"Bは外観だけで内容と適合性を判断しているため誤り。","example":"再加工品容器へ製品名、アレルゲン、製造日、ロット、使用可能な戻し先を明記し、投入時に照合する。","terms":"再加工、アレルゲン、トレーサビリティ","process":"再加工・原料投入","hazard":"化学的危害","scope":"対象国の表示対象アレルゲンを別途確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q047","categoryCode":"C","category":"危害分析と危害評価","subtheme":"仕入先保証と危害分析","difficulty":"レベル2","format":"○×","question":"原料の仕入先から検査成績書を受け取っていれば、自社でその原料の危害を分析する必要はない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"仕入先資料は重要な情報だが、自社工程での危害分析の代わりにはならない。","explanation":"検査成績書、規格書、監査結果などは危害分析の根拠になる。しかし、使用量、保管、加工、対象消費者、後工程、他原料との組合せは自社で異なるため、自社製品と工程に合わせて評価する。","wrongReason":"Aは仕入先資料の対象範囲と、自社での使用条件の違いを無視している。","example":"微生物規格がある香辛料でも、加熱せずに使用する製品では、自社工程での管理手段を別途検討する。","terms":"仕入先管理、検査成績書、原料規格","process":"受入れ・危害分析","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q048","categoryCode":"C","category":"危害分析と危害評価","subtheme":"変更時の危害分析見直し","difficulty":"レベル3","format":"現場判断","question":"同じ名称の原料ですが、仕入先を変更し、製造方法とアレルゲン取扱いが異なることが分かりました。最も適切な対応はどれか。","options":[{"key":"A","text":"原料名が同じなので既存の危害分析をそのまま使う"},{"key":"B","text":"価格だけ比較して採用する"},{"key":"C","text":"原料仕様、製造方法、危害情報、アレルゲン、輸送条件を確認し、危害分析を見直す"},{"key":"D","text":"初回製造後に問題が出た場合だけ確認する"}],"correct":["C"],"conclusion":"原料・仕入先・製法の変更は、危害分析を見直すきっかけになる。","explanation":"仕入先変更により、原料由来の微生物、薬剤、アレルゲン交差接触、異物、輸送・保管条件が変わる可能性がある。採用前に仕様と管理状況を確認し、必要な管理手段を更新する。","wrongReason":"A・Bは名称や価格だけで危害が同じと仮定している。Dは予防ではなく問題発生後の対応になっている。","example":"新規仕入先承認で、規格書、工程図、アレルゲン声明、検査方法、変更通知条件を確認する。","terms":"変更管理、仕入先変更、危害分析の見直し","process":"受入れ・変更管理","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q049","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"CCPの定義","difficulty":"レベル1","format":"四択","question":"CCP（重要管理点）の説明として最も適切なものはどれか。","options":[{"key":"A","text":"機械が自動停止するすべての箇所"},{"key":"B","text":"工場内で毎日清掃するすべての場所"},{"key":"C","text":"重要な食品安全危害を予防、除去、または許容可能な水準まで低減するため、管理が不可欠な工程"},{"key":"D","text":"品質不良を見つける最終検査だけ"}],"correct":["C"],"conclusion":"CCPは、重要な危害の管理に不可欠な工程である。","explanation":"CCPは工程名や設備名だけで決まるものではない。危害分析で重要と評価した危害に対し、その工程での管理が不可欠かを判断して設定する。","wrongReason":"Bは一般衛生管理を含み、すべてがCCPではない。Dは品質検査に限定している。Aは自動停止の有無だけで判断している。","example":"加熱工程をCCPにする場合でも、対象危害、管理基準、監視方法、逸脱時対応まで具体化する。","terms":"CCP、重要管理点、管理手段","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q050","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"CCPを設定しない場合","difficulty":"レベル3","format":"四択","question":"危害分析の結果、合理的に予想される危害はGHPで十分に管理でき、CCPで管理すべき重要な危害は特定されませんでした。最も適切な対応はどれか。","options":[{"key":"A","text":"危害分析そのものを削除する"},{"key":"B","text":"CCPを無理に作らず、判断根拠を記録し、GHPの実施と有効性を維持・確認する"},{"key":"C","text":"CCPがないので衛生管理を中止する"},{"key":"D","text":"クイズや監査で見栄えが悪いので、必ず1か所をCCPにする"}],"correct":["B"],"conclusion":"CCPの数を先に決めず、危害分析の結果に基づいて判断する。","explanation":"すべての工程にCCPが必要とは限らない。合理的に予想される危害がGHPで十分に管理でき、CCP管理が不要と判断した場合は、その根拠と管理方法を文書化し、継続して確認する。","wrongReason":"Dは結論ありきでCCPを設定している。A・Cは危害分析と衛生管理を放棄している。","example":"低リスク工程でも、清掃、温度、仕入先、交差汚染防止などのGHPを記録・検証し、変更時に再評価する。","terms":"CCP、GHP、判断根拠","process":"危害分析・計画作成","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q051","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"CCP決定ツール","difficulty":"レベル2","format":"四択","question":"CCP決定のためのデシジョンツリーについて、最も適切な説明はどれか。","options":[{"key":"A","text":"質問へ答えれば、製品や工程を確認せず自動的に正解が出る"},{"key":"B","text":"法律上、世界中で同じ形式の使用が必須である"},{"key":"C","text":"一度使えば工程変更後も見直す必要がない"},{"key":"D","text":"危害分析と専門的判断を支援する道具であり、工程条件や管理手段の確認が必要である"}],"correct":["D"],"conclusion":"デシジョンツリーは判断を助ける道具であり、危害分析の代わりではない。","explanation":"CCPの決定には、危害の重要性、管理手段、前後工程、失敗時の影響などを総合的に考える。デシジョンツリーは考え方を整理するが、回答の根拠を確認する必要がある。","wrongReason":"Aは機械的な判定に依存している。Bは各国・組織の手法差を無視している。Cは変更管理を無視している。","example":"加熱、冷却、金属検出を名称だけでCCPにせず、対象危害と後工程の有無を確認して判断する。","terms":"デシジョンツリー、CCP決定、専門的判断","process":"計画作成","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q052","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"管理基準の設定","difficulty":"レベル2","format":"四択","question":"CCPの管理基準として最も適切なものはどれか。","options":[{"key":"A","text":"対象危害を管理できる根拠に基づき、温度・時間・pHなどで合否を判断できる値"},{"key":"B","text":"毎日同じ製品色になること"},{"key":"C","text":"十分に加熱できたように見えること"},{"key":"D","text":"担当者が安全だと感じること"}],"correct":["A"],"conclusion":"管理基準は、安全側と不安全側を判定できる具体的な基準にする。","explanation":"管理基準はCCPが管理下にあるかを判断する境界であり、科学的・技術的根拠に基づく。値は製品、危害、工程、法令や顧客要求に応じて設定する。","wrongReason":"C・Dは主観的で再現性がない。Bは品質基準であり、提示条件だけでは食品安全危害の管理基準ではない。","example":"加熱では対象菌と製品特性に応じた温度・時間、酸性化ではpHなど、危害との関係を説明できる指標を使用する。","terms":"管理基準、クリティカルリミット、科学的根拠","process":"CCP","hazard":"共通","scope":"具体的数値は製品・危害・法令ごとに確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q053","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"社内警戒値と管理基準","difficulty":"レベル3","format":"四択","question":"CCPの管理基準より安全側に、社内の警戒値を設定する目的として最も適切なものはどれか。","options":[{"key":"A","text":"記録する値を少なくするため"},{"key":"B","text":"科学的根拠を不要にするため"},{"key":"C","text":"管理基準へ達する前に調整し、逸脱を予防するため"},{"key":"D","text":"管理基準を超えても合格扱いにするため"}],"correct":["C"],"conclusion":"警戒値は、管理基準から外れる前に工程を調整するために使える。","explanation":"管理基準は合否の境界である。これより安全側の運用値や警戒値を設けると、工程変動を早く検知して調整できる。ただし、警戒値を管理基準の代わりにしてはならない。","wrongReason":"Dは基準外製品を合格扱いにしている。A・Bは監視と根拠を弱めている。","example":"加熱温度が管理基準へ近づいた段階で警報を出し、蒸気圧や搬送速度を調整する。","terms":"管理基準、運用限界、警戒値","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q054","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"モニタリング計画","difficulty":"レベル2","format":"複数選択","question":"CCPのモニタリング手順に明確にしておくべき項目をすべて選んでください。","options":[{"key":"A","text":"誰が確認するかを決めず、記録場所も毎回変える"},{"key":"B","text":"異常が出ても記録を残さない方法"},{"key":"C","text":"何を測定・観察するか"},{"key":"D","text":"どの方法と頻度で確認するか"}],"correct":["C","D"],"conclusion":"モニタリングは、対象・方法・頻度・担当・記録を具体化する。","explanation":"モニタリングはCCPが管理下にあるかを時間内に判断できるよう設計する。測定項目、方法、機器、頻度、担当者、記録、異常時の連絡先を明確にする。","wrongReason":"Aは担当と記録を不明確にし、Bは追跡と逸脱対応を不可能にする。","example":"加熱CCPなら、測定位置、温度・時間、連続記録か手動確認か、確認担当、記録様式を計画書に記載する。","terms":"モニタリング、頻度、担当者、記録","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q055","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"連続モニタリング","difficulty":"レベル2","format":"四択","question":"連続式加熱機で温度を自動記録しています。最も適切な運用はどれか。","options":[{"key":"A","text":"一日の平均温度だけを確認する"},{"key":"B","text":"記録の連続性、センサー状態、警報、製品の通過条件を確認し、定めた頻度で記録をレビューする"},{"key":"C","text":"異常値は自動で削除する"},{"key":"D","text":"自動記録があるので、人は一切確認しない"}],"correct":["B"],"conclusion":"自動記録でも、測定系と記録内容が正しく機能しているか確認する。","explanation":"連続モニタリングは工程状態を詳細に把握できるが、センサー故障、記録欠落、時刻ずれ、バイパス、製品滞留時間などを別途確認する必要がある。","wrongReason":"Dは自動化を無条件に信頼している。Aは一時的な逸脱を見逃す。Cは記録改ざんになる。","example":"製造開始時と定期的に表示値を基準計器と比較し、チャートの欠測や警報履歴を確認する。","terms":"連続モニタリング、自動記録、警報","process":"加熱・冷却","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q056","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"非連続モニタリング頻度","difficulty":"レベル3","format":"現場判断","question":"CCPを1時間ごとに手動測定していますが、工程条件が15分で大きく変動する可能性があります。最も適切な対応はどれか。","options":[{"key":"A","text":"変動速度と不合格製品の範囲を踏まえ、逸脱を時間内に検知できる頻度へ見直す"},{"key":"B","text":"1時間ごとのままにし、平均値だけ記録する"},{"key":"C","text":"異常が起きた日だけ頻度を増やす"},{"key":"D","text":"測定担当者の都合だけで頻度を決める"}],"correct":["A"],"conclusion":"非連続監視の頻度は、逸脱を早く検知し影響範囲を限定できるよう設定する。","explanation":"手動測定では測定間に逸脱が起きる可能性がある。工程の安定性、変動速度、生産量、異常時に保留する製品量、測定方法の精度を考慮して頻度を決める。","wrongReason":"Bは短時間の変動を見逃す。Cは予防的管理にならない。Dは食品安全上の根拠がない。","example":"高速ラインでは、測定間隔が長いほど逸脱時に保留するロットが大きくなるため、連続監視や頻度増加を検討する。","terms":"非連続モニタリング、確認頻度、影響範囲","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q057","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"モニタリング担当者","difficulty":"レベル2","format":"四択","question":"CCPのモニタリング担当者として必要な条件はどれか。","options":[{"key":"A","text":"製品の味を判断できることだけ"},{"key":"B","text":"記録を後でまとめて記憶から書けること"},{"key":"C","text":"役職が高いことだけ"},{"key":"D","text":"手順、管理基準、異常時の行動を理解し、正確に測定・記録できること"}],"correct":["D"],"conclusion":"担当者は、基準と測定方法、逸脱時の行動を理解している必要がある。","explanation":"モニタリング担当者には、適切な教育、測定技術、記録能力、逸脱時に直ちに報告・行動できる権限や連絡手順が必要である。","wrongReason":"Cは役職だけ、Aは官能評価だけに依存している。Bは同時記録の原則と正確性を損なう。","example":"交代勤務者も含め、温度計の使用、測定位置、基準外時のライン停止と製品保留を訓練する。","terms":"教育訓練、モニタリング担当、記録","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q058","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"逸脱時の改善措置","difficulty":"レベル3","format":"複数選択","question":"CCPが管理基準から外れた場合、改善措置に含めるべき対応をすべて選んでください。","options":[{"key":"A","text":"記録を削除して通常運転に見せる"},{"key":"B","text":"影響を受けた製品を特定し、安全性を評価して処置する"},{"key":"C","text":"原因を調べ、必要に応じて再発防止を行う"},{"key":"D","text":"工程を管理下へ戻す"}],"correct":["B","C","D"],"conclusion":"逸脱時は、工程と製品の両方を管理し、原因と再発防止まで扱う。","explanation":"改善措置は、逸脱の原因を修正して工程を管理下へ戻すことと、影響製品が不安全に流出しないよう評価・処置することを含む。実施内容を記録し、必要に応じて計画を見直す。","wrongReason":"Aは追跡性を失わせ、食品安全管理を破壊する。","example":"加熱不足ならラインを停止・調整し、逸脱時間帯の製品を保留して、再加熱、検査、廃棄などを権限者が判断する。","terms":"逸脱、改善措置、製品保留、原因調査","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q059","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"逸脱製品の処置","difficulty":"レベル3","format":"現場判断","question":"CCPの管理基準を外れた製品について、「基準外だからすべて即廃棄」とだけ定めています。最も適切な考え方はどれか。","options":[{"key":"A","text":"見た目が正常なら無条件で出荷する"},{"key":"B","text":"担当者ごとに自由に決める"},{"key":"C","text":"廃棄以外の処置は絶対に認められない"},{"key":"D","text":"安全性を確保できる科学的根拠と承認手順があれば、再処理、用途変更、廃棄などから適切な処置を選ぶ"}],"correct":["D"],"conclusion":"逸脱製品の処置は、安全性を確保できる根拠と権限に基づいて決める。","explanation":"廃棄は有効な処置の一つだが、製品・危害によっては科学的に妥当な再加熱や再処理が可能な場合もある。処置基準、判断者、追跡、記録を明確にする。完成品の抜き取り検査だけで安全を保証できるとは限らない。","wrongReason":"Cは製品・危害ごとの合理的な選択肢を排除している。A・Bは安全性の根拠と一貫性がない。","example":"冷却逸脱品を再加熱できるかは、経過時間、温度履歴、対象菌、品質、法令や顧客条件を確認して判断する。","terms":"製品処置、再処理、廃棄、評価","process":"CCP逸脱後","hazard":"共通","scope":"処置可否は製品・危害・法令・顧客条件で異なる","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q060","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"製造再開条件","difficulty":"レベル3","format":"現場判断","question":"CCP逸脱の原因となった温度センサーを交換しました。製造再開前に最も適切な確認はどれか。","options":[{"key":"A","text":"新品なので確認せず再開する"},{"key":"B","text":"交換後の精度、設定、警報、記録、実工程での動作を確認し、対象製品の処置を決めてから再開する"},{"key":"C","text":"画面が点灯すれば再開する"},{"key":"D","text":"過去の逸脱記録を削除して再開する"}],"correct":["B"],"conclusion":"部品交換だけでなく、管理機能が正しく復旧したことを確認して再開する。","explanation":"センサー交換後は、校正または精度確認、取付位置、配線、設定値、警報、記録、インターロックを確認する。さらに、交換前の影響製品を特定・処置する必要がある。","wrongReason":"A・Cは機能の妥当性を確認していない。Dは原因分析と追跡を妨げる。","example":"基準温度計との比較、模擬警報試験、記録時刻の確認を行い、権限者が再開を承認する。","terms":"再開判定、校正、警報、インターロック","process":"保守後・CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q061","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"モニタリングと検証","difficulty":"レベル2","format":"四択","question":"モニタリングと検証の違いとして最も適切なものはどれか。","options":[{"key":"A","text":"モニタリングは日常的にCCPの状態を確認し、検証は計画どおり実施され有効に機能しているかを別の活動で確認する"},{"key":"B","text":"どちらも同じ意味で、区別する必要はない"},{"key":"C","text":"検証は異常値を消す作業である"},{"key":"D","text":"モニタリングは年1回だけ行う"}],"correct":["A"],"conclusion":"モニタリングは日常の管理確認、検証はシステムが意図どおり機能しているかの確認である。","explanation":"モニタリングは管理基準からの逸脱を時間内に検知する活動である。検証には、記録レビュー、校正、観察、サンプリング、内部点検などが含まれる。","wrongReason":"Bは役割の違いを無視している。Cは不正な記録操作である。Dは日常管理にならない。","example":"作業者が毎ロット温度を記録し、品質管理者が記録の完全性と逸脱処置を定期レビューする。","terms":"モニタリング、検証、記録レビュー","process":"CCP","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q062","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"妥当性確認","difficulty":"レベル3","format":"四択","question":"妥当性確認（バリデーション）の説明として最も適切なものはどれか。","options":[{"key":"A","text":"設備の外観を清掃すること"},{"key":"B","text":"記録用紙の空欄を後で埋める"},{"key":"C","text":"計画した管理手段と管理基準が、対象危害を実際に制御できることを科学的・技術的根拠で示す"},{"key":"D","text":"毎日の測定値を記録することだけ"}],"correct":["C"],"conclusion":"妥当性確認は、設計した管理方法で危害を制御できることを示す活動である。","explanation":"妥当性確認では、科学文献、法令、専門家資料、設備試験、製品試験などを用い、管理手段と管理基準の組合せが目的を達成できるか確認する。導入前後や重要変更時に見直す。","wrongReason":"B・Dは記録やモニタリングの一部であり、制御能力の根拠を示していない。Aは清掃作業である。","example":"連続加熱機では、最も冷えやすい条件ではなく、最も厳しい製品量・初期温度・搬送速度で必要な加熱効果を確認する。","terms":"妥当性確認、バリデーション、科学的根拠","process":"計画作成・変更時","hazard":"共通","scope":"国際共通の原則","sourceId":"S006","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q063","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"測定器の校正と影響評価","difficulty":"レベル3","format":"現場判断","question":"CCPで使用する温度計が校正確認で許容誤差を外れていました。最も適切な対応はどれか。","options":[{"key":"A","text":"表示値を正しい値へ書き換えるだけ"},{"key":"B","text":"誤差方向に関係なく、すべて安全だったと判断する"},{"key":"C","text":"温度計を是正し、前回正常確認以降の記録と製品への影響を評価する"},{"key":"D","text":"現在の温度計だけ調整し、過去の製品は確認しない"}],"correct":["C"],"conclusion":"測定器のずれが見つかったら、機器だけでなく過去の判定への影響も確認する。","explanation":"校正外れでは、誤差の方向と大きさ、前回正常確認時点、対象ロット、他の記録、工程余裕を確認する。必要に応じて製品を保留・評価し、機器を調整・交換する。","wrongReason":"Dは過去の判定影響を無視している。Aは記録改ざんになる。Bは誤差方向と工程余裕を評価していない。","example":"実際より高く表示していた場合、記録上は合格でも実温度が基準未満だった可能性があるため、対象期間を追跡する。","terms":"校正、精度確認、影響評価","process":"CCP・測定器","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q064","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"記録レビュー","difficulty":"レベル3","format":"現場判断","question":"CCP記録はすべて基準内ですが、同じ筆跡で一日の終わりにまとめて記入された疑いがあります。検証として最も適切な対応はどれか。","options":[{"key":"A","text":"原記録、時刻、自動ログ、作業状況を確認し、同時記録と手順遵守を評価する"},{"key":"B","text":"数値が基準内なので何もしない"},{"key":"C","text":"記録用紙を廃棄する"},{"key":"D","text":"担当者へ次回から気を付けるよう口頭で伝えるだけ"}],"correct":["A"],"conclusion":"基準内の数値だけでなく、記録が実際の監視を反映しているか確認する。","explanation":"記録レビューでは、記入時刻、署名、欠測、訂正、逸脱処置、機器ログとの一致を確認する。後書きや架空記録は、CCPが実際に監視されていなかった可能性を示す。","wrongReason":"Bは記録の信頼性を確認していない。Cは証拠を失わせる。Dは原因・影響評価と再発防止が不足する。","example":"PLC履歴と紙記録の時刻を照合し、監視が行われていない時間帯の製品を特定して評価する。","terms":"記録レビュー、データ完全性、同時記録","process":"CCP・検証","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q065","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"重要変更時の再評価","difficulty":"レベル4","format":"現場判断","question":"加熱機を大型化し、製品厚さ、搬送速度、温度センサー位置も変更します。既存HACCP計画の扱いとして最も適切なものはどれか。","options":[{"key":"A","text":"機械メーカーのカタログにHACCP対応とあればそのまま使う"},{"key":"B","text":"設定温度の数値が同じなら見直さない"},{"key":"C","text":"変更後に事故が起きた場合だけ見直す"},{"key":"D","text":"危害分析、CCP、管理基準、モニタリング、妥当性確認を変更前に再評価する"}],"correct":["D"],"conclusion":"工程能力や測定条件が変わる重要変更では、HACCP計画を再評価する。","explanation":"設備容量、製品厚さ、流れ、滞留時間、センサー位置が変わると、最も加熱されにくい位置や管理基準の測定方法が変わる。変更管理として危害分析と妥当性確認を更新する。","wrongReason":"Bは同じ設定値でも実際の加熱効果が変わる可能性を無視している。Cは予防原則に反する。Aは自社製品での制御能力を確認していない。","example":"試運転で温度分布と滞留時間を確認し、最悪条件での加熱効果、警報、記録、逸脱品排出を検証する。","terms":"変更管理、再評価、妥当性確認、設備変更","process":"設備変更・計画見直し","hazard":"共通","scope":"国際共通の原則","sourceId":"S006","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q066","categoryCode":"D","category":"CCP・管理基準・監視・是正・検証","subtheme":"HACCP原則の論理順序","difficulty":"レベル3","format":"手順並べ替え","question":"CCPの管理方法を設計する論理的な順序として、次の項目を並べてください。A：モニタリング方法を決める　B：CCPを決定する　C：管理基準を設定する　D：逸脱時の改善措置を決める","options":[{"key":"A","text":"B→C→A→D"},{"key":"B","text":"B→A→D→C"},{"key":"C","text":"A→B→C→D"},{"key":"D","text":"C→B→D→A"}],"correct":["A"],"conclusion":"CCPを決め、管理基準、モニタリング、改善措置の順に設計する。","explanation":"HACCPの原則では、危害分析後にCCPを決定し、管理基準を設定し、モニタリング手順と改善措置を定める。その後、検証と記録の仕組みを整える。","wrongReason":"C・D・Dの並びは、管理対象や合否基準が確定する前に監視・処置を決めている。","example":"加熱工程をCCPと決めた後、温度・時間の基準、測定方法、基準外時の製品保留と工程調整を具体化する。","terms":"7原則、CCP、管理基準、モニタリング、改善措置","process":"HACCP計画作成","hazard":"共通","scope":"国際共通の原則","sourceId":"S002","sourceUrl":"https://www.fda.gov/food/hazard-analysis-critical-control-point-haccp/haccp-principles-application-guidelines","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第3回作成"},{"id":"Q067","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"原料受入れ","difficulty":"レベル1","format":"四択","question":"冷蔵原料を受け入れる際の確認として、最も適切なものはどれか。","options":[{"key":"A","text":"外箱がきれいなら記録を残さず受け入れる"},{"key":"B","text":"受入規格、品温、包装の破損、期限、ロットなどを確認し、不適合品は使用前に区分する"},{"key":"C","text":"取引先の知名度だけを確認する"},{"key":"D","text":"納品車が予定時刻より早く到着したかだけを確認する"}],"correct":["B"],"conclusion":"冷蔵原料は、使用前に規格と実際の状態を確認する。","explanation":"原料は定めた仕様に合っていることを必要に応じて確認する。冷蔵・冷凍品では品温、包装破損、期限、表示、ロットなどを確認し、基準に合わない原料をそのまま製造へ流さない。具体的な温度基準は食品、法令、顧客要求、自社規格によって定める。","wrongReason":"Cは供給者評価の一部にすぎず、納品物の状態を確認していない。Dは食品安全と直接関係しない。Aは異常の見逃しと追跡不能につながる。","example":"冷蔵肉の品温が受入基準を外れていた場合は、いったん保留場所へ移し、時間・温度履歴や包装状態を確認して受入れ可否を判断する。","terms":"受入規格、品温、包装破損、ロット","process":"原料受入れ","hazard":"共通","scope":"国際共通の原則／具体的基準は製品・法令・顧客条件による","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q068","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"受入記録と仕様確認","difficulty":"レベル2","format":"複数選択","question":"原材料の受入れ時に、必要に応じて確認・記録する項目をすべて選んでください。","options":[{"key":"A","text":"供給者、受入日、数量、ロット"},{"key":"B","text":"アレルゲン表示や規格書との一致は確認しない"},{"key":"C","text":"品温、包装状態、期限"},{"key":"D","text":"受入担当者の昼食メニュー"}],"correct":["A","C"],"conclusion":"原料の由来、状態、規格への適合を追跡できる情報を残す。","explanation":"受入記録は、どの原料を、いつ、どこから、どの状態で受け入れたかを追跡するために必要である。食品や危害に応じて、品温、包装、期限、アレルゲン、検査証明書などを確認する。すべての原料で同じ検査を行うのではなく、危害分析と受入仕様に基づいて決める。","wrongReason":"Bは原料仕様とアレルゲン確認を省いている。Dは食品安全や原料の追跡性に関係しない。","example":"輸入原料では、供給者名、製造ロット、受入日、数量、表示、必要な検査証明を記録し、製造ロットと結び付ける。","terms":"受入記録、供給者管理、仕様書、証明書","process":"原料受入れ","hazard":"共通","scope":"国際共通の原則／必要項目は原料と危害により異なる","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q069","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"在庫回転","difficulty":"レベル1","format":"四択","question":"同じ原料の入庫日と使用期限が異なる場合、払い出し方法として最も適切なものはどれか。","options":[{"key":"A","text":"ロット表示が読めない原料を優先して使う"},{"key":"B","text":"作業場所から一番近い原料から使う"},{"key":"C","text":"包装が破損した原料から先に使い切る"},{"key":"D","text":"使用可能と確認された原料の中から、期限と入庫順を考慮して適切に在庫回転する"}],"correct":["D"],"conclusion":"在庫回転は、期限だけでなく使用可否とロット状態も確認して行う。","explanation":"先入れ先出しや期限の早いものから使う方法は有効だが、保留品、不適合品、包装破損品まで自動的に使用してよいわけではない。使用可能な状態であること、保存条件、期限、ロット識別を確認して払い出す。","wrongReason":"Bは期限や状態を無視している。Cは汚染や劣化の可能性がある。Aは追跡できない原料を使用している。","example":"倉庫では期限順に配置しつつ、品質管理による保留札が付いたロットは払い出し対象から除外する。","terms":"先入れ先出し、先期限先出し、在庫回転、保留品","process":"原料保管・払い出し","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q070","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"保管区分","difficulty":"レベル2","format":"複数選択","question":"食品工場の保管方法として適切なものをすべて選んでください。","options":[{"key":"A","text":"洗浄剤や潤滑油などの非食品用薬剤を、識別して食品から分離し、安全に保管する"},{"key":"B","text":"アレルゲンを含む原料を識別し、必要に応じて非含有原料と区分する"},{"key":"C","text":"生原料と加熱後のそのまま食べる製品を、汚染が移らないよう区分する"},{"key":"D","text":"冷蔵庫内であれば、液漏れしている生肉を包装済み製品の上段に置いてもよい"}],"correct":["A","B","C"],"conclusion":"保管中も、微生物、薬剤、アレルゲンなどの交差汚染を防ぐ。","explanation":"保管施設は、原料と加熱後製品、アレルゲン含有品と非含有品、食品と非食品薬剤を必要に応じて区分できることが重要である。温度や湿度も食品の特性に応じて管理する。","wrongReason":"Dは液漏れによる微生物汚染を包装済み製品へ広げるおそれがある。","example":"生肉は下段の漏れ防止容器に入れ、加熱済み食品とは棚や室を分ける。薬剤庫は食品倉庫と分離する。","terms":"区分保管、交差汚染、アレルゲン、薬剤管理","process":"原料・製品保管","hazard":"生物的・化学的危害","scope":"国際共通の原則／区分方法は施設と危害に応じて決める","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q071","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"解凍","difficulty":"レベル3","format":"現場判断","question":"冷凍肉を室温で一晩解凍しており、表面が温かく、解凍液が隣の加熱済み食品容器へ流れていました。最も適切な対応はどれか。","options":[{"key":"A","text":"中心がまだ凍っているので、そのまま使用する"},{"key":"B","text":"対象原料と汚染のおそれがある食品を区分し、時間・温度履歴と交差汚染を評価した上で、管理された解凍方法へ見直す"},{"key":"C","text":"表面を水で流せば必ず安全になる"},{"key":"D","text":"解凍液だけ拭き取り、記録せず作業を続ける"}],"correct":["B"],"conclusion":"解凍では、微生物増殖と解凍液による交差汚染の両方を管理する。","explanation":"食品の表面は中心部より早く温度が上がるため、長時間の室温放置では微生物が増殖する可能性がある。さらに解凍液が他の食品や器具へ触れると交差汚染が起こり得る。食品に適した管理温度、時間、設備、受け皿などを定める。","wrongReason":"Aは表面温度と交差汚染を無視している。Cは洗浄だけで安全を保証している。Dは影響製品の評価と記録がない。","example":"冷蔵庫内解凍、専用解凍設備、または妥当性が確認された方法を用い、解凍液が他の食品へ接触しない構造にする。","terms":"解凍、時間温度管理、ドリップ、交差汚染","process":"解凍","hazard":"生物的危害","scope":"製品別に解凍条件を設定","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q072","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"原料洗浄","difficulty":"レベル2","format":"○×","question":"野菜を水で洗浄すれば、原料由来の微生物や化学的危害は完全に除去されるため、その後の危害分析は不要である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"洗浄だけで、すべての危害が完全に除去されるとは限らない。","explanation":"洗浄は土や一部の汚染を減らす有効な工程だが、病原微生物、農薬、異物などを必ず許容レベルまで除去できるとは限らない。使用水自体も用途に適した水質である必要があり、後工程を含めて危害分析する。","wrongReason":"Aは洗浄効果を過大評価し、原料の危害と後工程での管理を確認していない。","example":"洗浄後に加熱する製品と、洗浄後そのまま食べる製品では、必要な洗浄・殺菌方法や検証内容が異なる。","terms":"原料洗浄、使用水、洗浄効果、危害分析","process":"洗浄","hazard":"生物的・化学的・物理的危害","scope":"国際共通の原則／洗浄条件は食品と危害により異なる","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q073","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"切断・混合","difficulty":"レベル2","format":"四択","question":"加熱前の切断・混合工程で、食品安全上最も適切な管理はどれか。","options":[{"key":"A","text":"作業時間と品温、器具の衛生、原料間の交差汚染、ロットの対応関係を管理する"},{"key":"B","text":"異なる原料でも同じ器具を洗浄せずに使用する"},{"key":"C","text":"混合後は原料ロットを記録しなくてもよい"},{"key":"D","text":"細かく切れば微生物は自然に消えると考える"}],"correct":["A"],"conclusion":"切断・混合では、汚染の拡大と温度上昇、ロット混合を管理する。","explanation":"切断や混合により食品表面が増え、複数原料の汚染が製品全体へ広がることがある。作業時間・品温、器具洗浄、アレルゲンや生原料からの交差汚染、原料ロットと製品ロットの対応を管理する。","wrongReason":"Dは微生物が切断で消えるという誤り。Bは交差汚染を起こす。Cは追跡性を失わせる。","example":"生肉用と加熱後製品用の器具を区分し、混合バッチごとに使用した原料ロットと投入量を記録する。","terms":"切断、混合、品温、ロット対応、交差汚染","process":"切断・混合","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q074","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"配合による危害管理","difficulty":"レベル3","format":"四択","question":"製品のpH、塩分、保存料などの配合を微生物増殖の抑制に利用する場合、最も適切な運用はどれか。","options":[{"key":"A","text":"熟練者が目分量で配合し、記録しない"},{"key":"B","text":"不足した原料は別の原料を同量入れて代用する"},{"key":"C","text":"有効性を確認した配合を定め、原料を正確に計量し、バッチ記録と基準外時の処置を管理する"},{"key":"D","text":"苦情が発生したときだけ完成品のpHを測る"}],"correct":["C"],"conclusion":"配合が安全性を支える場合は、レシピ、計量、均一性、記録を管理する。","explanation":"酸、塩、保存料などの配合を危害管理に使う場合、定めた配合が対象危害を制御できる根拠が必要である。投入量、混合の均一性、測定方法、バッチ記録、逸脱品の処置を明確にする。","wrongReason":"Aはばらつきと追跡不能を招く。Bは妥当性確認されていない配合変更である。Dは予防管理にならない。","example":"計量器で添加物を量り、投入者と確認者、ロット、投入量、混合時間、必要に応じて完成品pHなどを記録する。","terms":"配合、pH、水分活性、塩分、保存料","process":"調合・混合","hazard":"生物的・化学的危害","scope":"製品別の科学的根拠・法令上の使用基準が必要","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q075","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"加熱条件の確認","difficulty":"レベル3","format":"現場判断","question":"釜の表示温度は毎回同じですが、製品の粘度、投入量、初期温度がロットごとに変わります。加熱管理として最も適切なものはどれか。","options":[{"key":"A","text":"平均投入量のロットだけ確認し、最大投入量は確認しない"},{"key":"B","text":"釜の設定温度が同じなら、製品の加熱状態は確認しない"},{"key":"C","text":"最も加熱されにくい製品条件と位置を想定し、製品温度・時間または妥当性確認済みの代替条件で管理する"},{"key":"D","text":"表面から湯気が出れば全体が安全と判断する"}],"correct":["C"],"conclusion":"加熱は、設備表示だけでなく最も加熱されにくい製品条件を基準に確認する。","explanation":"設備の設定値と製品内部の温度履歴は同じとは限らない。粘度、量、厚さ、初期温度、撹拌、位置などによって冷点が変わるため、最悪条件を含めて加熱効果を確認し、日常管理方法を定める。","wrongReason":"Bは設備値と製品値を混同している。Dは外観による推測である。Aは最悪条件を除外している。","example":"最大投入量・最低初期温度などの厳しい条件で温度分布を確認し、代表測定位置や撹拌条件を決める。","terms":"加熱、冷点、中心温度、最悪条件、妥当性確認","process":"加熱","hazard":"生物的危害","scope":"加熱基準は製品・対象危害・法令に応じて設定","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q076","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"直接測定できない加熱工程","difficulty":"レベル4","format":"四択","question":"包装後に加熱する製品で、製造中に全製品の中心温度を直接測定できません。最も適切な管理方法はどれか。","options":[{"key":"A","text":"中心温度を測れないため、加熱工程の管理を行わない"},{"key":"B","text":"必要な加熱効果を得られることを事前に確認した設備温度、時間、充填量、初期温度などを管理し、定期的に有効性を確認する"},{"key":"C","text":"包装が膨らめば十分に加熱されたと判断する"},{"key":"D","text":"一度だけ試験に合格すれば、製品や設備を変更しても条件を見直さない"}],"correct":["B"],"conclusion":"直接測定できない場合は、妥当性確認済みの工程条件を代替指標として管理する。","explanation":"全製品の中心温度を直接測定できなくても、製品条件と設備条件の関係を試験で確認し、必要な安全性を得られる工程パラメータを定めることができる。充填量、製品厚さ、初期温度、槽温、滞留時間など重要条件を監視し、変更時には再評価する。","wrongReason":"Aは重要工程を無管理にする。Cは包装外観を安全性の根拠にしている。Dは変更による影響を無視している。","example":"ボイル槽温度と浸漬時間を日常監視し、代表製品で中心温度が確保されることを定期的に確認する。","terms":"代替管理指標、工程パラメータ、加熱殺菌、妥当性確認","process":"加熱","hazard":"生物的危害","scope":"具体的条件は製品・設備・対象危害・法令ごとに妥当性確認","sourceId":"S007","sourceUrl":"https://www.mhlw.go.jp/content/11130500/000796466.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q077","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"冷却","difficulty":"レベル3","format":"現場判断","question":"加熱済みの煮込み食品を深い容器に大量に入れ、室温で翌朝まで冷ましていました。中心部はまだ温かい状態です。最も適切な対応はどれか。","options":[{"key":"A","text":"対象製品を保留して時間・温度履歴を評価し、今後は適切な設備や小分けなどで速やかに冷却できる方法を設定・監視する"},{"key":"B","text":"においに異常がなければ安全と判断する"},{"key":"C","text":"表面が冷えているので、そのまま包装して出荷する"},{"key":"D","text":"冷蔵庫へ入れれば、室温放置の影響は必ず消える"}],"correct":["A"],"conclusion":"冷却では、食品内部が危険な温度帯を長時間通過しないよう管理する。","explanation":"大容量・深い容器では中心部の冷却が遅れ、加熱後に残った芽胞などが発芽・増殖する可能性がある。異常品は時間・温度履歴と対象危害を評価し、通常品と混ぜない。冷却方法と基準は食品や法令に応じて定める。","wrongReason":"Cは中心部を確認していない。Dは過去の温度履歴を取り消せない。Bは官能だけで微生物リスクを判断している。","example":"ブラストチラー、浅い容器、小分け、撹拌、冷却水などを組み合わせ、最も冷えにくい位置で条件を確認する。","terms":"急速冷却、時間温度管理、芽胞、製品保留","process":"冷却","hazard":"生物的危害","scope":"冷却基準は製品・対象危害・法令に応じて設定","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q078","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"充填・包装時の再汚染","difficulty":"レベル3","format":"四択","question":"加熱後製品の充填ノズルが保守作業中に床へ触れました。作業者が乾いた布で拭いただけで製造を再開しようとしています。最も適切な対応はどれか。","options":[{"key":"A","text":"製品は加熱済みなので、ノズルの状態は関係ない"},{"key":"B","text":"最初の1個だけ廃棄すれば必ず十分である"},{"key":"C","text":"見た目に汚れがなければ記録せず再開する"},{"key":"D","text":"製造を止め、影響製品を区分し、ノズルを定めた方法で洗浄・必要に応じて殺菌し、再開前確認を行う"}],"correct":["D"],"conclusion":"加熱後工程では、設備からの再汚染を防ぎ、影響範囲を評価する。","explanation":"加熱で危害を低減した後の製品は、充填・包装設備や作業者から再汚染されると、後工程で除去できない場合がある。汚染した部品を適切に洗浄・殺菌し、必要な確認後に再開する。接触した時間帯の製品も評価する。","wrongReason":"Aは再汚染を無視している。Bは影響範囲を根拠なく限定している。Cは衛生状態と追跡性を確認していない。","example":"設備停止時刻から最後の正常確認時刻までを調べ、該当製品を保留し、再洗浄後に拭取り検査や目視確認を行う。","terms":"再汚染、充填、包装、洗浄・殺菌、再開確認","process":"充填・包装","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q079","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"ラベル切替とアレルゲン表示","difficulty":"レベル4","format":"四択","question":"乳成分を含まない製品から乳成分を含む製品へ切り替えた後、包装機に前製品の「乳成分表示がないラベル」が残っていたことが分かりました。最も適切な対応はどれか。","options":[{"key":"A","text":"最後にラベルを正常確認した時点以降の製品を保留・特定し、中身と表示の一致を確認して処置し、切替手順を見直す"},{"key":"B","text":"苦情が来るまで何もしない"},{"key":"C","text":"製品の中身が正常なら、ラベル違いは食品安全に関係ない"},{"key":"D","text":"数枚だけ正しいラベルを上から貼り、残りはそのまま出荷する"}],"correct":["A"],"conclusion":"アレルゲンを含む中身と表示の不一致は、健康被害につながるため製品を特定して処置する。","explanation":"ラベル切替では、旧ラベルの除去、正しい資材の照合、初品確認、製造中の定期確認が重要である。誤表示が疑われる場合は、対象時間・ロットを特定して保留し、再表示、廃棄、回収などを法令と手順に基づいて判断する。この管理がCCPかどうかは危害分析による。","wrongReason":"Cはアレルゲン表示の重要性を無視している。Dは対象範囲を確認していない。Bは消費者へ危害が及ぶまで放置している。","example":"ラベルロールの照合を二者確認し、切替時の旧資材回収数、初品ラベル、製造日報へ貼付した見本を記録する。","terms":"アレルゲン表示、ラベル照合、ライン切替、製品保留","process":"包装・表示","hazard":"化学的危害（アレルゲン）","scope":"表示義務と処置は国・地域の法令に従う","sourceId":"S007","sourceUrl":"https://www.mhlw.go.jp/content/11130500/000796466.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q080","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"金属検出機の異常対応","difficulty":"レベル3","format":"手順並べ替え","question":"製造終了時のテストピース確認で金属検出機が正常に排除しませんでした。次の対応を論理的な順序に並べてください。A：製品の出荷を止め、前回の正常確認以降の製品を特定して保留する　B：検出機を点検・調整し、テストピースで正常機能を確認する　C：保留製品を正常な検出機で再検査し、処置を決める　D：再検査結果と製品処置を含めて逸脱を記録し、原因調査と再発防止を完了する","options":[{"key":"A","text":"D→C→B→A"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"A→B→C→D"},{"key":"D","text":"C→A→B→D"}],"correct":["C"],"conclusion":"まず製品流出を止めて範囲を特定し、設備復旧後に再検査・処置を行い、その結果を含めて原因調査と再発防止を完了する。","explanation":"終了時確認で異常が見つかった場合、前回の正常確認以降に検査された製品は適切に検出されていない可能性がある。製品を保留し、検出機の機能を復旧・確認してから再検査する。再検査結果と製品処置を記録し、異物や機器異常の原因を追究して再発防止へつなげる。","wrongReason":"A・B・Dから始める選択肢は、疑わしい製品の流出防止と影響範囲の確保が後回しになっている。","example":"テストピースの材質・向き・通過位置も手順どおり確認し、排除箱の施錠、排出確認、再検査数量を記録する。","terms":"金属検出、テストピース、排除機構、再検査、逸脱","process":"金属検出","hazard":"物理的危害","scope":"検出条件は製品特性・想定異物・顧客条件に応じて設定","sourceId":"S007","sourceUrl":"https://www.mhlw.go.jp/content/11130500/000796466.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q081","categoryCode":"E","category":"食品工場の工程別実務","subtheme":"製品保管・出荷","difficulty":"レベル2","format":"四択","question":"冷蔵製品を出荷しようとしたところ、車両の荷室が汚れており、必要な輸送温度にも達していません。最も適切な対応はどれか。","options":[{"key":"A","text":"出荷記録を先に作成すれば積み込んでよい"},{"key":"B","text":"移動中に冷えると考えて、そのまま積み込む"},{"key":"C","text":"製品を適切な条件で保留し、荷室の衛生状態と温度条件を整えるか、適切な別車両を使用してから出荷する"},{"key":"D","text":"外箱があるので荷室の汚れは確認しない"}],"correct":["C"],"conclusion":"輸送開始前に、車両・容器が食品を汚染せず必要な保存条件を維持できることを確認する。","explanation":"食品は工場内で安全に製造されても、輸送中の汚染、破損、温度逸脱によって不安全または不適切になる可能性がある。車両の清潔さ、修理状態、異品との区分、必要な温度維持能力を確認し、ロットと出荷先を記録する。","wrongReason":"Bは輸送開始直後の温度逸脱を容認している。Dは外箱を過信している。Aは記録だけで実際の条件を改善していない。","example":"積込み前に荷室温度、清掃状態、異臭、前荷、温度記録装置を確認し、出荷ロット、数量、届け先、時刻を記録する。","terms":"コールドチェーン、輸送衛生、出荷記録、トレーサビリティ","process":"製品保管・出荷","hazard":"共通","scope":"国際共通の原則／輸送条件は製品・法令・顧客条件による","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第4回作成"},{"id":"Q082","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"衛生的な設備設計","difficulty":"レベル1","format":"四択","question":"食品と直接接触する設備の設計として、最も適切なものはどれか。","options":[{"key":"A","text":"表面の傷や腐食が増えても、そのまま使用できる構造"},{"key":"B","text":"用途に適した材質を使い、耐久性があり、必要な範囲を洗浄・点検しやすい構造"},{"key":"C","text":"見た目が美しければ、洗浄性を確認しなくてもよい構造"},{"key":"D","text":"複雑な隙間が多く、分解しないと汚れを確認できない構造"}],"correct":["B"],"conclusion":"食品設備は、適切な材質と洗浄・点検しやすい構造が基本である。","explanation":"食品接触部は、想定する食品、洗浄剤、温度、機械的負荷に耐え、食品を汚染しにくい材質と構造にする。汚れが残る隙間や損傷部を減らし、必要な箇所へ清掃・点検のためにアクセスできることが重要である。","wrongReason":"Dは汚れの残留や確認漏れを招く。Aは異物や微生物の付着場所になり得る。Cは外観だけで食品安全上の性能を判断している。","example":"タンク、配管、充填ノズルなどは、接液部を洗浄でき、シールや接合部を必要に応じて点検・交換できる構造とする。","terms":"衛生設計、食品接触面、洗浄性、点検性","process":"全工程・設備設計","hazard":"共通","scope":"国際共通の原則／具体的な構造基準は適用規格に従う","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q083","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"センサーの測定位置","difficulty":"レベル2","format":"四択","question":"加熱設備の製品温度センサーを、蒸気入口に近い最も温まりやすい場所へ取り付けました。最も適切な考え方はどれか。","options":[{"key":"A","text":"最も高い温度が表示される位置なら、製品全体の安全性を代表できる"},{"key":"B","text":"センサーの型式が新しければ、取付位置は関係ない"},{"key":"C","text":"設備の設定温度だけを記録し、製品側の温度分布は確認しない"},{"key":"D","text":"測定位置が最も加熱されにくい製品条件を適切に代表するか確認し、必要なら位置や管理方法を見直す"}],"correct":["D"],"conclusion":"センサーは、管理したい危害と製品状態を代表できる位置で使う。","explanation":"正確なセンサーでも、測定位置が不適切なら工程全体を正しく評価できない。温度分布、製品量、流れ、撹拌、初期温度などを踏まえ、最も厳しい条件を代表する位置や、妥当性確認済みの代替指標を設定する。","wrongReason":"Aは最も温まりやすい位置を安全側と誤解している。Bは取付位置の影響を無視している。Cは設備値と製品状態を混同している。","example":"釜内の複数点で温度分布を調べ、日常監視に使うセンサー位置と、ロットごとの製品条件を決める。","terms":"測定位置、温度分布、冷点、代表性","process":"加熱・冷却","hazard":"生物的危害","scope":"測定位置は製品・設備・対象危害ごとに確認","sourceId":"S006","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q084","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"警報と異常時対応","difficulty":"レベル2","format":"○×","question":"CCPの温度が基準外になると警報が鳴る設備であれば、誰が止めるか、どの製品を保留するか、記録をどう残すかは決めなくてもよい。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"警報は異常を知らせる機能であり、製品処置や対応手順の代わりではない。","explanation":"警報があっても、気付かれない、無視される、設定が誤っている、製品がそのまま通過する可能性がある。警報値、担当者、停止・連絡方法、影響製品の範囲、保留、記録、復旧確認まで手順化する。","wrongReason":"Aは、警報が自動的に工程と製品を安全な状態へ戻すと誤解している。","example":"警報発生時にラインを停止し、最後の正常確認時刻以降の製品を保留できるよう、操作手順と教育を整える。","terms":"警報、逸脱対応、製品保留、連絡手順","process":"CCP・自動設備","hazard":"共通","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q085","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"インターロックとバイパス管理","difficulty":"レベル3","format":"四択","question":"安全管理に使用するインターロックが頻繁に作動するため、作業者が自由に無効化できる設定にしました。最も適切な対応はどれか。","options":[{"key":"A","text":"作動原因を調査し、無効化が必要な場合は権限、期間、代替管理、製品影響、記録、復旧確認を管理する"},{"key":"B","text":"生産が止まらなければ、恒久的に無効化してよい"},{"key":"C","text":"無効化したことを記録しなければ問題にならない"},{"key":"D","text":"インターロックがある設備は、モニタリングを行わなくてもよい"}],"correct":["A"],"conclusion":"インターロックのバイパスは、自由操作ではなく変更管理の対象にする。","explanation":"インターロックは異常時の流出や誤操作を防ぐ助けになるが、誤作動の原因を放置したまま無効化すると管理機能を失う。やむを得ない一時バイパスでは、権限者の承認、代替監視、対象製品の管理、期限、復旧確認を定める。","wrongReason":"BとCは食品安全上の管理を失わせる。Dはインターロックを日常監視の代替と誤解している。","example":"排除確認センサーを一時的にバイパスする場合は、全品を別の正常な検出機へ通すなどの代替管理を承認・記録する。","terms":"インターロック、バイパス、変更管理、代替管理","process":"自動設備・CCP","hazard":"共通","scope":"国際共通の原則／安全回路の法的要件は別途確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q086","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"センサー故障時の影響評価","difficulty":"レベル3","format":"現場判断","question":"製造後に確認すると、加熱温度センサーの表示が2時間同じ値で固定されていました。記録上はすべて基準内です。最も適切な対応はどれか。","options":[{"key":"A","text":"記録が基準内なので、全製品をそのまま出荷する"},{"key":"B","text":"固定値を平均温度として扱い、記録を修正する"},{"key":"C","text":"次回製造からセンサーを直せば、今回の製品は確認しなくてよい"},{"key":"D","text":"最後にセンサーが正常と確認できた時点以降の製品を保留し、別記録や工程条件で影響を評価し、センサー修理・精度確認後に再開する"}],"correct":["D"],"conclusion":"測定値の固定は正常記録ではなく、測定機能の異常として製品影響を評価する。","explanation":"センサーや伝送系が故障すると、画面には正常に見える値が残る場合がある。最後の正常確認、他の温度計、加熱時間、蒸気圧、流量、警報履歴などを確認し、根拠が不足する製品は通常品と区分して処置する。","wrongReason":"Aは記録値の信頼性を確認していない。Bは実測していない値への書換えである。Cは今回の製品への影響を無視している。","example":"PLCのトレンドが完全な水平線になった場合は、入力断線時の保持設定も確認し、異常検知ロジックを追加する。","terms":"センサー故障、固定値、影響評価、製品保留","process":"加熱・計測","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S008","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q087","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"電子記録の信頼性","difficulty":"レベル3","format":"複数選択","question":"HACCP管理に使用する自動記録へ含めることが望ましい情報をすべて選んでください。","options":[{"key":"A","text":"基準外の値を自動削除し、正常値だけ残す機能"},{"key":"B","text":"警報、設定変更、確認者や処置の履歴"},{"key":"C","text":"製品・ロットとの対応関係は残さない"},{"key":"D","text":"測定値、日時、対象設備またはライン"}],"correct":["B","D"],"conclusion":"自動記録は、値だけでなく製品と操作・異常の履歴を追跡できるようにする。","explanation":"電子記録は、いつ、どの設備で、どの製品を測定したかが分かり、警報、設定変更、確認、逸脱処置を追跡できることが重要である。アクセス権、時刻同期、バックアップ、訂正履歴などもリスクに応じて管理する。","wrongReason":"Cは製品追跡を不可能にし、Aは逸脱の証拠を消して記録の完全性を損なう。","example":"温度トレンドへ製造ロットを関連付け、設定値を変更した利用者、変更前後の値、警報確認時刻を保存する。","terms":"電子記録、監査証跡、時刻同期、アクセス権","process":"自動記録・全工程","hazard":"共通","scope":"記録要件は法令・認証規格・顧客要求も確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q088","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"CIPの管理条件","difficulty":"レベル3","format":"四択","question":"CIP洗浄の戻り液が透明に見えたため、毎回そこで洗浄を終了しています。最も適切な考え方はどれか。","options":[{"key":"A","text":"洗浄剤濃度だけを最大にすれば、他の条件は不要である"},{"key":"B","text":"CIP設備を導入すれば、分解点検や洗浄性の確認は一切不要になる"},{"key":"C","text":"設備と汚れに対して有効性を確認した手順に基づき、時間、温度、濃度、流量や流れ、工程順序などを管理し、洗浄結果を検証する"},{"key":"D","text":"透明であれば、時間、温度、洗浄剤濃度、流れは確認しなくてよい"}],"correct":["C"],"conclusion":"CIPは、見た目だけでなく有効性を確認した複数条件の組合せで管理する。","explanation":"CIPの洗浄効果は、設備形状、汚れ、時間、温度、薬剤濃度、流れや機械的作用、すすぎなどの組合せで決まる。洗浄できない枝管やシール裏があれば、記録が正常でも汚れが残る可能性がある。","wrongReason":"Dは外観だけで判断している。Aは濃度を上げれば必ず安全という誤りで、材質損傷や残留の問題もある。Bは設備の死角や保守点検を無視している。","example":"CIPチャートで各工程の時間・温度・導電率・流量を確認し、定期的に目視、拭取り、微生物検査などで有効性を検証する。","terms":"CIP、洗浄時間、温度、濃度、流量、検証","process":"洗浄・殺菌","hazard":"生物的・化学的危害","scope":"具体的条件は設備・食品・汚れ・薬剤ごとに妥当性確認","sourceId":"S010","sourceUrl":"https://my.3-a.org/Portals/93/Documents/E-Learning%20Modules/Module%201.0.%20Overview%20of%20Principles%20of%20Hygienic%20Design%20-%20Storyline%20output/story_html5.html?ver=2019-01-17-132253-103","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q089","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"保守後の製造再開","difficulty":"レベル3","format":"手順並べ替え","question":"食品接触部を分解修理した後の製造再開について、次の項目を論理的な順序に並べてください。A：交換部品、工具、ねじなどを確認し、欠品や異物残留がないか点検する　B：食品接触部を定めた方法で洗浄・必要に応じて殺菌する　C：センサー、警報、排除機構など修理に関係する機能を試験する　D：確認結果を記録し、権限者が再開を承認する","options":[{"key":"A","text":"B→D→A→C"},{"key":"B","text":"A→B→C→D"},{"key":"C","text":"C→A→D→B"},{"key":"D","text":"D→B→C→A"}],"correct":["B"],"conclusion":"保守後は、異物確認、衛生復旧、機能試験、承認の順で再開条件を整える。","explanation":"保守では、工具や部品の残留、潤滑剤、切粉、作業者による汚染、設定ずれが発生し得る。部品・工具確認後に洗浄し、管理機能を試験して、記録と承認を行ってから製造を再開する。","wrongReason":"A・C・Dから始める選択肢は、欠品や異物の確認、衛生復旧、機能確認のいずれかを後回しにしている。","example":"ボルト本数表、工具チェック表、洗浄記録、模擬警報試験、初品確認を一つの再開チェックシートにまとめる。","terms":"保守点検、部品管理、再開確認、機能試験","process":"保守後・製造再開","hazard":"物理的・生物的・化学的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q090","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"デッドスペースと排水性","difficulty":"レベル4","format":"四択","question":"CIP配管に洗浄液が十分流れない長い行き止まり枝管があり、製造後に製品と洗浄水が残ります。最も適切な対応はどれか。","options":[{"key":"A","text":"外側が清潔なら、内部の残留は問題にしない"},{"key":"B","text":"残留部を危害として評価し、枝管の削減・短縮、流れや排水性の改善、分解洗浄などで確実に洗浄・点検できる構造へ見直す"},{"key":"C","text":"製造開始時に残留物を製品へ押し出せばよい"},{"key":"D","text":"洗浄剤を濃くするだけで、配管構造はそのままにする"}],"correct":["B"],"conclusion":"洗浄液が届かず排水できないデッドスペースは、構造から見直す。","explanation":"行き止まりや液だまりは、食品残渣、微生物、洗浄剤の残留場所になり得る。薬剤条件だけに頼らず、流れ、排水、分解性、点検性を含めて設計を見直し、変更後の洗浄効果を確認する。","wrongReason":"Dは構造的な洗浄不良を解決していない。Aは内部汚染を無視している。Cは残留物を製品へ混入させる。","example":"配管の傾斜、バルブ位置、枝管長、スプレーボールの死角を確認し、必要なら配管を改造してリンス試験を行う。","terms":"デッドスペース、液だまり、排水性、CIP、点検性","process":"配管・タンク・CIP","hazard":"生物的・化学的危害","scope":"具体的寸法は適用する衛生設計規格に従う","sourceId":"S009","sourceUrl":"https://www.3-a.org/news/3-a-ssi-updates-foundational-hygienic-design-standard","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q091","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"潤滑剤と化学汚染","difficulty":"レベル4","format":"四択","question":"食品製造設備での使用に適した潤滑剤を使用しています。最も適切な管理はどれか。","options":[{"key":"A","text":"適した潤滑剤であれば、食品へ大量に漏れても問題ない"},{"key":"B","text":"潤滑剤の容器表示や保管場所は管理しなくてよい"},{"key":"C","text":"一般工業用潤滑剤と同じ容器へ移し替え、区別せず使用する"},{"key":"D","text":"適用箇所に合う潤滑剤を必要量だけ使用し、漏れや飛散を防ぎ、異常時は製品への影響を評価する"}],"correct":["D"],"conclusion":"使用に適した潤滑剤でも、意図しない食品汚染を防ぐ管理が必要である。","explanation":"潤滑剤は用途、接触可能性、設備条件に適したものを選び、過剰塗布、シール不良、滴下を防ぐ。漏れが発生した場合は、発生時刻、量、位置、対象製品を特定し、法令や仕様に基づいて処置する。","wrongReason":"Aは意図しない汚染を容認している。BとCは誤使用や交差汚染につながる。","example":"ギヤボックス下部に漏れ受けと点検窓を設け、保全点検で油量低下と漏れ跡を確認する。","terms":"潤滑剤、化学的危害、漏れ、薬剤管理","process":"保守・製造","hazard":"化学的危害","scope":"使用可能な潤滑剤区分と許容条件は国・地域・顧客要求を確認","sourceId":"S008","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q092","categoryCode":"F","category":"食品機械・設備・センサー・洗浄設計","subtheme":"シール・ガスケットの衛生管理","difficulty":"レベル4","format":"四択","question":"食品接触配管のガスケットを代替品へ交換したところ、接液面に段差ができ、取り外すと裏側に製品残渣がありました。最も適切な対応はどれか。","options":[{"key":"A","text":"対象製品への影響を評価し、用途・材質・寸法に適合する部品へ交換して、接液面の隙間、洗浄性、シール状態を確認する"},{"key":"B","text":"ガスケットの裏側は食品から見えないため、洗浄・点検しなくてよい"},{"key":"C","text":"漏れていなければ、そのまま使用を続ける"},{"key":"D","text":"段差を埋めるため、材質不明の接着剤を食品接触面へ塗る"}],"correct":["A"],"conclusion":"シール部は、適合部品を使い、残渣がたまらず洗浄・点検できる状態にする。","explanation":"寸法や材質が合わないガスケットは、接液面に隙間や段差を作り、食品残渣や微生物の滞留、部品の欠け、洗浄剤への劣化を招く可能性がある。交換部品の仕様、圧縮状態、取付方向、シール裏の清掃・点検性を確認する。","wrongReason":"Cは漏れだけで衛生状態を判断している。Dは新たな化学的危害や剥離異物を生む。Bは隠れた残留と劣化を無視している。","example":"定期分解時にガスケットの膨潤、亀裂、欠け、裏面残渣を確認し、交換品の材質・ロット・取付日を記録する。","terms":"ガスケット、シール、段差、適合部品、点検性","process":"配管・タンク・充填設備","hazard":"生物的・化学的・物理的危害","scope":"具体的な材質・段差・シール要件は適用する衛生設計規格に従う","sourceId":"S009","sourceUrl":"https://www.3-a.org/news/3-a-ssi-updates-foundational-hygienic-design-standard","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第5回作成"},{"id":"Q093","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"Codexと各国法令","difficulty":"レベル2","format":"四択","question":"CodexのHACCP原則に沿った計画を作成しました。海外へ輸出する際の考え方として最も適切なものはどれか。","options":[{"key":"A","text":"日本の衛生管理記録があれば、どの国でも同じ様式で必ず受理される"},{"key":"B","text":"取引先が了承すれば、輸出先の法令に適合しなくてもよい"},{"key":"C","text":"Codexは国際的な基準・指針だが、輸出先の法令、製品別規則、輸入条件、顧客要求を別に確認する"},{"key":"D","text":"Codexに沿っていれば、輸出先の法令や製品別要求は確認しなくてよい"}],"correct":["C"],"conclusion":"Codexは重要な国際基準だが、各国法令そのものではない。","explanation":"Codex文書は国際的な基準・指針として各国制度の参考になるが、Codex自体がすべての国でそのまま法的義務になるわけではない。輸出時は、仕向国・地域、食品分類、製造施設、表示、衛生証明、輸入者の責任などを個別に確認する。","wrongReason":"DはCodexと国内法を同一視している。Aは様式・言語・保存期間などの違いを無視している。Bは民間合意を法令より優先している。","example":"同じ冷凍食品でも、EU、米国、台湾などで施設登録、表示、衛生証明、微生物基準、輸入者側の確認が異なるため、輸出案件ごとに要求一覧を作る。","terms":"Codex、輸出先法令、輸入条件、顧客要求","process":"輸出・法令確認","hazard":"共通","scope":"国際共通の考え方／具体的義務は仕向国・製品ごとに確認","sourceId":"S011","sourceUrl":"https://www.fao.org/fao-who-codexalimentarius/about-codex/faq/faq-detail/en/c/454753/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q094","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"EU向け輸出対応","difficulty":"レベル3","format":"現場判断","question":"日本の工場がEU向け食品の商談を進めています。工場にはHACCP計画がありますが、買い手からEUの衛生法令、製品別基準、記録の提示を求められました。最も適切な対応はどれか。","options":[{"key":"A","text":"HACCP計画があると伝え、それ以外の確認は断る"},{"key":"B","text":"EUの一般衛生規則と製品別規則、輸入条件、関係する加盟国・顧客要求を確認し、既存計画とのギャップと必要な証拠を整理する"},{"key":"C","text":"日本国内で販売できる製品なら、EUでもそのまま販売できると判断する"},{"key":"D","text":"英語へ翻訳したHACCP表紙だけを提出する"}],"correct":["B"],"conclusion":"EU向けでは、HACCP計画に加えて適用法令と製品別要求への適合を確認する。","explanation":"EUの食品衛生規則は、食品事業者に衛生管理とHACCP原則に基づく手順を求めているが、食品の種類によって追加規則、温度・微生物基準、施設承認、輸入証明などが関係する。既存計画を輸出先要求と照合し、手順、記録、責任者、証明書を整える。","wrongReason":"AはHACCP以外の法的要求を無視している。Cは日本法への適合をEU適合とみなしている。Dは運用と記録の証拠がない。","example":"EU向け動物性食品では、一般衛生規則だけでなく製品別衛生規則や施設・証明の条件を輸入者と確認し、対象ロットの温度記録やトレーサビリティを提示できるようにする。","terms":"EU食品衛生規則、HACCP手順、輸入条件、適合証拠","process":"EU向け輸出・監査","hazard":"共通","scope":"EU向けの一般原則／具体的要求は製品・加盟国・輸入条件により異なる","sourceId":"S012","sourceUrl":"https://eur-lex.europa.eu/eli/reg/2004/852/2021-03-24/eng","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q095","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"米国の製品別制度","difficulty":"レベル3","format":"四択","question":"米国向け食品のHACCP・予防管理制度について、最も適切な説明はどれか。","options":[{"key":"A","text":"ISO 22000認証があれば、FDAの規則確認は不要になる"},{"key":"B","text":"水産食品やジュースにはFDAの製品別HACCP規則があり、多くのその他食品ではFSMAの危害分析・リスクベース予防管理など、製品と施設に応じた規則を確認する"},{"key":"C","text":"輸入者だけが責任を持ち、海外製造者は製造工程を確認しなくてよい"},{"key":"D","text":"米国向け食品はすべて、同じHACCP規則だけに従う"}],"correct":["B"],"conclusion":"米国では、食品と施設によってHACCP規則やFSMAの適用関係が異なる。","explanation":"FDAは水産食品に21 CFR Part 123、ジュースにPart 120のHACCP規則を設けている。一方、多くのその他食品施設ではPart 117の危害分析・リスクベース予防管理が中心となり、免除・修正要件や輸入者のFSVPも関係し得る。対象製品と事業活動から適用規則を確認する。","wrongReason":"Dは製品別制度を一律化している。Aは民間認証を法令の代替にしている。Cは製造者側の工程管理責任を否定している。","example":"米国向け冷凍水産品、果汁飲料、焼菓子では、同じ米国向けでも適用するFDA規則と必要文書が異なるため、品目と工程を先に分類する。","terms":"Seafood HACCP、Juice HACCP、FSMA、予防管理、FSVP","process":"米国向け輸出・制度確認","hazard":"共通","scope":"米国制度／適用除外・修正要件を含め製品・施設ごとに確認","sourceId":"S013,S014","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-seafood-haccp-and-fda-food-safety-modernization-act\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-juice-haccp-and-fda-food-safety-modernization-act","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q096","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"HACCPとISO 22000","difficulty":"レベル3","format":"四択","question":"HACCPとISO 22000の関係として最も適切なものはどれか。","options":[{"key":"A","text":"HACCP計画とISO 22000は完全に同じものである"},{"key":"B","text":"ISO 22000は食品の味や外観だけを管理する品質規格である"},{"key":"C","text":"ISO 22000を使う場合、危害分析は不要になる"},{"key":"D","text":"ISO 22000はHACCP原則を組み込み、前提条件プログラム、コミュニケーション、マネジメントシステムなども含む食品安全マネジメントシステム規格である"}],"correct":["D"],"conclusion":"ISO 22000はHACCPを含む、より広い食品安全マネジメントシステムの枠組みである。","explanation":"HACCPは危害分析と重要な管理を中心とする方法である。ISO 22000はCodexのHACCP原則と適用手順を取り込み、前提条件プログラム、組織内外のコミュニケーション、責任、文書、評価、改善などを組み合わせて食品安全マネジメントシステムを構築する。","wrongReason":"Aは範囲の違いを無視している。Bは食品安全規格を品質だけの規格としている。CはISO 22000の中心要素である危害分析を否定している。","example":"HACCP表だけでなく、方針、責任権限、緊急事態対応、供給者管理、内部監査、マネジメントレビューなどを含めて運用する。","terms":"HACCP、ISO 22000、FSMS、PRP、マネジメントシステム","process":"食品安全マネジメントシステム","hazard":"共通","scope":"国際規格／使用時は現行版と改訂状況を確認","sourceId":"S015","sourceUrl":"https://www.iso.org/standard/65464.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q097","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"ISO 22000認証","difficulty":"レベル4","format":"四択","question":"ISO 22000認証を取得したい場合の説明として最も適切なものはどれか。","options":[{"key":"A","text":"ISO 22000の利用に認証は必須ではなく、認証を希望する場合は外部の認証機関による審査を受ける"},{"key":"B","text":"ISOのロゴを自社の認証マークとして自由に製品へ表示できる"},{"key":"C","text":"ISO本部が工場監査を行い、ISO自身が証明書を発行する"},{"key":"D","text":"一度認証を取得すれば、法令変更や工程変更があっても見直しは不要である"}],"correct":["A"],"conclusion":"ISOは規格を発行するが、組織の認証や証明書発行は外部の認証機関が行う。","explanation":"ISO 22000は認証を受けずに活用することもできる。第三者認証を希望する場合は、適切な認証機関を選び、規格要求への適合審査を受ける。ISO自体は認証を行わず、ISOロゴの使用にも制限がある。","wrongReason":"CはISOと認証機関の役割を混同している。Dは継続的な維持・変更管理を否定している。BはISOロゴの無断使用を認めている。","example":"証明書では、発行した認証機関、認証範囲、事業所、規格版、発行日・有効期限を確認し、認証機関の認定状況も必要に応じて確認する。","terms":"ISO認証、認証機関、認証範囲、ISOロゴ","process":"第三者認証","hazard":"共通","scope":"国際共通の説明／認定・認証制度の詳細は国と契約条件により確認","sourceId":"S015,S016","sourceUrl":"https://www.iso.org/standard/65464.html\nhttps://www.iso.org/certification.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q098","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"FSSC 22000の構成と版管理","difficulty":"レベル4","format":"四択","question":"FSSC 22000とISO 22000の関係として最も適切なものはどれか。","options":[{"key":"A","text":"FSSC 22000は食品安全とは関係のない財務監査制度である"},{"key":"B","text":"一度選んだFSSCの版は、スキームが更新されても永久に使用できる"},{"key":"C","text":"FSSC 22000認証には、ISO 22000に加えて、適用分野の前提条件プログラムとFSSCのスキーム追加要求などへの適合が必要である"},{"key":"D","text":"ISO 22000認証を取得すれば、自動的にFSSC 22000認証にもなる"}],"correct":["C"],"conclusion":"FSSC 22000は、ISO 22000だけでなくPRPとスキーム固有要求を組み合わせた認証スキームである。","explanation":"FSSC 22000はISO 22000の食品安全マネジメントシステム要求、適用分野の前提条件プログラム、FSSC追加要求と認証ルールで構成される。2026年5月にVersion 7が公開されており、監査時は移行期限と適用版を公式スキーム文書で確認する必要がある。","wrongReason":"Dは認証スキームの追加要求と別審査を無視している。Aは制度の目的を誤っている。Bは版改訂と移行管理を無視している。","example":"FSSC 22000の更新時は、認証機関から移行計画を入手し、追加要求、PRP規格、内部監査、文書改訂、教育の期限を管理する。","terms":"FSSC 22000、ISO 22000、PRP、追加要求、Version 7","process":"FSSC認証・版移行","hazard":"共通","scope":"2026年7月時点の情報／監査前に現行版と移行期限を再確認","sourceId":"S017,S018","sourceUrl":"https://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf\nhttps://www.fssc.com/insights/fssc-22000-version-7-key-changes/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q099","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"海外監査の証拠","difficulty":"レベル4","format":"複数選択","question":"海外の顧客・認証監査へ備える際、整合させておくべきものをすべて選んでください。","options":[{"key":"A","text":"適用法令・顧客要求の一覧と、改訂時に内容を見直す仕組み"},{"key":"B","text":"会社案内の英語版だけを準備し、現場記録は提示できない状態"},{"key":"C","text":"翻訳版があれば原文との一致や証明書の範囲は確認しない"},{"key":"D","text":"現場で使用している最新版のHACCP計画、工程図、手順と実際の記録"}],"correct":["A","D"],"conclusion":"監査では、文書、現場運用、記録、適用要求が一致していることが重要である。","explanation":"監査用に見栄えのよい資料を作るだけでは不十分である。管理された最新版の文書が現場で使用され、記録が実際の運用を示し、適用法令・顧客要求への対応が追跡できる必要がある。翻訳や証明書も原文、認証範囲、対象事業所、期限と一致させる。","wrongReason":"Cは翻訳・認証範囲の不一致を見逃す。Bは実際の管理と証拠を示せない。","example":"監査前に工程図を現場で歩いて確認し、英語版の改訂番号、温度記録、逸脱処置、校正証明、証明書のスコープを相互に照合する。","terms":"顧客監査、認証監査、文書管理、翻訳、認証範囲","process":"海外監査・文書提示","hazard":"共通","scope":"監査要求は規格・法令・顧客ごとに確認","sourceId":"S012,S017","sourceUrl":"https://eur-lex.europa.eu/eli/reg/2004/852/2021-03-24/eng\nhttps://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q100","categoryCode":"G","category":"海外対応・監査・規格との関係","subtheme":"海外対応の実施順序","difficulty":"レベル4","format":"手順並べ替え","question":"新しい国への輸出と顧客監査へ備える手順として、次の項目を論理的な順序に並べてください。A：仕向国、製品、施設、輸入者に適用される法令・規格・顧客要求を特定する　B：現在のHACCP・一般衛生管理・文書とのギャップを評価する　C：必要な手順変更、妥当性確認、教育、運用を行い、記録を蓄積する　D：内部で実施状況を検証し、不適合を是正してから申請・監査・出荷判定へ進む","options":[{"key":"A","text":"B→D→A→C"},{"key":"B","text":"C→A→D→B"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"A→B→C→D"}],"correct":["D"],"conclusion":"要求の特定、ギャップ評価、実装と記録、内部検証の順で海外対応を進める。","explanation":"最初に適用要求を確定しなければ、何を変更すべきか判断できない。次に現状とのギャップを整理し、必要な管理を実装して有効性を確認し、担当者を教育して記録を残す。最後に内部監査や記録レビューで実施状況を確認し、問題を是正してから外部審査や出荷判断へ進む。","wrongReason":"A・B・Cから始める選択肢は、適用要求を確定する前に変更や監査を進めており、必要条件の見落としにつながる。","example":"輸出プロジェクト表に、法令条項、要求事項、現状、対応責任者、期限、証拠、内部確認結果を記録し、出荷承認条件と結び付ける。","terms":"法令調査、ギャップ分析、変更管理、教育、内部監査","process":"海外輸出・認証準備","hazard":"共通","scope":"国際共通の進め方／個別要求は仕向国・制度ごとに確認","sourceId":"S011,S012,S013,S014,S015,S017","sourceUrl":"https://www.fao.org/fao-who-codexalimentarius/about-codex/faq/faq-detail/en/c/454753/\nhttps://eur-lex.europa.eu/eli/reg/2004/852/2021-03-24/eng\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-seafood-haccp-and-fda-food-safety-modernization-act\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-juice-haccp-and-fda-food-safety-modernization-act\nhttps://www.iso.org/standard/65464.html\nhttps://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第6回作成"},{"id":"Q101","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"ひき肉・内部汚染","difficulty":"レベル1","format":"四択","question":"同じ牛肉でも、ステーキとひき肉で加熱管理の考え方が異なる主な理由はどれか。","options":[{"key":"A","text":"ひき肉は必ず海外産だから"},{"key":"B","text":"ひく工程で表面にあった汚染が肉全体へ広がる可能性があるから"},{"key":"C","text":"ひき肉は色が濃いため、病原菌が見えにくいから"},{"key":"D","text":"ひき肉に含まれる脂肪が病原菌を増やすと決まっているから"}],"correct":["B"],"conclusion":"ひき肉では、表面由来の汚染が内部まで分散する可能性を考える。","explanation":"塊肉では汚染が主に表面にある場合でも、ひく・混合する工程によって汚染が製品内部へ広がる可能性がある。そのため、外側の焼き色だけでなく、製品全体に必要な加熱効果が得られる管理方法を設定する。","wrongReason":"Cは外観の問題に置き換えている。Dは脂肪だけで危害を決めている。Aは原産国と危害管理を混同している。","example":"ハンバーグの厚さや重量が変わる場合は、最も加熱されにくい条件で中心部の加熱効果を確認し、設備条件や測定方法を見直す。","terms":"ひき肉、STEC、内部汚染、加熱","process":"挽肉・成形・加熱","hazard":"生物的危害","scope":"国際共通の考え方／具体的加熱基準は製品・法令に従う","sourceId":"S019","sourceUrl":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat/ground-beef-and-food-safety","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q102","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"生卵を使用する非加熱食品","difficulty":"レベル2","format":"四択","question":"加熱せずに提供する自家製ドレッシングへ卵を使用します。最も適切な管理はどれか。","options":[{"key":"A","text":"酢を少量入れれば、条件確認なしに必ず安全になる"},{"key":"B","text":"完成品の見た目が正常であれば問題ない"},{"key":"C","text":"殻がきれいな生卵であれば、そのまま使用する"},{"key":"D","text":"殺菌済み殻付き卵または殺菌済み卵製品を使用するか、有効性を確認した別の管理を行う"}],"correct":["D"],"conclusion":"最終的に加熱しない卵料理では、生卵由来のサルモネラを別の方法で管理する。","explanation":"清潔で割れていない卵でもサルモネラを含む可能性がある。提供前に十分な加熱がない製品では、殺菌済み殻付き卵または殺菌済み卵製品を使うか、配合・処理で危害を制御できることを科学的に確認する必要がある。","wrongReason":"Cは外観だけで安全性を判断している。Aは酸の量、pH、接触時間などを確認していない。Bは病原菌を外観で判定している。","example":"マヨネーズ、ティラミス、ドレッシングなどでは、原料仕様書で殻付き卵または卵製品の殺菌処理を確認し、未殺菌卵が投入されないよう受入れと払い出しを区分する。","terms":"サルモネラ、殺菌済み卵、非加熱食品","process":"調合・非加熱製品","hazard":"生物的危害","scope":"国・業態の法令と製品条件を確認","sourceId":"S074","sourceUrl":"https://www.fda.gov/food/retail-food-industryregulatory-assistance-training/assuring-safety-eggs-and-menu-and-deli-items-made-raw-shell-eggs","checkedDate":"2026-07-25","status":"完成","audit":"監査済","note":"確認第2回で用語・出典精緻化"},{"id":"Q103","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"生乳と加熱殺菌","difficulty":"レベル1","format":"○×","question":"衛生的に搾乳し、農場の検査で異常がなければ、生乳に病原菌が存在する可能性はなくなるため、加熱殺菌は不要である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"衛生的な搾乳や検査はリスクを下げるが、生乳の病原菌リスクをゼロにはできない。","explanation":"生乳にはサルモネラ、病原性大腸菌、リステリアなどが存在する可能性がある。農場衛生と検査は重要だが、すべてのロットのすべての病原菌を保証するものではない。加熱殺菌などの管理は、対象製品と法令に基づいて設定する。","wrongReason":"Aは農場衛生と抜き取り検査だけで、原料の病原菌を完全に否定している。","example":"殺菌乳の製造では、原料乳の受入管理に加え、殺菌工程の温度・時間、流路切替、記録、殺菌後の再汚染防止を管理する。","terms":"生乳、加熱殺菌、原料管理","process":"乳受入れ・殺菌","hazard":"生物的危害","scope":"乳製品の法令・製品規格に従う","sourceId":"S021","sourceUrl":"https://www.fda.gov/food/buy-store-serve-safe-food/raw-milk-misconceptions-and-danger-raw-milk-consumption","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q104","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"米飯とBacillus cereus","difficulty":"レベル3","format":"現場判断","question":"炊飯後のご飯を室温で長時間置き、注文後に炒め直して提供する運用になっています。最も適切な判断はどれか。","options":[{"key":"A","text":"においに異常がなければ使用する"},{"key":"B","text":"炒め直せば、室温放置中に生じたすべての危害を必ず除去できる"},{"key":"C","text":"炊飯で生き残る芽胞と、放置中の増殖・毒素形成を評価し、速やかな冷却または適切な保温を行う"},{"key":"D","text":"炊飯した時点で無菌なので、保管条件は関係ない"}],"correct":["C"],"conclusion":"米飯では、炊飯後の時間・温度管理によってBacillus cereusの増殖と毒素形成を防ぐ。","explanation":"B. cereusの耐熱性芽胞は炊飯後も残る可能性がある。炊飯米を不適切な温度で保持すると菌が増殖し、耐熱性の毒素が形成される場合があり、短時間の再加熱だけでは安全性を回復できない可能性がある。","wrongReason":"Bは形成済み毒素を考慮していない。Dは芽胞の生残を無視している。Aは毒素や病原菌を官能で判定している。","example":"冷却販売する米飯は、容器の深さ、投入量、冷却機能力、最も冷えにくい位置を確認し、冷却記録と保管温度を管理する。","terms":"Bacillus cereus、芽胞、セレウリド、米飯","process":"炊飯・保温・冷却","hazard":"生物的危害","scope":"具体的な時間温度基準は製品・法令・手引書に従う","sourceId":"S022","sourceUrl":"https://www.cdc.gov/mmwr/preview/mmwrhtml/00025744.htm","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q105","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"加熱食肉の冷却","difficulty":"レベル3","format":"四択","question":"大きなロースト肉は必要な加熱条件を満たしましたが、その後ゆっくり冷却されています。冷却工程で特に検討すべき危害はどれか。","options":[{"key":"A","text":"芽胞を形成する菌が生き残り、冷却中に増殖する可能性"},{"key":"B","text":"包装デザインが変わること"},{"key":"C","text":"加熱済みなので、冷却中の生物的危害は存在しない"},{"key":"D","text":"製品の焼き色が薄くなることだけ"}],"correct":["A"],"conclusion":"加熱が完了しても、冷却中の芽胞形成菌の増殖を別に管理する必要がある。","explanation":"加熱で栄養細胞を減らしても、Clostridium perfringensなどの芽胞が残る可能性がある。大容量・高密度の食肉は中心部がゆっくり冷えるため、冷却条件を検証し、時間・温度履歴を管理する。","wrongReason":"Cは加熱後の増殖危害を無視している。DとBは主に品質・表示上の論点である。","example":"製品径、ラック間隔、冷却風量、積載量を変える場合は、最も冷えにくい条件で冷却曲線を確認する。","terms":"Clostridium perfringens、芽胞、冷却、安定化","process":"加熱後冷却","hazard":"生物的危害","scope":"具体的冷却基準は製品・法令・科学的根拠に従う","sourceId":"S023","sourceUrl":"https://www.fsis.usda.gov/guidelines/2021-0013","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q106","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"RTE食品とListeria管理","difficulty":"レベル3","format":"複数選択","question":"加熱後に包装前の環境へ露出する冷蔵RTE食品について、必要となり得る管理をすべて選んでください。","options":[{"key":"A","text":"衛生管理の有効性を環境モニタリングなどで検証する"},{"key":"B","text":"保存期間と温度を、リステリアの増殖可能性を考慮して設定する"},{"key":"C","text":"冷蔵または冷凍すればリステリアは自動的に消滅すると考える"},{"key":"D","text":"加熱後区域への原料・人・器具の交差を抑える"}],"correct":["A","B","D"],"conclusion":"RTE食品では、加熱後の再汚染防止、環境管理、保存条件を組み合わせる。","explanation":"包装前に環境へ露出し、その後に殺菌工程がないRTE食品では、設備・環境からのL. monocytogenes再汚染が重要になる。冷蔵温度でも増殖でき、冷凍だけで除去できないため、区域管理、洗浄・殺菌、環境モニタリング、時間・温度・保存期間を組み合わせる。","wrongReason":"Cは低温保存の効果を過大評価し、病原菌の生残・増殖可能性を無視している。","example":"スライサーや充填機の周辺は、食品接触面だけでなく、床、排水、脚部、カバー内部などの侵入・定着経路も確認する。","terms":"Listeria monocytogenes、RTE、環境モニタリング、保存期間","process":"加熱後・包装前","hazard":"生物的危害","scope":"製品が増殖を支持するか、後処理があるかで管理が異なる","sourceId":"S024","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q107","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"ヒスタミン形成魚","difficulty":"レベル2","format":"○×","question":"マグロなどでヒスタミンが一度形成されても、十分に加熱または冷凍すれば除去できる。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"形成されたヒスタミンは、洗浄、冷凍、加熱では除去できない。","explanation":"ヒスタミン形成魚では、死後の不適切な時間・温度管理により細菌の働きでヒスタミンが蓄積する。形成後の除去に頼るのではなく、漁獲後から迅速に冷却し、流通・受入れ・加工中の時間と温度を管理する。","wrongReason":"Aは、形成済みヒスタミンを後工程で消せると誤解している。","example":"受入れ時は魚体温度、氷の状態、輸送記録、必要に応じた官能検査やヒスタミン検査をHACCP計画に基づいて組み合わせる。","terms":"ヒスタミン、スコンブロトキシン、時間温度管理","process":"水産物受入れ・保管","hazard":"化学的危害","scope":"対象魚種と管理条件は水産物規則・HACCP計画に従う","sourceId":"S025","sourceUrl":"https://www.fda.gov/food/hfp-constituent-updates/fda-issues-final-compliance-policy-guide-scombrotoxin-histamine-forming-fish-and-fishery-products","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q108","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"生食用カキとVibrio","difficulty":"レベル2","format":"四択","question":"生食用カキのVibrio危害について、最も適切な管理はどれか。","options":[{"key":"A","text":"レモン汁や辛いソースをかければ、Vibrioを確実に死滅できる"},{"key":"B","text":"見た目とにおいが正常なら、危害はない"},{"key":"C","text":"承認された採取・供給経路、採取後の時間温度管理、必要な処理や加熱を管理する"},{"key":"D","text":"寒い季節だけ確認し、他の時期は管理しない"}],"correct":["C"],"conclusion":"生食用カキは、見た目では判断せず、採取源と時間温度管理、必要な処理で危害を管理する。","explanation":"Vibrioは自然環境に存在し、汚染したカキでも外観・におい・味が正常な場合がある。レモン汁、辛味、飲酒は有効な殺菌方法ではない。生食用として扱う場合は、採取区域、供給者、タグ・ロット、採取後の冷却などを管理する。","wrongReason":"Aは食品に加える調味料を殺菌工程と誤解している。Bは官能だけで判断している。Dは年間を通じた危害の可能性を無視している。","example":"殻付きカキは採取タグをロットへ結び付け、受入時刻、品温、輸送状態、採取区域の開閉情報を追跡できるようにする。","terms":"Vibrio、カキ、生食、採取区域、タグ","process":"貝類受入れ・提供","hazard":"生物的危害","scope":"国・地域の貝類衛生制度に従う","sourceId":"S026","sourceUrl":"https://www.cdc.gov/vibrio/prevention/vibrio-and-oysters.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q109","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"貝毒","difficulty":"レベル3","format":"四択","question":"二枚貝の麻痺性貝毒を管理する方法として、最も適切なものはどれか。","options":[{"key":"A","text":"味見をして異常がなければ出荷する"},{"key":"B","text":"監視された採取区域、採取禁止情報、正規供給者、ロット追跡で管理する"},{"key":"C","text":"出荷前に十分加熱し、毒を除去する"},{"key":"D","text":"冷凍して毒を分解する"}],"correct":["B"],"conclusion":"貝毒は通常の加熱や冷凍で除去できないため、採取源の管理が中心となる。","explanation":"麻痺性貝毒などの自然毒は、貝の見た目、におい、味では判断できず、通常の調理や冷凍で除去できない。公的な海域監視と採取規制、承認供給者、タグ・ロットの追跡によって汚染品の流通を防ぐ。","wrongReason":"CとDは毒を後工程で除去できると誤解している。Aは危険な官能確認であり、毒の有無を判定できない。","example":"採取区域が閉鎖された場合、対象日・海域・供給者のロットを直ちに検索し、出荷停止や回収判断ができるよう記録する。","terms":"麻痺性貝毒、PST、採取区域、供給者管理","process":"貝類受入れ・出荷","hazard":"化学的危害（自然毒）","scope":"対象毒素・基準・採取規制は国・地域ごとに確認","sourceId":"S027","sourceUrl":"https://www.fda.gov/food/alerts-advisories-safety-information/fda-advises-restaurants-and-retailers-not-serve-or-sell-and-consumers-not-eat-certain-oysters-0","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q110","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"真空包装生魚とボツリヌス菌","difficulty":"レベル4","format":"現場判断","question":"生魚を真空包装し、冷蔵流通する新製品を計画しています。担当者は「冷蔵品なので安全」と判断しています。最も適切な対応はどれか。","options":[{"key":"A","text":"Clostridium botulinumの増殖・毒素形成を危害分析し、厳格な温度管理や製品障壁、包装・流通条件の有効性を確認する"},{"key":"B","text":"真空包装すれば酸素が減るので、すべての病原菌リスクが下がる"},{"key":"C","text":"冷蔵庫の設定温度だけ決め、流通中と消費者段階は考えない"},{"key":"D","text":"開封後に加熱する表示だけで、製造・流通中の危害管理を省略する"}],"correct":["A"],"conclusion":"低酸素包装では、ボツリヌス菌の危害を製品・流通条件に合わせて評価する。","explanation":"真空包装やガス置換包装は、酸素を必要としないC. botulinumの増殖・毒素形成条件を作る場合がある。冷蔵という名称だけでは十分な管理にならず、温度履歴、保存期間、塩分、pH、水分活性、凍結流通などの障壁を科学的に確認する。","wrongReason":"Bは低酸素環境の危害を逆に理解している。Cは実際の流通温度と逸脱を無視している。Dは消費前の加熱だけへ依存している。","example":"新しい包装材や賞味期限を採用する場合は、最悪の温度条件を含めた試験、表示、物流記録、逸脱時の製品処置を一体で設計する。","terms":"真空包装、低酸素包装、Clostridium botulinum、障壁技術","process":"包装・冷蔵流通","hazard":"生物的危害","scope":"水産物の種類・包装・保存条件ごとに規則と科学的根拠を確認","sourceId":"S028","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-questions-and-answers-haccp-regulation-fish-and-fishery-products","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q111","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"粉末乳児用食品とCronobacter","difficulty":"レベル3","format":"四択","question":"粉末乳児用食品の危害分析として、最も適切な考え方はどれか。","options":[{"key":"A","text":"一般成人向け食品と同じ重大性で評価すれば十分である"},{"key":"B","text":"水分が少ないため、病原菌は生残できず危害分析は不要である"},{"key":"C","text":"完成品が粉末であれば、食品接触面の洗浄状態は関係ない"},{"key":"D","text":"Cronobacterなどは乾燥食品や環境で生残でき、乳児の重症化リスクを考慮して環境・設備・充填・包装を管理する"}],"correct":["D"],"conclusion":"乾燥状態は増殖を抑えても、Cronobacterの生残や環境からの汚染を否定できない。","explanation":"Cronobacterは低水分の粉末食品で生残しやすく、特に新生児、早産児、免疫が弱い乳児では重大な健康影響につながる。対象消費者の脆弱性を踏まえ、乾燥区域の衛生設計、水分侵入防止、環境管理、充填・包装を評価する。","wrongReason":"Bは生残と増殖を混同している。Cは環境由来汚染を無視している。Aは対象消費者による重大性の違いを考慮していない。","example":"乾燥充填室で水漏れが起きた場合は、通常清掃だけで終えず、汚染拡散、対象ロット、乾燥復旧、環境検査を計画に基づいて判断する。","terms":"Cronobacter、粉末乳児用食品、低水分、脆弱な消費者","process":"乾燥・充填・包装","hazard":"生物的危害","scope":"乳児用食品の専用法令・製品表示・対象者条件を確認","sourceId":"S029","sourceUrl":"https://www.fda.gov/food/foodborne-pathogens/cronobacter-sakazakii","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q112","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"スプラウトの危害管理","difficulty":"レベル3","format":"複数選択","question":"生または軽く加熱して食べるスプラウトの危害管理として、必要となり得るものをすべて選んでください。","options":[{"key":"A","text":"検査が陰性なら、工程異常のあるロットも無条件で出荷する"},{"key":"B","text":"種子の供給者・ロット・取扱い履歴を管理する"},{"key":"C","text":"発芽に使う水、設備、環境、作業者衛生を管理する"},{"key":"D","text":"出荷前に水洗いすれば、種子由来の病原菌は必ず除去できると考える"}],"correct":["B","C"],"conclusion":"スプラウトは、種子から発芽・出荷までの複数段階で微生物危害を管理する。","explanation":"発芽に適した暖かく湿った条件は、種子に付着したサルモネラなどの増殖にも適している。最終洗浄だけへ依存せず、種子供給、衛生、水、設備、工程検証、必要な検査とロット管理を組み合わせる。","wrongReason":"Aは検査結果だけで工程異常を無視している。Dは水洗いで病原菌を確実に除去できると誤解している。","example":"陽性や工程異常が出た場合に、同じ種子ロットから作られた製品と使用設備を追跡できるよう、投入から出荷まで記録を結び付ける。","terms":"スプラウト、種子、発芽水、サルモネラ、工程検証","process":"種子受入れ・発芽・出荷","hazard":"生物的危害","scope":"対象国のスプラウト規則・検査要件を確認","sourceId":"S030","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-reducing-microbial-food-safety-hazards-production-seed-sprouting","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q113","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"冷凍食品と微生物","difficulty":"レベル1","format":"○×","question":"食品を完全に冷凍すれば、製品中の病原菌はすべて死滅するため、解凍後の加熱条件は重要ではない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"冷凍は多くの病原菌の増殖を止めるが、すべてを死滅させる工程ではない。","explanation":"冷凍中に生残する病原菌があるため、非加熱または半加熱の冷凍食品では、原料・製造段階の汚染防止と、最終的に必要な加熱効果を確保する必要がある。外観が加熱済みに見える製品でも、表示どおりの調理が必要な場合がある。","wrongReason":"Aは冷凍を殺菌工程と誤解し、解凍後や調理時の危害を無視している。","example":"冷凍ハンバーグや冷凍生地では、中心部まで必要な加熱が得られる調理方法と表示を、製品サイズ・機器差を考慮して確認する。","terms":"冷凍、生残、加熱表示、中心温度","process":"冷凍・解凍・最終加熱","hazard":"生物的危害","scope":"製品表示と法令上の調理・加熱条件を確認","sourceId":"S031","sourceUrl":"https://www.fda.gov/food/buy-store-serve-safe-food/test-your-safety-knowledge-about-ready-cook-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q114","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"冷凍ベリーとウイルス","difficulty":"レベル3","format":"現場判断","question":"加熱せずに使用する冷凍ベリーについて、「冷凍済みなのでウイルス危害は管理済み」と判断しています。最も適切な対応はどれか。","options":[{"key":"A","text":"解凍時に香りを確認すれば、ウイルス汚染を判断できる"},{"key":"B","text":"冷凍でノロウイルスやA型肝炎ウイルスは必ず死滅するため、そのまま使用する"},{"key":"C","text":"色が濃いベリーだけを選別すればよい"},{"key":"D","text":"原料産地、水、作業者衛生、供給者管理、必要な処理を評価し、冷凍をウイルス除去工程として扱わない"}],"correct":["D"],"conclusion":"冷凍ベリーでは、冷凍をウイルスの殺滅工程とみなさず、前段階の汚染防止を重視する。","explanation":"ベリーは農業用水、収穫・選別作業者、容器や設備などからウイルスに汚染される可能性がある。冷凍してもウイルスは生残し得るため、供給者・農場・加工工程の管理や、製品用途に応じた有効な処理を検討する。","wrongReason":"Bは冷凍の効果を過大評価している。CとAは外観・香りでウイルスを判定している。","example":"スムージーやデザートへ非加熱使用する場合は、供給者仕様、原料ロット、処理履歴、回収連絡先を製品ロットへ結び付ける。","terms":"冷凍ベリー、ノロウイルス、A型肝炎、供給者管理","process":"原料受入れ・冷凍保管・使用","hazard":"生物的危害","scope":"原料産地・用途・輸出入条件に応じて管理","sourceId":"S032","sourceUrl":"https://www.fda.gov/food/hfp-constituent-updates/fda-sampling-frozen-berries-harmful-viruses","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q115","categoryCode":"H","category":"食品別危害分析・製品別ケース","subtheme":"低水分食品とSalmonella","difficulty":"レベル2","format":"四択","question":"ピーナッツバターや香辛料などの低水分食品について、最も適切な考え方はどれか。","options":[{"key":"A","text":"増殖しにくくてもサルモネラが長期間生残することがあり、低水分状態では加熱抵抗性が高まる場合がある"},{"key":"B","text":"低水分食品は、環境衛生や水分侵入を管理する必要がない"},{"key":"C","text":"加熱条件は高水分食品の条件をそのまま使用できる"},{"key":"D","text":"水分が少ない食品では、サルモネラは直ちに死滅する"}],"correct":["A"],"conclusion":"低水分食品では、病原菌が増殖しなくても生残し、工程条件によっては加熱しにくくなる。","explanation":"低水分の食品ではサルモネラが長期間生残する可能性があり、水分活性や食品組成によって加熱抵抗性が高くなる場合がある。原料供給者、乾燥区域の衛生、水分侵入防止、製品に適した殺菌工程を管理する。","wrongReason":"Dは生残を否定している。Bは乾燥環境での定着・拡散を無視している。Cは食品マトリックスの違いを考慮していない。","example":"ナッツペーストを生地へ混合する場合は、塊のまま残るか十分に水和するかによって殺菌効果が変わる可能性を評価する。","terms":"低水分食品、サルモネラ、水分活性、加熱抵抗性","process":"乾燥原料・殺菌・充填","hazard":"生物的危害","scope":"製品ごとに殺菌工程の妥当性確認が必要","sourceId":"S033","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-measures-address-risk-contamination-salmonella-species-food-containing-peanut","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q116","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"米飯冷却設備の停止","difficulty":"レベル3","format":"現場判断","question":"炊飯直後に冷却機が停止し、複数バッチの米飯が冷却前の状態で滞留しました。最初の対応として最も適切なものはどれか。","options":[{"key":"A","text":"表面が乾燥しているバッチだけ出荷する"},{"key":"B","text":"対象バッチを特定・保留し、炊飯終了からの時間温度履歴を記録して安全性を評価し、設備復旧後の再開条件を確認する"},{"key":"C","text":"冷却機が直った後に全量を冷却すれば、滞留時間は確認しなくてよい"},{"key":"D","text":"再加熱すれば必ず安全になるため、そのまま次工程へ送る"}],"correct":["B"],"conclusion":"冷却設備の停止時は、対象製品を分け、滞留時間と温度履歴に基づいて処置する。","explanation":"炊飯米ではB. cereusの芽胞が生き残り、冷却待ちの間に増殖・毒素形成が進む可能性がある。設備復旧だけでなく、どのバッチが、いつから、どの温度条件にあったかを確認して製品処置を決める。","wrongReason":"Cは異常期間の影響を無視している。Dは形成済み毒素の可能性を考慮していない。Aは外観で安全性を判断している。","example":"炊飯終了時刻、搬送停止時刻、品温、積載量を記録し、保留区画を設け、承認者が再処理・廃棄などを判断する。","terms":"設備停止、米飯、冷却逸脱、製品保留","process":"炊飯後冷却","hazard":"生物的危害","scope":"処置基準は製品と科学的根拠に基づいて事前設定","sourceId":"S022","sourceUrl":"https://www.cdc.gov/mmwr/preview/mmwrhtml/00025744.htm","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q117","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"RTE区域の環境陽性","difficulty":"レベル4","format":"現場判断","question":"包装前のRTE食品ライン近くの排水溝からListeria monocytogenesが検出されました。食品接触面の検査は陰性です。最も適切な対応はどれか。","options":[{"key":"A","text":"排水溝へ薬剤を一度かければ、原因調査や再検査は不要である"},{"key":"B","text":"環境陽性は必ず完成品陽性を意味するため、条件確認なしに全製品を永久廃棄する"},{"key":"C","text":"位置・区域・人や器具の動線を評価し、必要な製品保留、追加採取、集中的清掃、原因調査、再発防止を行う"},{"key":"D","text":"食品接触面が陰性なので、記録だけ残して通常運転を続ける"}],"correct":["C"],"conclusion":"環境陽性は、製品への移行経路と汚染の定着範囲を調べ、状況に応じて迅速に是正する。","explanation":"排水溝は食品接触面ではないが、飛沫、車輪、靴、清掃器具、作業動線を通じてRTE区域へ汚染が広がる可能性がある。陽性位置、継続性、区域、食品露出、過去結果を確認し、製品と環境の処置をリスクに基づいて決める。","wrongReason":"Dは早期警告を無視している。Aは一時的処置だけで原因と定着を確認していない。Bは環境結果と製品結果を一律に同一視している。","example":"排水溝周辺だけでなく、近接する床、脚部、車輪、清掃用具、食品接触面への経路を追加採取し、清掃後の再確認を行う。","terms":"環境モニタリング、Listeria、区域、根本原因","process":"RTE包装前区域","hazard":"生物的危害","scope":"製品保留・検査・出荷判断は環境ゾーン、製品露出、規則、社内計画に基づく","sourceId":"S024,S035","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods\nhttps://www.fda.gov/food/sampling-protect-food-supply/environmental-sampling","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q118","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"ヒスタミン形成魚の受入逸脱","difficulty":"レベル3","format":"複数選択","question":"ヒスタミン形成魚を受け入れたところ、輸送中の温度記録が欠落し、氷も一部溶けています。適切な対応をすべて選んでください。","options":[{"key":"A","text":"ロットを保留し、供給者・輸送者へ時間温度履歴を確認する"},{"key":"B","text":"HACCP計画に基づき、魚体状態、氷、官能、必要なヒスタミン検査などを組み合わせて評価する"},{"key":"C","text":"受入れ判断と根拠を記録せず、口頭だけで処理する"},{"key":"D","text":"到着時に冷たければ、途中の温度履歴を確認せず自動的に合格とする"}],"correct":["A","B"],"conclusion":"受入時点の冷たさだけでなく、漁獲後からの時間温度履歴とロット状態を評価する。","explanation":"ヒスタミンは不適切な温度履歴の途中で形成される可能性があり、到着後に再冷却しても除去できない。記録欠落は管理の証拠が不足した状態であるため、ロットを保留し、計画に定めた受入確認と供給者是正を行う。","wrongReason":"Cは判断根拠と供給者是正を追跡できない。Dは到着時の一時点だけで過去の温度逸脱を否定している。","example":"同じ運送便の複数ロットへ影響する可能性があるため、車両、積載位置、出発時刻、氷の補給、データロガーの故障範囲を確認する。","terms":"ヒスタミン、受入CCP、輸送記録、供給者是正","process":"水産物受入れ","hazard":"化学的危害","scope":"受入基準・サンプリング・検査方法は魚種とHACCP計画に従う","sourceId":"S025","sourceUrl":"https://www.fda.gov/food/hfp-constituent-updates/fda-issues-final-compliance-policy-guide-scombrotoxin-histamine-forming-fish-and-fishery-products","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q119","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"冷凍調理品の表示変更","difficulty":"レベル4","format":"現場判断","question":"冷凍の加熱調理用食品について、内容量と容器形状を変更しましたが、旧製品と同じ電子レンジ加熱表示をそのまま使用する予定です。最も適切な対応はどれか。","options":[{"key":"A","text":"新しい内容量・形状・初期温度・機器差で中心部の加熱効果を再確認し、必要なら表示と製造条件を変更する"},{"key":"B","text":"外側が熱くなれば、中心部の確認は不要である"},{"key":"C","text":"消費者が追加加熱する可能性があるため、表示の妥当性確認は不要である"},{"key":"D","text":"原材料が同じなら、加熱表示の再確認は不要である"}],"correct":["A"],"conclusion":"内容量や容器が変わると加熱分布が変わるため、調理表示を再度妥当性確認する。","explanation":"冷凍調理品では、部分加熱済みに見えても病原菌が生残する可能性がある。製品厚さ、重量、容器、配置、電子レンジ出力、休止時間などが変わると冷点が変化するため、代表条件と厳しい条件で調理方法を確認する。","wrongReason":"Dは製品物性と熱移動の変化を無視している。Bは表面温度だけで判断している。Cは安全管理を消費者の追加行動へ丸投げしている。","example":"変更品を販売する前に複数の家庭用機器で温度分布を確認し、攪拌、休止時間、加熱時間、製品配置を表示へ反映する。","terms":"冷凍調理品、調理表示、冷点、妥当性確認","process":"製品変更・表示","hazard":"生物的危害","scope":"表示要件と検証方法は製品・販売国に応じて確認","sourceId":"S006,S031","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation\nhttps://www.fda.gov/food/buy-store-serve-safe-food/test-your-safety-knowledge-about-ready-cook-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q120","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"包装停止とブドウ球菌毒素","difficulty":"レベル3","format":"手順並べ替え","question":"手作業で調製したサンドイッチ具材が、包装機停止中に不適切な温度で長時間滞留しました。対応を論理的な順序に並べてください。A：停止時間帯と対象ロットを特定して保留する　B：温度・時間・取扱い状況から黄色ブドウ球菌の増殖と毒素形成を評価する　C：再加熱だけに頼らず、科学的根拠と手順に基づいて製品処置を決める　D：設備停止の原因を是正し、温度管理と再開条件を確認する","options":[{"key":"A","text":"A→B→C→D"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"C→A→D→B"},{"key":"D","text":"D→C→B→A"}],"correct":["A"],"conclusion":"対象品を保留し、毒素形成の可能性を評価して製品処置と工程復旧を行う。","explanation":"黄色ブドウ球菌は作業者の皮膚や鼻などから食品へ移る可能性があり、温度管理が悪いと毒素を作ることがある。菌自体を加熱で減らせても、形成済み毒素は通常の再加熱で破壊できないため、時間温度履歴と取扱い状況に基づいて処置する。","wrongReason":"B・C・Dから始める選択肢は、影響製品の流出防止と範囲特定が後回しになっている。","example":"包装停止時に具材を自動的に冷蔵保管へ移す手順、滞留開始時刻の記録、再開前の品温確認を設定する。","terms":"Staphylococcus aureus、耐熱性毒素、包装停止、時間温度管理","process":"調製・包装","hazard":"生物的危害（毒素）","scope":"具体的処置基準は製品・時間温度・法令・科学的根拠に従う","sourceId":"S034","sourceUrl":"https://www.cdc.gov/staph-food-poisoning/about/index.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第7回作成"},{"id":"Q121","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"未承認供給者からの緊急調達","difficulty":"レベル3","format":"現場判断","question":"主原料が不足し、購買担当者が評価していない新しい供給者から同等品を緊急購入しようとしています。最も適切な対応はどれか。","options":[{"key":"A","text":"価格が安ければ、安全性の確認は不要である"},{"key":"B","text":"最初のロットだけ製品検査に合格すれば、供給者評価は永久に不要である"},{"key":"C","text":"原料名が同じなら、確認せず使用する"},{"key":"D","text":"使用前に仕様、危害情報、アレルゲン、製造方法、輸送条件、必要な証明を確認し、承認または特別受入れの判断を記録する"}],"correct":["D"],"conclusion":"緊急調達でも、原料の危害と供給者の管理能力を確認してから使用する。","explanation":"同じ名称の原料でも、産地、工程、アレルゲン取扱い、微生物・化学物質・異物の管理、包装、輸送条件が異なる可能性がある。緊急時の特別承認手順を定め、必要な確認と責任者の判断を記録する。","wrongReason":"Cは名称だけで同等性を判断している。Aは価格を食品安全より優先している。Bは一回の完成品検査だけで継続的な供給者管理を代替している。","example":"代替香辛料を使う場合は、殺菌処理、アレルゲン交差接触、異物規格、検査成績、輸送条件を確認し、対象ロットを限定して承認する。","terms":"供給者承認、緊急調達、原料仕様、変更管理","process":"原料調達・受入れ","hazard":"共通","scope":"国際共通の原則／具体的承認要件は法令・顧客条件に従う","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q122","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"解凍室の冷却停止","difficulty":"レベル3","format":"現場判断","question":"夜間に解凍室の冷却機が停止し、冷凍肉の表面温度と停止時間が正確に分かりません。最も適切な対応はどれか。","options":[{"key":"A","text":"中心部が凍っていれば、全量をそのまま使用する"},{"key":"B","text":"対象ロットを保留し、停止時刻、室温、品温、包装状態、解凍液、代替記録を集めて安全性を評価する"},{"key":"C","text":"冷却機を再起動すれば、過去の温度履歴は問題にならない"},{"key":"D","text":"表面を水洗いして使用する"}],"correct":["B"],"conclusion":"解凍中の設備停止では、表面部の温度履歴と交差汚染を確認して製品を処置する。","explanation":"解凍中は中心部が凍っていても表面が早く温まり、微生物が増殖する可能性がある。記録不足の場合は、異常の開始範囲を安全側に設定し、室温・品温・警報・保守記録などから影響を評価する。","wrongReason":"Aは表面の温度上昇を無視している。Cは過去の温度履歴を取り消せない。Dは水洗いを安全性回復の手段としている。","example":"データロガー、冷凍機警報、入退室記録、電源履歴を照合し、影響ロットを特定して、再加熱・用途変更・廃棄などを手順に基づいて判断する。","terms":"解凍逸脱、温度履歴、設備故障、製品保留","process":"解凍","hazard":"生物的危害","scope":"処置基準は食品・時間温度・法令・科学的根拠に従う","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q123","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"加熱ライン速度の変更","difficulty":"レベル3","format":"四択","question":"連続加熱ラインの生産量を増やすため、コンベヤ速度を上げる予定です。最も適切な対応はどれか。","options":[{"key":"A","text":"製品表面が熱ければ、中心部の確認は不要である"},{"key":"B","text":"変更後の最初の製品が合格なら、それ以降の条件は確認しない"},{"key":"C","text":"最も厳しい製品条件で滞留時間と加熱効果を再確認し、管理基準、警報、記録を必要に応じて更新する"},{"key":"D","text":"設定温度を変えなければ、滞留時間の確認は不要である"}],"correct":["C"],"conclusion":"ライン速度の変更は滞留時間と加熱効果へ影響するため、再評価が必要である。","explanation":"連続式加熱では、温度だけでなく製品が加熱区域に滞留する時間が重要である。速度、製品厚さ、投入量、初期温度、流れが変わる場合は、最悪条件で工程能力を再確認する。","wrongReason":"Dは温度と時間の組合せを無視している。Aは表面温度だけで判断している。Bは工程の継続的安定性を確認していない。","example":"速度設定へアクセス制限を設け、変更履歴を保存し、許容範囲を外れた場合に警報またはライン停止が作動することを試験する。","terms":"コンベヤ速度、滞留時間、工程変更、再妥当性確認","process":"連続加熱","hazard":"生物的危害","scope":"国際共通の原則／具体的加熱条件は製品ごとに妥当性確認","sourceId":"S006","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q124","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"冷却記録の欠測","difficulty":"レベル4","format":"現場判断","question":"冷却工程のデータロガー電池が切れ、3時間分の温度記録がありません。冷却機は現在正常に動いています。最も適切な対応はどれか。","options":[{"key":"A","text":"現在の温度が基準内なので、欠測期間の製品をそのまま出荷する"},{"key":"B","text":"正常に見える温度を推定して記録欄へ書き込む"},{"key":"C","text":"欠測期間の対象製品を保留し、他の温度計、室温、開始・終了時刻、設備履歴などで評価し、根拠が不足する場合は定めた処置を行う"},{"key":"D","text":"ロガーの電池だけ交換し、製品への影響は確認しない"}],"correct":["C"],"conclusion":"記録欠測では、測定機器の復旧と欠測期間の製品影響を別々に確認する。","explanation":"冷却記録がない期間は、工程が基準内だったことを証明できない。独立した記録や製品温度から科学的に評価できる場合を除き、通常品と区分して処置する必要がある。","wrongReason":"Aは過去の冷却履歴を現在値だけで判断している。Bは実測していない値の記入である。Dは対象製品への影響を無視している。","example":"バックアップ温度計や冷却室の監視記録を照合し、ロガーの電池残量警報、予防交換、通信断監視を追加する。","terms":"欠測、データロガー、冷却記録、影響評価","process":"冷却・記録","hazard":"生物的危害","scope":"国際共通の原則／製品処置は科学的根拠と承認手順に従う","sourceId":"S001,S008","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q125","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"殺菌剤濃度の逸脱","difficulty":"レベル2","format":"複数選択","question":"製造中の確認で、器具の殺菌に使用する薬剤濃度が手順の範囲より低かったことが分かりました。必要な対応をすべて選んでください。","options":[{"key":"A","text":"薬剤名が殺菌剤であれば、濃度不足でも効果は同じと判断する"},{"key":"B","text":"製品への影響を確認せず、設備だけを復旧する"},{"key":"C","text":"薬剤の調製・供給系を是正し、正しい条件で再洗浄・再殺菌する"},{"key":"D","text":"対象時間、設備・器具、製品への接触範囲を特定する"}],"correct":["C","D"],"conclusion":"殺菌条件の逸脱では、衛生復旧と影響製品の評価を行う。","explanation":"殺菌効果は薬剤の種類だけでなく、濃度、接触時間、温度、表面の清浄度、使用方法などに左右される。基準外が見つかった場合は、影響範囲を特定し、正しい条件で衛生状態を回復する。","wrongReason":"Bは影響製品の評価を省いている。Aは必要な濃度と使用条件を無視している。","example":"自動希釈装置の薬液切れ、吸込不良、導電率計のずれを確認し、始業時だけでなく使用中の確認頻度を見直す。","terms":"殺菌剤、濃度、接触時間、衛生逸脱","process":"洗浄・殺菌","hazard":"生物的・化学的危害","scope":"薬剤表示・設備・食品の手順に従い、残留も確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q126","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"アレルゲン切替の検証不合格","difficulty":"レベル4","format":"現場判断","question":"アレルゲン含有製品から非含有製品へ切り替えた後、始業前のアレルゲン拭取り検査が不合格でした。最も適切な対応はどれか。","options":[{"key":"A","text":"製造を開始せず、不合格箇所と洗浄手順を確認して再洗浄し、合格確認後に開始する"},{"key":"B","text":"目視で汚れがなければ、そのまま製造を開始する"},{"key":"C","text":"最初の製品だけ廃棄すれば、検証結果は無視できる"},{"key":"D","text":"検査結果を記録せず、別の場所だけ再検査する"}],"correct":["A"],"conclusion":"切替検証が不合格なら、原因を是正し、有効性を確認するまで製造を開始しない。","explanation":"アレルゲンは目に見えない残留でも健康被害につながる可能性がある。拭取り位置、分解範囲、洗浄方法、器具、再組立てを確認し、必要な再洗浄と再検証を行う。","wrongReason":"Bは目視だけでアレルゲン残留を判断している。Cは残留の影響範囲を根拠なく限定している。Dは不適合の隠蔽になる。","example":"連続して同じ箇所が不合格になる場合は、ガスケット、ベルト裏、ホッパー接合部などの衛生設計と分解手順を見直す。","terms":"アレルゲン、切替洗浄、拭取り検査、再洗浄","process":"ライン切替・始業前","hazard":"化学的危害（アレルゲン）","scope":"対象アレルゲン・検査法・合格基準は妥当性確認が必要","sourceId":"S001,S004","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content\nhttps://www.fda.gov/media/71976/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q127","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"金属検出機の排除不良","difficulty":"レベル3","format":"手順並べ替え","question":"運転中に金属検出機は反応しましたが、排除装置が詰まり、対象製品が正常品側へ流れた可能性があります。対応を論理的な順序に並べてください。A：ラインと出荷を止め、前回正常確認以降の製品を保留する　B：排除装置、センサー、満杯・詰まり検知を点検し、機能試験を行う　C：保留製品を正常な検出条件で再検査し、排除品を評価する　D：原因、製品処置、再発防止を記録して再開を承認する","options":[{"key":"A","text":"D→C→B→A"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"A→B→C→D"},{"key":"D","text":"C→A→D→B"}],"correct":["C"],"conclusion":"排除不良では、影響製品を止め、機能復旧後に再検査と原因是正を行う。","explanation":"検出部が反応しても、排除装置や排除確認センサーが機能しなければ異物品が流出する可能性がある。検出・排除・排除確認・排除箱管理を一つのシステムとして確認する。","wrongReason":"A・B・Dから始める選択肢は、疑わしい製品の流出防止と影響範囲の特定を後回しにしている。","example":"排除箱満杯、空気圧不足、タイミングずれ、ベルト速度変更などを確認し、テストピースを複数位置で通して排除を確認する。","terms":"金属検出、排除装置、排除確認、再検査","process":"異物検出・包装後","hazard":"物理的危害","scope":"検出・排除条件は製品特性とHACCP計画に従う","sourceId":"S007","sourceUrl":"https://www.mhlw.go.jp/content/11130500/000796466.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q128","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"真空包装のシール不良","difficulty":"レベル2","format":"四択","question":"加熱後の冷蔵真空包装製品で、シール部にしわと食品の噛み込みが多数見つかりました。最も適切な対応はどれか。","options":[{"key":"A","text":"不良部分を手で押さえれば出荷できる"},{"key":"B","text":"対象ロットを保留し、シール強度・漏れ・汚染、包装条件、製品の安全性と保存条件への影響を評価する"},{"key":"C","text":"外箱に入れるため、一次包装の不良は問題にならない"},{"key":"D","text":"真空度が高く見えれば、そのまま出荷する"}],"correct":["B"],"conclusion":"シール不良は、再汚染、漏れ、保存条件の破綻につながるためロットを評価する。","explanation":"食品の噛み込み、しわ、温度・圧力・時間の不足は、密封性を低下させる可能性がある。包装が危害管理や保存期間に関係する場合、シール検査の妥当性と逸脱時処置を定める。","wrongReason":"Dは外観上の真空だけで密封性を判断している。Aは正式な再包装・検査ではない。Cは一次包装の機能を無視している。","example":"シールバーの汚れ、製品充填量、袋位置、温度・時間・圧力、冷却状態を確認し、漏れ試験やシール強度試験を行う。","terms":"シール不良、包装完全性、真空包装、保存期間","process":"包装・密封","hazard":"生物的・物理的危害","scope":"包装条件と製品安全性の関係を製品ごとに妥当性確認","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q129","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"冷蔵庫の温度逸脱","difficulty":"レベル3","format":"複数選択","question":"冷蔵庫の扉が長時間開いており、製品温度が保管基準を外れた可能性があります。必要な対応をすべて選んでください。","options":[{"key":"A","text":"対象製品、庫内位置、時間温度履歴を特定する"},{"key":"B","text":"冷蔵庫を冷やし直せば、過去の温度逸脱は自動的に解消すると考える"},{"key":"C","text":"製品特性と危害に基づいて安全性を評価し、保留・処置する"},{"key":"D","text":"扉、警報、作業方法、積載状態の原因を是正する"}],"correct":["A","C","D"],"conclusion":"冷蔵逸脱では、時間温度履歴、製品特性、原因を確認する。","explanation":"同じ庫内でも扉付近、上段、中心部で温度履歴が異なる場合がある。単に再冷却するのではなく、微生物増殖や品質・表示条件への影響を評価し、対象品を処置する。","wrongReason":"Bは、逸脱中に起きた微生物増殖や危害を再冷却で取り消せると誤解している。","example":"扉開放警報、入出庫時間、庫内マッピング、製品温度の抜取りを組み合わせ、影響範囲を必要以上に広げず、狭めすぎないよう特定する。","terms":"冷蔵逸脱、時間温度履歴、庫内マッピング、製品保留","process":"冷蔵保管","hazard":"生物的危害","scope":"許容時間と処置は食品・温度・法令・科学的根拠に従う","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q130","categoryCode":"I","category":"工程別トラブル・逸脱判断","subtheme":"水道停止時の代替水","difficulty":"レベル2","format":"四択","question":"工場の水道が停止し、出所と水質を確認していない貯水タンクの水を食品接触面の洗浄へ使う案が出ました。最も適切な対応はどれか。","options":[{"key":"A","text":"洗浄剤を多く入れれば、水質確認は不要である"},{"key":"B","text":"製造終了後に検査すれば、使用中の管理は不要である"},{"key":"C","text":"透明な水であれば使用する"},{"key":"D","text":"用途に適した安全な水質が確認できるまで食品・食品接触面への使用を止め、必要な代替水と復旧後の洗浄・評価を行う"}],"correct":["D"],"conclusion":"水供給の異常時は、水質を確認できない水を食品や食品接触面へ使用しない。","explanation":"食品工場の水は、用途に応じて食品を汚染しない安全な品質である必要がある。断水時は、飲用可能な代替水、タンク・配管の衛生、復旧後のフラッシングや再洗浄を確認する。","wrongReason":"Cは外観だけで水質を判断している。Aは薬剤で未知の化学・微生物危害を解決できると考えている。Bは問題発生後の検査だけへ依存している。","example":"代替給水車を使用する場合は、水源、ホース、接続部、タンクの洗浄記録と、使用用途を確認し、通常水道との交差接続を防ぐ。","terms":"安全な水、代替給水、断水、復旧確認","process":"水使用工程・洗浄","hazard":"生物的・化学的危害","scope":"水質基準と緊急時手順は国・地域の法令に従う","sourceId":"S036","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.37","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q131","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"衛生ゾーニングと動線","difficulty":"レベル2","format":"四択","question":"生原料区域と加熱後RTE区域を分ける主な目的として、最も適切なものはどれか。","options":[{"key":"A","text":"原料、人、器具、台車などから加熱後製品への交差汚染を減らすため"},{"key":"B","text":"従業員の歩く距離を長くするため"},{"key":"C","text":"清掃回数を減らすため"},{"key":"D","text":"区域ごとに製品の価格を変えるため"}],"correct":["A"],"conclusion":"衛生ゾーニングは、汚染度の異なる区域間の交差汚染を抑える。","explanation":"壁や床の線だけでなく、人、原料、包装材、器具、廃棄物、空気、排水の流れを設計し、加熱後の製品へ汚染が戻らないようにする必要がある。","wrongReason":"BとDは衛生上の目的ではない。Cはゾーニングを清掃省略の理由にしている。","example":"RTE区域専用の衣服、器具、台車を設定し、原料区域から持ち込む物品は洗浄・殺菌または受渡し手順を通す。","terms":"衛生ゾーニング、動線、RTE区域、交差汚染","process":"施設設計・運用","hazard":"生物的危害","scope":"施設・製品・危害に応じて区域と管理を設定","sourceId":"S024","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q132","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"区域間の空気流","difficulty":"レベル3","format":"四択","question":"生原料区域と加熱後RTE区域の空気流を設計する際、最も適切な考え方はどれか。","options":[{"key":"A","text":"扉を常時開放し、圧力差をなくす"},{"key":"B","text":"汚染度の高い原料区域からRTE区域へ空気を流す"},{"key":"C","text":"RTE区域を相対的に清浄側とし、汚染区域からの空気・粉じん・飛沫の移動を抑える"},{"key":"D","text":"空気流は食品汚染に影響しないため確認しない"}],"correct":["C"],"conclusion":"空気流は、汚染区域から清浄区域へ汚染を運ばない方向に設計する。","explanation":"空調、扉、排気、室圧、温度差によって、粉じん、エアロゾル、結露が移動する可能性がある。RTE区域では、製品と危害に応じて圧力差、フィルタ、扉管理を確認する。","wrongReason":"Bは汚染を清浄側へ運ぶ。Dは空気を汚染経路として無視している。Aはゾーニングと室圧管理を損なう。","example":"煙試験や差圧計で扉開閉時を含む流れを確認し、原料側の排気増加やフィルタ目詰まりがRTE区域へ与える影響を監視する。","terms":"空気流、室圧、RTE区域、エアロゾル","process":"空調・施設設計","hazard":"生物的・物理的危害","scope":"空気管理の必要性と条件は製品・工程・施設に応じて設定","sourceId":"S024","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q133","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"結露水の落下","difficulty":"レベル3","format":"現場判断","question":"加熱後の露出食品の上にある冷却配管から結露水が落ち始めました。最も適切な対応はどれか。","options":[{"key":"A","text":"製品表面を後で乾燥させればよい"},{"key":"B","text":"水は透明なので、そのまま製造を続ける"},{"key":"C","text":"床だけを拭き、配管と製品は確認しない"},{"key":"D","text":"食品を保護・保留し、落下範囲と影響製品を評価して、断熱・排水・空調など結露原因を是正する"}],"correct":["D"],"conclusion":"結露は汚れや微生物を食品へ運ぶ可能性があるため、製品保護と原因是正が必要である。","explanation":"配管や天井の結露水は、周囲のほこり、微生物、腐食物を含む可能性がある。露出食品へ落下する場合は、対象時間と位置を特定し、通常品と区分して処置する。","wrongReason":"Bは透明な水を安全とみなしている。Cは汚染源と影響製品を確認していない。Aは付着した危害を乾燥で除去できると考えている。","example":"蒸気負荷、室温・湿度、断熱材の破損、冷媒配管の温度、ドレンの詰まりを確認し、再発時に製品上へ落ちない構造へ改善する。","terms":"結露、ドレン、断熱、露出食品","process":"加熱後・冷却・包装前","hazard":"生物的・物理的危害","scope":"国際共通の原則／施設基準は国・地域の法令に従う","sourceId":"S036","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.37","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q134","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"排水溝逆流と高圧洗浄","difficulty":"レベル4","format":"現場判断","question":"RTE区域の排水溝が逆流し、作業者が高圧ホースで流そうとしています。最も適切な対応はどれか。","options":[{"key":"A","text":"排水溝へ香料を入れてにおいを消す"},{"key":"B","text":"製造と製品移動を止め、影響区域を隔離し、飛沫を抑えて排水障害を除去し、清掃・殺菌・製品影響評価を行う"},{"key":"C","text":"食品接触面だけ拭き、床・車輪・清掃器具は確認しない"},{"key":"D","text":"高圧水で素早く流せば、周囲の製品や設備は保護しなくてよい"}],"correct":["B"],"conclusion":"排水逆流時は、エアロゾルと動線による汚染拡散を防ぎながら復旧する。","explanation":"高圧ホースは排水由来の汚染を飛沫やエアロゾルとして広げる可能性がある。製品、設備、台車、靴、清掃器具への影響を評価し、区画を復旧した後に確認する。","wrongReason":"Dは汚染拡散を促す。Aは原因を解決しない。Cは非食品接触面からの再汚染経路を無視している。","example":"排水詰まり、勾配、処理能力、逆止め、製造排水量を確認し、再発時の停止・隔離・清掃手順を訓練する。","terms":"排水逆流、高圧ホース、エアロゾル、区域隔離","process":"排水・RTE区域","hazard":"生物的危害","scope":"RTE区域の衛生計画と施設排水基準に従う","sourceId":"S024","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q135","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"低水分区域への水分侵入","difficulty":"レベル1","format":"○×","question":"低水分RTE食品の乾燥区域では、床や設備に水が残っても製品自体が乾燥しているため、病原体の環境定着リスクは増えない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"乾燥区域への水分侵入は、環境病原体の増殖・拡散リスクを高める。","explanation":"低水分食品は病原菌の増殖を支持しにくくても、製造環境へ水分が入るとSalmonellaやCronobacterなどが増殖し、設備や床へ定着する可能性がある。水の使用を管理し、完全な乾燥と復旧確認を行う。","wrongReason":"Aは製品の水分と製造環境の水分を混同している。","example":"屋根漏れ、結露、配管漏れ、湿式清掃が起きた場合は、影響区域を隔離し、製品・環境への影響、乾燥状態、必要な環境検査を確認する。","terms":"低水分食品、水分侵入、Salmonella、乾燥区域","process":"乾燥製造区域","hazard":"生物的危害","scope":"低水分RTE食品向けの考え方／具体的手順は製品と施設に応じる","sourceId":"S037","sourceUrl":"https://www.fda.gov/media/184815/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q136","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"COP部品の洗浄と保管","difficulty":"レベル2","format":"複数選択","question":"機械から取り外してCOP洗浄する部品の管理として、適切なものをすべて選んでください。","options":[{"key":"A","text":"汚れた部品と洗浄済み部品の動線・置場を分ける"},{"key":"B","text":"洗浄後の部品を濡れたまま保護せず保管する"},{"key":"C","text":"部品の内部、穴、シール溝まで洗浄・すすぎ・必要な殺菌を行う"},{"key":"D","text":"洗浄済み部品を床へ直接置き、使用前に軽く拭く"}],"correct":["A","C"],"conclusion":"COP部品は、洗浄前後の交差汚染を防ぎ、乾燥・保護・部品管理まで行う。","explanation":"取り外し部品は複雑な接合部や内部に汚れが残りやすい。洗浄済み部品が床、飛沫、汚れた台車、作業者の手から再汚染されないよう、清潔側の保管と組立て確認が必要である。","wrongReason":"Bは再汚染と微生物増殖を招く。Dは洗浄済み部品を床から再汚染させる。","example":"部品番号入りラック、汚染側と清潔側の受渡し、乾燥時間、部品数、組立て方向を写真付き手順で管理する。","terms":"COP、部品洗浄、乾燥、清潔保管","process":"分解洗浄・再組立て","hazard":"生物的・物理的危害","scope":"国際共通の原則","sourceId":"S001,S024","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/draft-guidance-industry-control-listeria-monocytogenes-ready-eat-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q137","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"清掃用具の色分け","difficulty":"レベル1","format":"○×","question":"清掃用具を区域別に色分けすれば、用具の洗浄・殺菌・乾燥・保管状態を確認しなくても交差汚染を完全に防げる。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"色分けは識別を助けるが、清掃用具自体の衛生管理の代わりにはならない。","explanation":"色分けは誤使用を減らす方法の一つである。しかし、ブラシやスクイージーが汚れたまま、濡れたまま、床に置かれていれば、同じ区域内でも汚染を広げる可能性がある。","wrongReason":"Aは、識別だけで用具の衛生状態と正しい使用が保証されると誤解している。","example":"用具ごとに使用区域、洗浄方法、交換基準、乾燥場所を決め、破損や毛の脱落も点検する。","terms":"清掃用具、色分け、交差汚染、乾燥保管","process":"清掃・衛生管理","hazard":"生物的・物理的危害","scope":"国際共通の原則","sourceId":"S001","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q138","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"食品接触用圧縮空気","difficulty":"レベル2","format":"四択","question":"食品や食品接触面へ直接吹き付ける圧縮空気の管理として、最も適切なものはどれか。","options":[{"key":"A","text":"空気は目に見えないため、汚染源にはならない"},{"key":"B","text":"油、水分、微生物、粒子などで食品を汚染しないよう、用途に応じた処理、フィルタ、配管、点検を行う"},{"key":"C","text":"コンプレッサーが新しければ、フィルタ交換は不要である"},{"key":"D","text":"床掃除用のエアガンと同じ配管・ノズルを食品へ使用する"}],"correct":["B"],"conclusion":"食品接触用の圧縮空気は、食品を汚染しない品質と設備状態を維持する。","explanation":"コンプレッサー油、凝縮水、配管の錆、フィルタ破損、吸気位置などが汚染源になる可能性がある。食品へ直接触れる用途では、危害分析に基づいて処理方法と確認頻度を決める。","wrongReason":"Aは空気を汚染経路として無視している。Cは保守を省略している。Dは清掃区域から汚染を持ち込む。","example":"最終フィルタの差圧・交換履歴、ドレン、油分、微生物・粒子の確認を用途とリスクに応じて設定する。","terms":"圧縮空気、フィルタ、油分、水分、粒子","process":"乾燥・搬送・包装","hazard":"生物的・化学的・物理的危害","scope":"用途・製品・適用規格に応じて空気品質基準を設定","sourceId":"S008","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q139","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"環境モニタリングの設計","difficulty":"レベル3","format":"四択","question":"RTE食品工場の環境モニタリング計画として、最も適切なものはどれか。","options":[{"key":"A","text":"陽性結果は監査前に削除する"},{"key":"B","text":"毎回同じ清潔な場所だけを採取し、陽性が出ないことを目標にする"},{"key":"C","text":"完成品検査を行えば、環境採取は常に不要である"},{"key":"D","text":"食品接触面への移行経路、区域、設備構造、過去の陽性傾向を踏まえて採取場所・頻度・時期を設定し、結果を傾向分析する"}],"correct":["D"],"conclusion":"環境モニタリングは、汚染を見つけて是正するためにリスクに基づいて設計する。","explanation":"固定点だけでなく、排水、床、車輪、設備脚部、カバー内部、食品接触面に近い場所など、汚染の侵入・定着・移行経路を考慮する。単発結果だけでなく、場所・菌株・時期の傾向を分析する。","wrongReason":"Bは見つけやすい問題を避けている。Cは完成品の抜取り検査だけへ依存している。Aは記録の完全性を破壊する。","example":"設備変更、工事、水漏れ、陽性再発の後は、通常採取に加えて調査採取を増やし、是正後の効果を確認する。","terms":"環境モニタリング、採取ゾーン、傾向分析、seek and destroy","process":"RTE・低水分区域","hazard":"生物的危害","scope":"環境病原体が重要な危害となる製品・工程で適用","sourceId":"S035,S037","sourceUrl":"https://www.fda.gov/food/sampling-protect-food-supply/environmental-sampling\nhttps://www.fda.gov/media/184815/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q140","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"始業前衛生確認の不合格","difficulty":"レベル4","format":"手順並べ替え","question":"始業前点検でスライサーの刃の裏に食品残渣が見つかりました。対応を論理的な順序に並べてください。A：製造開始を止め、不合格箇所と影響設備を特定する　B：必要な分解を行い、再洗浄・すすぎ・殺菌する　C：目視と計画した検証方法で再確認する　D：結果を記録し、合格後に権限者が製造開始を承認する","options":[{"key":"A","text":"C→A→D→B"},{"key":"B","text":"A→B→C→D"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"B→D→A→C"}],"correct":["B"],"conclusion":"始業前不合格では、製造を止め、再洗浄と再確認の後に開始する。","explanation":"目視で残渣が見つかった設備は衛生状態が回復していない。残渣の原因となる分解範囲、洗浄方法、作業手順を確認し、再洗浄後にリスクに応じた検証を行う。","wrongReason":"A・C・Dから始める選択肢は、製造開始の停止と不合格範囲の特定を後回しにしている。","example":"同じ箇所の不合格が繰り返される場合は、刃の取外し方法、カバー、シール、洗浄時間、照明、点検位置を根本原因として見直す。","terms":"始業前点検、目視検査、再洗浄、衛生検証","process":"始業前・スライサー","hazard":"生物的・物理的危害","scope":"検証方法は対象危害・設備・洗浄手順に応じて設定","sourceId":"S001,S037","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content\nhttps://www.fda.gov/media/184815/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第8回作成"},{"id":"Q141","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"粘着テープによる仮修理","difficulty":"レベル2","format":"四択","question":"食品が露出する充填機の近くで、割れた樹脂カバーを粘着テープで仮修理しています。最も適切な対応はどれか。","options":[{"key":"A","text":"製品への影響とテープ・破片の混入リスクを評価し、管理された一時措置と早期の恒久修理、修理後確認を行う"},{"key":"B","text":"食品接触部でなければ、清掃性や破損状態を確認しなくてよい"},{"key":"C","text":"テープが剥がれていなければ、期限を決めず使用し続ける"},{"key":"D","text":"テープの色を設備と同じにすれば、異物リスクはなくなる"}],"correct":["A"],"conclusion":"仮修理は恒久対策にせず、異物・清掃性・製品影響を管理する。","explanation":"粘着テープ、結束具、段ボールなどの仮修理は、剥離片、粘着剤、汚れの蓄積、洗浄不能部を生む可能性がある。やむを得ない一時措置では、責任者、期限、点検頻度、製品保護を定め、適切な部品へ交換する。","wrongReason":"Cは一時措置を恒久化している。Dは色だけで剥離や汚染を防げない。Bは非接触部からの落下・飛散と清掃性を無視している。","example":"仮修理一覧に設備、位置、材質、実施日、期限、点検者を登録し、シフトごとに状態を確認して恒久修理を完了する。","terms":"仮修理、粘着テープ、異物、変更管理","process":"設備保守・充填","hazard":"物理的・化学的危害","scope":"国際共通の原則／一時修理の可否は製品・位置・社内基準に従う","sourceId":"S008,S039","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.35","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q142","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"中空フレームへの液体侵入","difficulty":"レベル3","format":"現場判断","question":"洗浄後、機械の中空フレーム内部から茶色い液体が食品コンベヤ付近へ流れ出しました。最も適切な対応はどれか。","options":[{"key":"A","text":"液体が少量なら、食品へ触れても問題ない"},{"key":"B","text":"フレームへさらに洗浄水を注入し、乾燥確認なしで再開する"},{"key":"C","text":"製造を止めて影響製品を区分し、侵入口・内部汚染・排出経路を調べ、中空部を完全密閉するか、内部を点検・洗浄・排水できる構造へ改修する"},{"key":"D","text":"外側を拭き、内部は見えないので製造を続ける"}],"correct":["C"],"conclusion":"中空構造は、液体が侵入しない完全密閉、または内部を点検・洗浄・排水できる構造にする。","explanation":"密閉不良の中空フレームは、洗浄水、製品残渣、微生物、腐食物を内部へため、後から漏出させる可能性がある。単に侵入口を塞ぐだけでなく、内部状態と影響製品を確認し、完全密閉するか、内部を確実に点検・洗浄・排水できる構造へ改修する。","wrongReason":"Dは隠れた汚染源を残している。Aは量だけで危害を否定している。Bは汚染を広げ、液体を残す可能性がある。","example":"修理後に漏れ試験と衛生確認を行い、中空部を使用しない設計、完全密閉、または内部を点検・洗浄・排水できる構造を検討する。","terms":"中空フレーム、液体侵入、排水性、腐食","process":"設備設計・洗浄","hazard":"生物的・化学的・物理的危害","scope":"具体的構造は適用する衛生設計規格に従う","sourceId":"S008,S009","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40\nhttps://www.3-a.org/news/3-a-ssi-updates-foundational-hygienic-design-standard","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"確認第2回で衛生設計表現を精密化"},{"id":"Q143","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"コンベヤベルトのほつれ","difficulty":"レベル3","format":"現場判断","question":"製造中にコンベヤベルト端部のほつれと欠けが見つかり、欠けた部分が回収できていません。最も適切な対応はどれか。","options":[{"key":"A","text":"ラインを止め、最後の正常確認以降の製品を保留し、欠片の捜索、製品影響、ベルト交換、原因調査を行う"},{"key":"B","text":"ベルトが動いているため、製造終了まで使用する"},{"key":"C","text":"ほつれをハサミで切り、記録せず再開する"},{"key":"D","text":"後段に金属検出機があるため、樹脂片の確認は不要である"}],"correct":["A"],"conclusion":"ベルト欠損時は、異物の所在と影響製品を確認し、設備を正常な状態へ戻す。","explanation":"樹脂やゴムの破片は金属検出機で検出できない場合がある。欠損時刻、ベルト点検履歴、製品の通過範囲を確認し、対象製品を通常品と分けて評価する。","wrongReason":"Bは異物発生を継続させる。Cは欠片と原因を確認していない。Dは検出装置の対象外となる異物を無視している。","example":"ベルト蛇行、スクレーパー接触、ローラー段差、張力、洗浄剤劣化を調べ、交換後に追跡防止と始業前点検を確認する。","terms":"コンベヤベルト、樹脂片、欠損、設備点検","process":"搬送・設備保守","hazard":"物理的危害","scope":"国際共通の原則","sourceId":"S008,S051","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.40\nhttps://www.fsis.usda.gov/policy/fsis-directives/7310.5","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q144","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"製造区域内の工事管理","difficulty":"レベル4","format":"手順並べ替え","question":"稼働中の包装区域に隣接して天井工事を行います。食品汚染を防ぐ手順として、次の項目を論理的な順序に並べてください。A：工事範囲・粉じん・工具・空気流・製品露出を事前評価し、停止・隔離方法を決める　B：製品と設備を保護し、工事区域・作業者・工具・廃棄物の動線を管理する　C：工事後に異物除去、清掃・必要な殺菌、設備・環境確認を行う　D：確認結果を記録し、権限者が製造再開を承認する","options":[{"key":"A","text":"B→D→A→C"},{"key":"B","text":"C→A→D→B"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"A→B→C→D"}],"correct":["D"],"conclusion":"工事は事前評価、隔離、復旧清掃、再開確認の順で管理する。","explanation":"天井・壁・配管工事では、粉じん、金属片、断熱材、工具、害虫侵入口、空気流変化などが食品汚染源になる。稼働区域との分離と工事後の衛生復旧を変更管理として実施する。","wrongReason":"A・B・Cから始める選択肢は、工事前の危害評価と製品保護を後回しにしている。","example":"工事許可書に養生、負圧・排気、工具本数、部材、作業時間、清掃範囲、環境採取、初品確認を記載する。","terms":"工事管理、粉じん、工具管理、再開確認","process":"施設工事・包装区域","hazard":"生物的・物理的危害","scope":"国際共通の原則／施設・製品リスクに応じて管理","sourceId":"S038,S039","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.20\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.35","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q145","categoryCode":"J","category":"衛生設計・洗浄・環境衛生","subtheme":"設備下の滞留水","difficulty":"レベル1","format":"○×","question":"設備下の床に水が長時間たまっていても、食品が床へ直接触れなければ、衛生上の管理は不要である。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"滞留水は、微生物、害虫、飛沫、車輪や靴による汚染拡散の原因になり得る。","explanation":"設備下の液だまりは、排水不良、漏れ、清掃不足の兆候であり、Listeriaなどの環境病原体が定着する場所になる可能性がある。床勾配、排水、設備脚部、清掃アクセスを改善する。","wrongReason":"Aは床から食品接触面・器具・人への間接的な汚染経路を無視している。","example":"滞留水の発生時刻と原因を記録し、スクイージーで移動させるだけでなく、配管漏れ、床勾配、排水能力を是正する。","terms":"滞留水、排水、設備下、環境病原体","process":"床・排水・設備周辺","hazard":"生物的危害","scope":"国際共通の原則","sourceId":"S036,S039","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.37\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.35","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q146","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"芽胞と栄養細胞","difficulty":"レベル2","format":"四択","question":"芽胞を作る細菌について、最も適切な説明はどれか。","options":[{"key":"A","text":"加熱工程があれば、冷却と保管の管理は不要になる"},{"key":"B","text":"芽胞は増殖中の細菌そのもので、通常の冷却で必ず死滅する"},{"key":"C","text":"芽胞は耐熱性を持つ休眠状態で、加熱後に生残し、条件が整うと発芽・増殖する場合がある"},{"key":"D","text":"芽胞を作る菌は食品中で毒素を作ることがない"}],"correct":["C"],"conclusion":"芽胞形成菌では、加熱時の生残と加熱後の発芽・増殖を分けて考える。","explanation":"BacillusやClostridiumの一部は、耐熱性の芽胞を形成する。加熱で栄養細胞を減らしても芽胞が残る可能性があるため、冷却、保温、保存条件で発芽・増殖を抑える。","wrongReason":"Bは芽胞と増殖中の細胞を混同している。Dは毒素形成の可能性を否定している。Aは加熱後管理を省略している。","example":"大量調理品では、加熱条件だけでなく、容器深さ、冷却速度、再加熱、保温をHACCP計画で一体管理する。","terms":"芽胞、栄養細胞、発芽、Bacillus、Clostridium","process":"加熱・冷却・保管","hazard":"生物的危害","scope":"国際共通の微生物学的原則","sourceId":"S040","sourceUrl":"https://www.fda.gov/files/food/published/Bad-Bug-Book-2nd-Edition-%28PDF%29.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q147","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"形成済み毒素と再加熱","difficulty":"レベル2","format":"四択","question":"黄色ブドウ球菌が増殖して毒素を作った可能性がある食品について、最も適切な考え方はどれか。","options":[{"key":"A","text":"においが正常なら毒素は存在しない"},{"key":"B","text":"菌の増殖と毒素形成を時間温度管理で防ぎ、毒素形成が疑われる食品は再加熱だけで安全と判断しない"},{"key":"C","text":"冷凍すれば形成済み毒素は消える"},{"key":"D","text":"十分に再加熱すれば、形成済み毒素を必ず無害化できる"}],"correct":["B"],"conclusion":"耐熱性毒素は、菌を減らす再加熱だけでは安全性を回復できない場合がある。","explanation":"S. aureusのエンテロトキシンやB. cereusの一部毒素は耐熱性を持つ。重要なのは、作業者からの汚染と、不適切な温度での増殖・毒素形成を予防することである。","wrongReason":"DとCは形成済み毒素を後工程で除去できると誤解している。Aは毒素を官能で判断している。","example":"調理後に手作業で盛付ける具材は、小分け、冷却、作業時間、手指衛生を管理し、長時間滞留を防ぐ。","terms":"耐熱性毒素、Staphylococcus aureus、Bacillus cereus","process":"調理後・盛付け・保管","hazard":"生物的危害（毒素）","scope":"具体的処置は食品・時間温度・科学的根拠に従う","sourceId":"S034,S040","sourceUrl":"https://www.cdc.gov/staph-food-poisoning/about/index.html\nhttps://www.fda.gov/files/food/published/Bad-Bug-Book-2nd-Edition-%28PDF%29.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q148","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"リステリアと冷蔵温度","difficulty":"レベル1","format":"○×","question":"Listeria monocytogenesは冷蔵温度で増殖できないため、冷蔵RTE食品の保存期間はリステリア管理に影響しない。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"Listeria monocytogenesは冷蔵中でも生残・増殖できるため、温度と保存期間が重要である。","explanation":"冷蔵は多くの細菌の増殖を遅くするが、L. monocytogenesは低温でも増殖できる。加熱後再汚染を防ぎ、製品が増殖を支持するかを確認して保存条件を設定する。","wrongReason":"Aは冷蔵をリステリアの殺菌・完全抑制工程として扱っている。","example":"長い賞味期限の冷蔵RTE食品では、環境管理、後処理、温度逸脱、保存試験を組み合わせて評価する。","terms":"Listeria monocytogenes、冷蔵、保存期間、RTE","process":"冷蔵保管・賞味期限設定","hazard":"生物的危害","scope":"製品特性と法令に応じて管理","sourceId":"S041","sourceUrl":"https://www.fda.gov/food/foodborne-pathogens/listeria-listeriosis","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q149","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"ノロウイルスと体調不良者","difficulty":"レベル3","format":"現場判断","question":"RTE食品を盛り付ける作業者が勤務中に嘔吐しました。最も適切な対応はどれか。","options":[{"key":"A","text":"症状が一度だけなら報告不要とする"},{"key":"B","text":"作業者が触れた製品だけ水洗いして出荷する"},{"key":"C","text":"手袋を交換すれば、そのまま作業を続ける"},{"key":"D","text":"食品取扱いから外し、対象食品と区域を保護・区分し、嘔吐物処理と清掃・消毒を手順に基づいて行う"}],"correct":["D"],"conclusion":"嘔吐・下痢のある作業者は食品取扱いから外し、広範な汚染拡散を防ぐ。","explanation":"ノロウイルスは少量でも感染し、嘔吐物の飛沫や手指から食品・設備へ広がる。作業者の就業制限、対象食品の処置、専用の嘔吐物処理、周辺清掃を行う。","wrongReason":"Cは手袋だけで既存汚染を解決していない。Aは報告と初動を遅らせる。Bはウイルスを水洗いで確実に除去できると考えている。","example":"嘔吐場所周辺の露出食品、器具、ドアノブ、床、作業着を確認し、復帰条件は地域の法令と社内手順に従う。","terms":"ノロウイルス、嘔吐、就業制限、RTE食品","process":"盛付け・食品取扱い","hazard":"生物的危害","scope":"就業制限期間と消毒方法は国・地域の法令・手順に従う","sourceId":"S042","sourceUrl":"https://www.cdc.gov/norovirus/communication-resources/facts-for-food-workers.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q150","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"生食用魚の寄生虫","difficulty":"レベル3","format":"四択","question":"生食用として提供する魚の寄生虫危害について、最も適切な管理はどれか。","options":[{"key":"A","text":"金属検出機を通せば、寄生虫を除去できる"},{"key":"B","text":"目視で寄生虫が見えなければ、管理は不要である"},{"key":"C","text":"表面を酢で洗えば、すべての寄生虫を確実に死滅できる"},{"key":"D","text":"魚種・養殖条件・食べ方を評価し、必要な場合は妥当性確認された冷凍または加熱条件を適用する"}],"correct":["D"],"conclusion":"寄生虫危害は、魚種・生育環境・生食用途に応じて冷凍や加熱で管理する。","explanation":"寄生虫は目視検査だけで完全に除去できない場合がある。野生・養殖、餌管理、魚種、提供方法を踏まえ、必要な冷凍・加熱条件と記録を設定する。","wrongReason":"Bは目視の限界を無視している。Cは酢洗浄を殺虫工程としている。Aは検出原理が異なる。","example":"供給者証明、魚種、養殖方法、冷凍開始・終了時刻、中心温度をロットへ結び付ける。","terms":"寄生虫、生食用魚、冷凍、供給者証明","process":"水産物受入れ・冷凍・提供","hazard":"生物的危害","scope":"具体的冷凍条件は販売国・魚種・工程の規則に従う","sourceId":"S043","sourceUrl":"https://www.fda.gov/media/80637/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q151","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"カビ毒の管理","difficulty":"レベル3","format":"複数選択","question":"穀類やナッツ類のカビ毒管理として、適切な対応をすべて選んでください。","options":[{"key":"A","text":"基準を超えた原料を正常原料と混ぜて濃度を下げる"},{"key":"B","text":"リスクに応じた代表的なサンプリングと検査、選別を行う"},{"key":"C","text":"高水分・かび・虫害などの異常ロットを区分し、保管中の水分上昇を防ぐ"},{"key":"D","text":"供給者、産地、収穫・乾燥・保管条件と規格を確認する"}],"correct":["B","C","D"],"conclusion":"カビ毒は、供給・乾燥・保管・サンプリングを組み合わせて管理する。","explanation":"カビ毒は原料中に不均一に分布する場合があり、外観だけでは評価できない。供給者管理、湿度・温度管理、選別、適切なサンプリング・分析を危害分析に基づいて行う。","wrongReason":"Aは不適合原料を希釈して使用する考えであり、適切な管理ではない。","example":"高リスク産地や異常気象の年度では、供給者確認と検査頻度を増やし、受入ロットと製品ロットを追跡する。","terms":"カビ毒、アフラトキシン、サンプリング、供給者管理","process":"穀類・ナッツ受入れ・保管","hazard":"化学的危害（自然毒）","scope":"対象毒素・食品・基準は国・地域の法令に従う","sourceId":"S044","sourceUrl":"https://www.fda.gov/food/natural-toxins-food/mycotoxins","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q152","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"アレルゲン交差接触","difficulty":"レベル2","format":"四択","question":"食品アレルゲンの「交差接触」の説明として、最も適切なものはどれか。","options":[{"key":"A","text":"本来含まない食品へアレルゲンが意図せず混入すること"},{"key":"B","text":"原料の価格が変わること"},{"key":"C","text":"病原菌が生食品から加熱済み食品へ移ることだけを指す"},{"key":"D","text":"製品の色や味が他製品と似ること"}],"correct":["A"],"conclusion":"アレルゲン交差接触は、本来含まない食品へアレルゲンが意図せず入ることである。","explanation":"共用設備、粉じん、再加工品、器具、作業者、保管、切替不良などによりアレルゲンが移る可能性がある。微生物の交差汚染とは危害と管理方法が異なる。","wrongReason":"Cは微生物の交差汚染だけを説明している。DとBは食品安全上のアレルゲン混入ではない。","example":"アレルゲン含有原料は識別・区分し、製造順序、切替洗浄、再加工品、包装表示を一つの管理計画で扱う。","terms":"アレルゲン交差接触、共用設備、切替","process":"原料保管・製造・包装","hazard":"化学的危害（アレルゲン）","scope":"対象アレルゲンと表示義務は販売国の法令に従う","sourceId":"S045","sourceUrl":"https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/food-allergies","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q153","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"配合変更とアレルゲン表示","difficulty":"レベル4","format":"現場判断","question":"製品の配合へごまを追加しましたが、包装ラインには旧ラベルが残っています。最も適切な対応はどれか。","options":[{"key":"A","text":"少量の配合変更なので、旧ラベルを使用する"},{"key":"B","text":"旧ラベルを隔離し、新配合と表示を照合して承認し、切替前後の製品・包材を特定して誤表示を防ぐ"},{"key":"C","text":"「原料が変更される場合があります」とだけ表示する"},{"key":"D","text":"苦情が出た場合にラベルを直す"}],"correct":["B"],"conclusion":"配合変更時は、原料・規格・表示・包材・製造切替を同期させる。","explanation":"ごまなど表示対象アレルゲンを追加した場合、旧ラベル使用は未表示アレルゲンにつながる。変更承認、在庫包材、ラインクリアランス、初品・定期確認を行う。","wrongReason":"Aは量だけで表示義務と健康影響を判断している。Cは正確な原材料・アレルゲン表示の代替にならない。Dは事後対応である。","example":"変更管理表で配合、BOM、原料規格、ラベル版、製造開始日、旧資材廃棄を連動させる。","terms":"配合変更、ごま、ラベル照合、ラインクリアランス","process":"製品設計・包装切替","hazard":"化学的危害（アレルゲン）","scope":"表示対象と方法は販売国の現行法令に従う","sourceId":"S046,S047","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-questions-and-answers-regarding-food-allergen-labeling-edition-5\nhttps://www.fda.gov/media/172318/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q154","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"殺菌とアレルゲン除去","difficulty":"レベル2","format":"四択","question":"共用ラインのアレルゲン切替洗浄について、最も適切な説明はどれか。","options":[{"key":"A","text":"香料を使えば、アレルゲン残留を隠せる"},{"key":"B","text":"殺菌剤をかければ、アレルゲンたんぱく質も必ず除去される"},{"key":"C","text":"微生物を減らす殺菌と、アレルゲン残留を物理的・化学的に除去する洗浄は目的が異なる"},{"key":"D","text":"目視で汚れがなければ、洗浄方法の有効性確認は不要である"}],"correct":["C"],"conclusion":"アレルゲン管理では、殺菌だけでなく残留たんぱく質を除去できる洗浄が必要である。","explanation":"殺菌剤は微生物管理を目的とするため、アレルゲンたんぱく質の除去を保証しない。食品、設備、洗剤、時間、機械的作用を考慮し、代表箇所で洗浄の有効性を確認する。","wrongReason":"Bは殺菌とアレルゲン除去を同一視している。Dは見えない残留を無視している。Aは危害を解決しない。","example":"ベルト、ガスケット、ホッパー、粉体集塵部などの最悪箇所を選び、拭取りや製品検査で切替洗浄を検証する。","terms":"アレルゲン洗浄、殺菌、たんぱく質残留、検証","process":"切替洗浄","hazard":"化学的危害（アレルゲン）","scope":"検査法・合格基準は対象アレルゲンと工程に応じて妥当性確認","sourceId":"S047","sourceUrl":"https://www.fda.gov/media/172318/download","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q155","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"金属検出機と製品影響","difficulty":"レベル3","format":"現場判断","question":"乾燥製品用に設定した金属検出機へ、水分と塩分の多い新製品を通すと誤検出が増えました。最も適切な対応はどれか。","options":[{"key":"A","text":"感度を大きく下げ、確認せず運転する"},{"key":"B","text":"誤検出品を正常品へ戻し、記録しない"},{"key":"C","text":"新製品と包装条件で製品影響を評価し、代表テストピース、位置、向き、速度を使って検出・排除条件を再設定する"},{"key":"D","text":"乾燥製品で合格した設定なので、新製品での確認は不要である"}],"correct":["C"],"conclusion":"金属検出感度は製品の水分・塩分・温度・包装などに影響されるため、製品別に確認する。","explanation":"導電性の高い製品は製品影響を起こし、感度や安定性が変わる可能性がある。感度を下げるだけではなく、対象異物を検出できる設定と排除機能を妥当性確認する。","wrongReason":"Aは異物検出能力を確認せず低下させる。Bは追跡性を失わせる。Dは製品条件の違いを無視している。","example":"製造開始、終了、品種切替時に、鉄・非鉄・ステンレスのテストピースを製品内の異なる位置で確認する。","terms":"金属検出、製品影響、感度、テストピース","process":"包装後・異物検出","hazard":"物理的危害","scope":"検出限界は製品・包装・装置ごとに妥当性確認","sourceId":"S048","sourceUrl":"https://www.fda.gov/files/food/published/Fish-and-Fishery-Products-Hazards-and-Controls-Guidance-Chapter-20--Metal-Inclusion-Download.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q156","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"ステンレス線と通過方向","difficulty":"レベル3","format":"四択","question":"金属検出機の能力確認として、最も適切な方法はどれか。","options":[{"key":"A","text":"ステンレスは金属なので、形状や向きに関係なく同じ感度で検出できる"},{"key":"B","text":"想定する材質・形状・サイズを代表するテストピースを、検出しにくい位置や向きも含めて確認する"},{"key":"C","text":"最も検出しやすい大きな鉄球だけを一度通す"},{"key":"D","text":"装置のカタログ感度だけを記録し、実製品では確認しない"}],"correct":["B"],"conclusion":"金属検出は、材質・形状・向き・製品条件を含めて能力を確認する。","explanation":"ステンレスは鉄系異物より検出しにくい場合があり、細い線状異物は通過方向によって信号が変わる。球状テストピースだけで実際の異物を完全に代表できるとは限らない。","wrongReason":"Cは最も容易な条件だけを確認している。Dは実製品・包装による影響を無視している。Aは材質・形状・方向の違いを否定している。","example":"設備破損で発生し得るワイヤーや刃片を想定し、装置メーカーと試験方法、テストピース、最悪方向を設定する。","terms":"ステンレス、線状異物、方向効果、検出限界","process":"異物検出・検証","hazard":"物理的危害","scope":"実異物による試験は安全に管理し、標準テストピースを基本とする","sourceId":"S048,S049","sourceUrl":"https://www.fda.gov/files/food/published/Fish-and-Fishery-Products-Hazards-and-Controls-Guidance-Chapter-20--Metal-Inclusion-Download.pdf\nhttps://www.fda.gov/files/food/published/Draft-Guidance-for-Industry-Hazard-Analysis-and-Risk-Based-Preventive-Controls-for-Human-Food-Full-Guidance-01292024.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q157","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"X線検査機の適用確認","difficulty":"レベル3","format":"複数選択","question":"X線検査機を異物管理へ使用する場合、確認すべき項目をすべて選んでください。","options":[{"key":"A","text":"製品の厚さ、密度、包装、配置が検出へ与える影響"},{"key":"B","text":"検出時の排除、排除確認、日常テスト、記録"},{"key":"C","text":"対象とする異物の材質・密度・形状・サイズ"},{"key":"D","text":"X線検査機であれば、すべての樹脂・木・骨・ガラスを無条件で検出できると考える"}],"correct":["A","B","C"],"conclusion":"X線検査機も、対象異物と製品条件に対する検出能力と排除機能を確認する。","explanation":"X線検査はガラスや金属などの管理に使える場合があるが、異物と食品の密度差、製品厚さ、重なり、包装によって検出能力が変わる。装置名だけで万能と判断しない。","wrongReason":"Dは、すべての異物を同じ能力で検出できると誤解している。","example":"想定異物を安全な標準片で再現し、中央・端部・製品重なりなどの厳しい位置で検出・排除を確認する。","terms":"X線検査、密度差、包装、排除確認","process":"包装後・異物検査","hazard":"物理的危害","scope":"検出限界は対象異物・製品・装置ごとに妥当性確認","sourceId":"S049","sourceUrl":"https://www.fda.gov/files/food/published/Draft-Guidance-for-Industry-Hazard-Analysis-and-Risk-Based-Preventive-Controls-for-Human-Food-Full-Guidance-01292024.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q158","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"ガラス破損時の対応","difficulty":"レベル4","format":"手順並べ替え","question":"露出食品の近くでガラス製計器が破損しました。対応を論理的な順序に並べてください。A：製造と人・製品の移動を止め、破損区域と対象製品を隔離する　B：破片の飛散範囲、欠損量、設備・容器・作業者への付着を確認する　C：定めた方法で回収・清掃し、必要な分解と再確認を行う　D：製品処置と確認結果を記録し、権限者が再開を承認する","options":[{"key":"A","text":"A→B→C→D"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"C→A→D→B"},{"key":"D","text":"D→C→B→A"}],"correct":["A"],"conclusion":"ガラス破損時は、移動を止めて飛散範囲を特定し、清掃・確認後に再開する。","explanation":"ガラス片は飛散・付着しやすく、通常清掃だけでは残る可能性がある。靴、衣服、容器、ベルト、設備隙間を含め、対象製品と区域を管理する。","wrongReason":"B・C・Dから始める選択肢は、破片と製品の移動防止を後回しにしている。","example":"ガラス・脆性材料台帳、破損品の図面、破片回収数、清掃範囲、廃棄ロットを記録する。","terms":"ガラス、脆性材料、飛散範囲、ライン停止","process":"全工程・破損事故","hazard":"物理的危害","scope":"製品処置は異物の性状、飛散範囲、対象消費者、法令に基づく","sourceId":"S039,S050","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-B/section-117.35\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/cpg-sec-555425-foods-adulteration-involving-hard-or-sharp-foreign-objects","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q159","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"ふるい・マグネットの検証","difficulty":"レベル2","format":"複数選択","question":"ふるいとマグネットを異物管理へ使用する場合、適切な確認をすべて選んでください。","options":[{"key":"A","text":"ふるい網の破れ・取付け・目開きと、マグネットの位置・清掃・状態を確認する"},{"key":"B","text":"捕捉物の種類・量・発生傾向を記録し、異常増加時に原因を調べる"},{"key":"C","text":"設置してあれば、確認や清掃を行わなくても性能は維持される"},{"key":"D","text":"破損や性能低下が見つかった場合、前回正常確認以降の製品を評価する"}],"correct":["A","B","D"],"conclusion":"ふるい・マグネットは、完全性、性能、捕捉物、逸脱時の影響を管理する。","explanation":"ふるいの破れや誤った目開き、マグネットの汚れ・位置ずれ・性能低下は管理能力を失わせる。日常点検と捕捉物の傾向分析を行い、発生源対策へつなげる。","wrongReason":"Cは設置だけで継続的な機能を保証できると誤解している。","example":"清掃時に捕捉した金属粉が急増した場合は、上流のミル、配管、ポンプ、ボルトの摩耗を点検する。","terms":"ふるい、マグネット、完全性、捕捉物、傾向分析","process":"原料投入・粉体搬送","hazard":"物理的危害","scope":"性能確認方法は装置・対象異物・工程に応じて設定","sourceId":"S001,S049","sourceUrl":"https://openknowledge.fao.org/server/api/core/bitstreams/6866dc55-d2c0-48dd-a528-a4d634f1b0b4/content\nhttps://www.fda.gov/files/food/published/Draft-Guidance-for-Industry-Hazard-Analysis-and-Risk-Based-Preventive-Controls-for-Human-Food-Full-Guidance-01292024.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q160","categoryCode":"K","category":"微生物・アレルゲン・異物の深掘り","subtheme":"異物検出の再発と根本原因","difficulty":"レベル4","format":"現場判断","question":"金属検出機で同じ形状の金属片が1週間に複数回排除されています。最も適切な対応はどれか。","options":[{"key":"A","text":"対象製品を管理し、異物の材質・形状・発生時刻を比較して、摩耗部品や工程条件を調査し、原因を除去する"},{"key":"B","text":"排除された製品だけ捨て、設備は正常として製造を続ける"},{"key":"C","text":"検出機の感度を下げ、排除回数を減らす"},{"key":"D","text":"記録が増えるため、同じ異物は一件だけ記録する"}],"correct":["A"],"conclusion":"繰り返す異物検出は、検出工程だけでなく発生源を特定して除去する。","explanation":"同じ異物が繰り返される場合、刃、メッシュ、ワイヤー、ポンプ、ベアリング、締結部などの損傷が進行している可能性がある。排除品の分析、発生時間、設備点検を結び付ける。","wrongReason":"Bは発生源を残す。Cは異物流出リスクを高める。Dは傾向分析と追跡性を失わせる。","example":"異物を写真・寸法・材質で分類し、製造ロット、設備、保守作業、部品交換履歴と照合する。","terms":"異物傾向、根本原因、設備摩耗、排除記録","process":"異物検出・設備保守","hazard":"物理的危害","scope":"製品保留・回収判断は異物性状、流通状況、法令に基づく","sourceId":"S049,S050,S051","sourceUrl":"https://www.fda.gov/files/food/published/Draft-Guidance-for-Industry-Hazard-Analysis-and-Risk-Based-Preventive-Controls-for-Human-Food-Full-Guidance-01292024.pdf\nhttps://www.fda.gov/regulatory-information/search-fda-guidance-documents/cpg-sec-555425-foods-adulteration-involving-hard-or-sharp-foreign-objects\nhttps://www.fsis.usda.gov/policy/fsis-directives/7310.5","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第9回作成"},{"id":"Q161","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"妥当性確認と検証の違い","difficulty":"レベル1","format":"四択","question":"妥当性確認（バリデーション）と検証（ベリフィケーション）の違いとして、最も適切なものはどれか。","options":[{"key":"A","text":"妥当性確認は設備の外観確認、検証は清掃だけを指す"},{"key":"B","text":"妥当性確認は日々の温度記録、検証は製品の味見である"},{"key":"C","text":"どちらも同じ意味で区別しない"},{"key":"D","text":"妥当性確認は管理方法が危害を制御できる根拠を示し、検証は計画どおり実施され有効に機能しているか確認する"}],"correct":["D"],"conclusion":"妥当性確認は設計の有効性、検証は実施と機能の確認である。","explanation":"妥当性確認では、管理手段・管理基準が対象危害を制御できることを科学的・技術的に示す。検証では、記録レビュー、校正、観察、試験などにより、計画が正しく実行され効果を発揮しているかを確認する。","wrongReason":"Bはモニタリングや官能確認と混同している。Cは役割の違いを無視している。Aは対象を狭く誤解している。","example":"新しい加熱条件は導入前に妥当性確認し、稼働後は温度記録、校正、逸脱処置を定期的に検証する。","terms":"妥当性確認、検証、モニタリング","process":"HACCP計画・全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S052,S053","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.155\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.160","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q162","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"妥当性確認に使う根拠","difficulty":"レベル2","format":"四択","question":"新しい加熱工程の妥当性確認に使う根拠として、最も適切なものはどれか。","options":[{"key":"A","text":"科学文献、法令・公的資料、専門家評価、設備・製品試験などを組み合わせた根拠"},{"key":"B","text":"機械のカタログに高性能と書いてあることだけ"},{"key":"C","text":"一度製品検査が陰性だったことだけ"},{"key":"D","text":"担当者の経験だけ"}],"correct":["A"],"conclusion":"妥当性確認は、対象製品と危害に適した科学的・技術的根拠で行う。","explanation":"一般文献や法令値を使う場合も、自社製品の厚さ、量、初期温度、設備、最悪条件へ適用できるか確認する。必要に応じて実設備で試験し、管理条件と許容範囲を定める。","wrongReason":"B・C・Dはいずれも、対象危害を継続して制御できることを十分に示していない。","example":"連続加熱機では、最大投入量、最低初期温度、最高速度など厳しい条件で温度履歴と加熱効果を確認する。","terms":"科学的根拠、設備試験、最悪条件","process":"工程設計・導入前","hazard":"共通","scope":"国際共通の原則","sourceId":"S006,S053","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.160","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q163","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"重要変更時の再分析","difficulty":"レベル3","format":"現場判断","question":"包装材、保存温度、賞味期限を同時に変更する予定です。最も適切な対応はどれか。","options":[{"key":"A","text":"販売後に苦情が出た場合だけ見直す"},{"key":"B","text":"包装材メーカーの保証だけで保存期間を延長する"},{"key":"C","text":"製品名が同じなのでHACCP計画を見直さない"},{"key":"D","text":"新しい危害や危害増大の可能性を再分析し、必要な管理・妥当性確認・表示・記録を変更前に更新する"}],"correct":["D"],"conclusion":"安全性へ影響し得る変更では、変更前に危害分析と計画を再評価する。","explanation":"包装の酸素透過性、低酸素環境、温度、保存期間は微生物増殖や包装完全性へ影響する可能性がある。変更管理として再分析し、必要な試験と記録を行う。","wrongReason":"Cは条件変更を無視している。Aは予防管理にならない。Bは自社製品・流通条件での確認がない。","example":"変更管理票へ対象製品、変更理由、危害評価、試験、承認者、実施日を記録し、旧仕様との混在を防ぐ。","terms":"再分析、変更管理、保存期間、包装","process":"製品・工程変更","hazard":"共通","scope":"国際共通の原則／米国では再分析要件あり","sourceId":"S055","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.170","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q164","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"記録レビューの目的","difficulty":"レベル2","format":"四択","question":"CCP記録を責任者がレビューする主な目的はどれか。","options":[{"key":"A","text":"基準外の数値を正常値へ修正するため"},{"key":"B","text":"監査の直前だけ書類を完成させるため"},{"key":"C","text":"モニタリング、逸脱処置、署名・時刻などが計画どおりで、問題製品が適切に管理されたか確認するため"},{"key":"D","text":"記録用紙の文字をきれいにするため"}],"correct":["C"],"conclusion":"記録レビューは、管理の実施と逸脱処置の適切性を確認する検証活動である。","explanation":"数値が基準内かだけでなく、欠測、遅延記入、訂正、担当者、警報、製品保留、是正内容を確認する。問題があれば対象製品と工程へ遡って対応する。","wrongReason":"Dは形式だけを目的としている。Aは記録改ざんになる。Bは日常的な検証を行っていない。","example":"品質管理者が製造後に加熱記録とPLCログを照合し、逸脱ロットの処置承認まで確認する。","terms":"記録レビュー、検証、逸脱処置","process":"CCP・予防管理","hazard":"共通","scope":"国際共通の原則／具体的期限は適用制度に従う","sourceId":"S054","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.165","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q165","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"校正外れの影響評価","difficulty":"レベル3","format":"現場判断","question":"CCP用温度計が校正確認で実際より3℃高く表示していたことが分かりました。最も適切な対応はどれか。","options":[{"key":"A","text":"過去の記録値から3℃を引いて書き換える"},{"key":"B","text":"前回正常確認以降の記録・製品を特定し、誤差方向と工程余裕から影響を評価して処置する"},{"key":"C","text":"誤差が小さいため自動的に安全とする"},{"key":"D","text":"温度計を調整し、過去の製品は確認しない"}],"correct":["B"],"conclusion":"測定器の校正外れでは、機器の是正と過去の判定への影響を評価する。","explanation":"実際より高く表示していた場合、記録上は合格でも実温度が管理基準未満だった可能性がある。前回正常確認、他の測定、工程余裕、対象ロットを調べる。","wrongReason":"Dは過去への影響を無視している。Aは実測していない値への改ざんである。Cは誤差と基準の関係を評価していない。","example":"校正頻度、使用前確認、基準温度計、交換履歴を見直し、影響製品を保留して権限者が処置を決める。","terms":"校正外れ、誤差方向、影響評価","process":"CCP・測定器","hazard":"共通","scope":"国際共通の原則","sourceId":"S054","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.165","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q166","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"モニタリングと検証","difficulty":"レベル2","format":"○×","question":"作業者が毎ロット温度を測定して記録していれば、それだけでHACCPシステムの検証も完了している。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"日常モニタリングだけでなく、記録レビュー、校正、観察などの検証が必要である。","explanation":"モニタリングは工程が基準内かを日常的に確認する活動である。検証では、そのモニタリングが正しく行われ、管理手段が有効に機能しているかを別の活動で確認する。","wrongReason":"Aはモニタリングと検証を同一視している。","example":"作業者の温度測定とは別に、管理者が記録をレビューし、温度計を校正し、測定手順を現場観察する。","terms":"モニタリング、検証、独立確認","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S052,S054","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.155\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.165","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q167","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"検証活動の組合せ","difficulty":"レベル2","format":"複数選択","question":"HACCPの検証活動に含まれ得るものをすべて選んでください。","options":[{"key":"A","text":"基準外記録を削除して正常に見せる"},{"key":"B","text":"測定機器の校正・精度確認"},{"key":"C","text":"現場観察や製品・環境試験は検証に含めない"},{"key":"D","text":"モニタリング記録と逸脱処置のレビュー"}],"correct":["B","D"],"conclusion":"検証は、記録、機器、現場、試験など複数の方法で行う。","explanation":"危害と管理手段に応じて、記録レビュー、校正、現場観察、サンプリング・試験、内部点検などを組み合わせる。検証頻度と責任者も明確にする。","wrongReason":"Cは検証活動を不当に限定している。Aはデータの信頼性を破壊する。","example":"金属検出工程では、テストピース確認、排除機構の観察、記録レビュー、校正・保守履歴を確認する。","terms":"検証活動、記録レビュー、校正、試験","process":"全工程","hazard":"共通","scope":"国際共通の原則","sourceId":"S052,S054","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.155\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.165","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q168","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"妥当性確認試験の設計","difficulty":"レベル3","format":"複数選択","question":"加熱工程の妥当性確認試験を設計する際、考慮すべき項目をすべて選んでください。","options":[{"key":"A","text":"最も加熱されにくい製品・位置・負荷条件"},{"key":"B","text":"未校正の測定器を使い、一回だけ試験する"},{"key":"C","text":"最も加熱しやすい小さな製品だけを一度確認する"},{"key":"D","text":"製品厚さ、初期温度、速度など実運用の変動範囲"}],"correct":["A","D"],"conclusion":"妥当性確認は、実運用の厳しい条件と変動を代表できる試験にする。","explanation":"平均的条件だけでは、最大負荷や冷点で危害を制御できることを示せない。試験計画、測定位置、反復、機器精度、受入基準、変更時の再確認を文書化する。","wrongReason":"Bは測定の信頼性と再現性を確保していない。Cは最も容易な条件だけを試験している。","example":"製品サイズが複数ある場合、最大厚さと最低初期温度を含め、温度分布と滞留時間を測定する。","terms":"試験計画、最悪条件、冷点、反復","process":"工程設計・変更時","hazard":"共通","scope":"国際共通の原則","sourceId":"S006,S053","sourceUrl":"https://www.fsis.usda.gov/inspection/compliance-guidance/haccp/haccp-validation\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.160","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q169","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"電子記録の監査証跡","difficulty":"レベル3","format":"四択","question":"HACCPの電子記録システムで望ましい監査証跡の説明として、最も適切なものはどれか。","options":[{"key":"A","text":"共有アカウントで全員が同じ名前を使用する"},{"key":"B","text":"誰が、いつ、何を変更したかを記録し、変更前の情報を隠さない"},{"key":"C","text":"異常値を自動的に削除する"},{"key":"D","text":"修正後の数値だけ残し、元の値は消去する"}],"correct":["B"],"conclusion":"電子記録の変更は、元データを残したまま日時・実施者・内容を追跡できるようにする。","explanation":"監査証跡は、記録の作成・変更・削除の履歴を独立して残し、データの真正性と完全性を確認するために使う。法的適用範囲は制度ごとに確認する。","wrongReason":"DとCは元データを失わせる。Aは実施者を特定できない。","example":"設定値変更、警報確認、記録訂正に利用者ID、時刻、変更前後の値、理由、承認を保存する。","terms":"監査証跡、電子記録、データ完全性","process":"自動記録・電子文書","hazard":"共通","scope":"電子記録規制の適用可否は国・制度ごとに確認","sourceId":"S059","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-11/subpart-B/section-11.10","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q170","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"紙記録の訂正","difficulty":"レベル2","format":"四択","question":"紙のHACCP記録を訂正する方法として、最も適切なものはどれか。","options":[{"key":"A","text":"修正液で元の記録を完全に消す"},{"key":"B","text":"用紙を捨て、新しい用紙へ正常値だけ書き直す"},{"key":"C","text":"鉛筆で何度でも消せるようにする"},{"key":"D","text":"元の記録が読めるよう一本線で訂正し、正しい内容、訂正者、日付、必要な理由を残す"}],"correct":["D"],"conclusion":"訂正は元の情報を残し、誰がいつ変更したか分かる方法で行う。","explanation":"記録は実際の観察値を示す証拠である。誤記は隠さず、元の値を判読可能にし、正しい値と訂正情報を残す。重大な訂正は理由と承認も記録する。","wrongReason":"A・Bは元記録を失わせる。Cは消去・改変が容易で記録の信頼性を損なう。","example":"温度の転記ミスを訂正する場合、元値に線を引き、測定器の原記録を確認して訂正理由を記載する。","terms":"記録訂正、原記録、署名、日付","process":"紙記録・全工程","hazard":"共通","scope":"共通の文書管理原則／具体的法的要件は適用制度に従う","sourceId":"S072","sourceUrl":"https://www.fda.gov/media/185615/download","checkedDate":"2026-07-25","status":"完成","audit":"監査済","note":"確認第2回で直接根拠へ変更"},{"id":"Q171","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"バックアップ復元不能","difficulty":"レベル3","format":"現場判断","question":"サーバー障害で温度記録データが消失し、バックアップからも復元できませんでした。最も適切な対応はどれか。","options":[{"key":"A","text":"今後バックアップを取れば、今回の製品は自動的に安全とする"},{"key":"B","text":"現在の設備が正常なら、消失データは問題にしない"},{"key":"C","text":"影響期間と製品を特定・保留し、代替記録で評価し、システム復旧・バックアップ試験・再発防止を行う"},{"key":"D","text":"推定値を入力して記録を完成させる"}],"correct":["C"],"conclusion":"データ消失では、製品影響評価と記録システムの復旧・再発防止を行う。","explanation":"バックアップは保存するだけでなく、実際に復元できることを定期的に確認する必要がある。代替記録が不十分な期間は、管理状態を証明できない可能性がある。","wrongReason":"Bは過去の管理証拠を無視している。Dは実測値を捏造している。Aは今回の影響を評価していない。","example":"PLC、紙記録、警報履歴、製造時刻を照合し、復元テスト、保存先分離、容量監視、責任者を設定する。","terms":"バックアップ、復元試験、データ消失、事業継続","process":"電子記録・全工程","hazard":"共通","scope":"電子記録規制の適用可否は制度ごとに確認","sourceId":"S059","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-11/subpart-B/section-11.10","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q172","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"システム時刻の不一致","difficulty":"レベル3","format":"現場判断","question":"PLC、温度ロガー、包装機の時計がそれぞれ10分以上ずれており、逸脱製品の範囲を特定できません。最も適切な対応はどれか。","options":[{"key":"A","text":"対象範囲を安全側に設定して製品を保留し、時刻同期、変更権限、定期確認、過去記録の影響を是正する"},{"key":"B","text":"機械ごとの時刻があれば、同期は不要である"},{"key":"C","text":"包装機の時刻だけ正しいと仮定する"},{"key":"D","text":"平均時刻を計算して記録を書き換える"}],"correct":["A"],"conclusion":"時刻ずれはトレーサビリティと逸脱範囲を不明確にするため、同期と影響評価が必要である。","explanation":"複数システムのデータを結び付けるには共通時刻が必要である。時刻変更も監査証跡へ残し、停電・夏時間・交換後のずれを確認する。","wrongReason":"Dは根拠のない値へ変更している。Bは記録間の照合不能を放置する。Cは一つの機器を根拠なく優先している。","example":"ネットワーク時刻同期を導入し、日次で時刻差を監視し、許容差を超えた場合に警報を出す。","terms":"時刻同期、PLC、トレーサビリティ、監査証跡","process":"電子記録・ライン連携","hazard":"共通","scope":"国際共通のデータ管理原則","sourceId":"S059","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-11/subpart-B/section-11.10","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q173","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"アクセス権と共有アカウント","difficulty":"レベル2","format":"四択","question":"HACCP記録システムの利用者管理として、最も適切なものはどれか。","options":[{"key":"A","text":"役割に応じて個人IDと権限を設定し、設定変更・承認・削除を必要な人に限定する"},{"key":"B","text":"退職者のIDをそのまま使用する"},{"key":"C","text":"パスワードを設備へ貼り付ける"},{"key":"D","text":"全員が管理者の共有IDを使用する"}],"correct":["A"],"conclusion":"電子記録は個人を識別し、必要最小限の権限で操作できるようにする。","explanation":"共有IDでは、誰が設定や記録を変更したか追跡できない。入退社、異動、緊急権限、パスワード管理、定期レビューを手順化する。","wrongReason":"B・C・Dはいずれも不正操作と追跡不能のリスクを高める。","example":"作業者は入力、班長はレビュー、品質管理は承認、管理者は設定変更というように権限を分離する。","terms":"アクセス権、個人ID、権限分離、電子署名","process":"電子記録・制御設定","hazard":"共通","scope":"電子記録規制の適用可否は制度ごとに確認","sourceId":"S059","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-11/subpart-B/section-11.10","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q174","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"管理手段の導入順序","difficulty":"レベル4","format":"手順並べ替え","question":"新しい殺菌工程を導入する手順として、次の項目を論理的な順序に並べてください。A：対象危害と必要な制御水準を定める　B：管理手段と基準の有効性を妥当性確認する　C：日常モニタリング、逸脱処置、記録を運用する　D：記録レビュー、校正、試験で実施と有効性を検証する","options":[{"key":"A","text":"D→C→B→A"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"A→B→C→D"},{"key":"D","text":"C→A→D→B"}],"correct":["C"],"conclusion":"危害の明確化、妥当性確認、運用、検証の順で管理を構築する。","explanation":"何を制御するかを明確にし、導入前に管理方法が有効であることを示す。その後、日常管理を行い、別の検証活動で継続的な実施と効果を確認する。","wrongReason":"A・B・Dから始める選択肢は、対象危害や有効性を確定する前に運用・検証を進めている。","example":"加熱工程では、対象菌と必要効果を定め、試験後に温度・時間を監視し、記録レビューと校正を行う。","terms":"管理設計、妥当性確認、モニタリング、検証","process":"新工程導入","hazard":"共通","scope":"国際共通の原則","sourceId":"S052,S053,S054","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.155\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.160\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.165","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q175","categoryCode":"L","category":"検証・妥当性確認・記録・データ管理","subtheme":"検証不合格の再発","difficulty":"レベル4","format":"現場判断","question":"同じCCPで記録欠落と確認遅れが繰り返され、教育後も再発しています。最も適切な対応はどれか。","options":[{"key":"A","text":"基準を緩めて不合格を減らす"},{"key":"B","text":"毎回記録を後から埋めて終了する"},{"key":"C","text":"担当者だけを交代し、仕組みは見直さない"},{"key":"D","text":"作業量、手順、設備、責任、教育、監督を根本原因として評価し、管理方法とHACCP計画の有効性を再分析する"}],"correct":["D"],"conclusion":"検証で繰り返し不備が見つかる場合、個人だけでなくシステムと計画を再評価する。","explanation":"同じ問題の再発は、手順が実行困難、頻度が不適切、設備が使いにくい、責任が不明確など、仕組み上の原因を示す可能性がある。必要に応じて再分析し、管理を変更する。","wrongReason":"Bは記録の信頼性を失わせる。Cは根本原因を残す。Aは食品安全の根拠なく基準を変更している。","example":"自動記録、確認アラーム、担当交代時の引継ぎ、管理者レビュー頻度を含めて是正効果を検証する。","terms":"再発、不適合、根本原因、再分析","process":"CCP・検証","hazard":"共通","scope":"国際共通の原則／米国では無効な計画に再分析要件あり","sourceId":"S055","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.170","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q176","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"トレーサビリティロットコード","difficulty":"レベル2","format":"四択","question":"トレーサビリティロットコードの主な役割はどれか。","options":[{"key":"A","text":"賞味期限の代わりに必ず使用する"},{"key":"B","text":"商品の販売価格を示す"},{"key":"C","text":"特定のロットを記録上で一意に識別し、入出荷・加工情報を結び付ける"},{"key":"D","text":"従業員の出勤番号として使う"}],"correct":["C"],"conclusion":"ロットコードは、特定ロットの移動と関連記録を結び付ける識別子である。","explanation":"原料ロット、加工・変換、数量、出荷先などを追跡するには、一貫したロット識別が必要である。具体的な追加記録要件は対象食品・国の制度を確認する。","wrongReason":"B・Dは食品ロット追跡の目的ではない。Aは期限表示とロット識別を混同している。","example":"原料ロットを製造バッチへ結び付け、分割・混合・再加工時に新旧ロットの関係を記録する。","terms":"ロットコード、TLC、追跡、バッチ","process":"受入れ・製造・出荷","hazard":"共通","scope":"具体的義務は販売国・対象食品に従う","sourceId":"S060,S061","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods\nhttps://www.fda.gov/food/food-safety-modernization-act-fsma/traceability-lot-code","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q177","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"回収計画の内容","difficulty":"レベル3","format":"複数選択","question":"食品の回収計画に含めるべき内容をすべて選んでください。","options":[{"key":"A","text":"全製品が自然に返品されるまで、初動連絡を行わない手順"},{"key":"B","text":"回収品の再加工、用途変更、廃棄などの処置と責任者"},{"key":"C","text":"直接の納入先へ連絡し、返品・隔離・処分方法を伝える手順"},{"key":"D","text":"消費者への通知や回収の有効性確認は計画に含めない"}],"correct":["B","C"],"conclusion":"回収計画は、通知、有効性確認、回収品処置、責任分担を具体化する。","explanation":"危害が判明した際に迅速に動けるよう、連絡先、権限、納入先通知、公衆通知、有効性確認、回収品の管理と処分を事前に定める。","wrongReason":"Dは必要な通知と回収到達の確認を省いている。Aは危害の拡大を防ぐ初動を遅らせる。","example":"休日・夜間の連絡網、代理責任者、倉庫・物流会社の連絡先を定期的に更新する。","terms":"回収計画、納入先通知、有効性確認、処分","process":"回収・危機対応","hazard":"共通","scope":"具体的法的要件は国・製品に従う","sourceId":"S062","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.139","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q178","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"模擬回収の実施順序","difficulty":"レベル4","format":"手順並べ替え","question":"模擬回収の手順として、次の項目を論理的な順序に並べてください。A：想定する危害と対象ロットを設定し、出荷停止・在庫保留を開始する　B：原料、製造、再加工、出荷先、数量を記録から追跡する　C：納入先への模擬連絡と回収数量の照合を行う　D：不足情報・所要時間・責任分担を評価し、手順と記録を改善する","options":[{"key":"A","text":"C→A→D→B"},{"key":"B","text":"A→B→C→D"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"B→D→A→C"}],"correct":["B"],"conclusion":"模擬回収は、対象設定、追跡、連絡・数量照合、改善の順で行う。","explanation":"模擬回収では、前方・後方追跡だけでなく、在庫、廃棄、再加工、サンプル、数量差を照合し、必要情報を迅速に提出できるか確認する。","wrongReason":"A・C・Dから始める選択肢は、対象範囲と製品流出防止の設定を後回しにしている。","example":"目標時間を設定し、ロット単位で受入数量、使用数量、在庫、出荷、廃棄の収支を確認する。","terms":"模擬回収、数量照合、前方追跡、後方追跡","process":"トレーサビリティ・回収","hazard":"共通","scope":"追跡記録要件は国・対象食品に従う","sourceId":"S060,S062","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.139","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q179","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"供給者変更と検証","difficulty":"レベル4","format":"現場判断","question":"重要な殺菌工程を供給者が管理している原料について、供給者を変更します。最も適切な対応はどれか。","options":[{"key":"A","text":"供給者自身の自己評価だけを確認し、受入側は評価しない"},{"key":"B","text":"新供給者の危害管理能力を評価し、監査、試験、記録レビューなど適切な検証を行って承認してから使用する"},{"key":"C","text":"最初の納品を使用してから、問題があれば承認する"},{"key":"D","text":"原料名が同じなら、旧供給者の評価をそのまま適用する"}],"correct":["B"],"conclusion":"危害を供給者が管理する場合、新供給者の管理能力と検証方法を使用前に確認する。","explanation":"供給者変更では、危害の重大性、供給者実績、工程、法令、第三者監査、試験結果などから検証活動と頻度を決める。受入施設は記録をレビューし、承認を文書化する。","wrongReason":"Dは供給者固有の能力を無視している。Aは受入側の責任を放棄している。Cは承認前に使用している。","example":"殺菌済み香辛料では、工程監査、殺菌証明、ロット検査、逸脱・回収実績を評価し、受入手順へ登録する。","terms":"供給者承認、供給者検証、監査、試験","process":"調達・受入れ","hazard":"共通","scope":"具体的要件は適用法令・顧客要求に従う","sourceId":"S064","sourceUrl":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-G/section-117.415","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q180","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"輸送温度逸脱の対応","difficulty":"レベル4","format":"手順並べ替え","question":"冷蔵食品の輸送記録に長時間の温度逸脱が見つかりました。対応を論理的な順序に並べてください。A：荷受け・出荷を止め、対象ロットを保留する　B：時間温度履歴、車両、積載、包装、製品温度を確認する　C：製品の安全性を評価し、受入れ・再処理・廃棄などを決める　D：車両・手順・責任分担を是正し、判断と記録を保存する","options":[{"key":"A","text":"A→B→C→D"},{"key":"B","text":"C→A→D→B"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"B→D→A→C"}],"correct":["A"],"conclusion":"輸送逸脱では、製品を保留し、履歴を評価して処置と再発防止を行う。","explanation":"到着時の一時点の温度だけでなく、逸脱時間、最高温度、製品特性、包装、積載位置を確認する。荷主、積込者、運送者、荷受人の責任も明確にする。","wrongReason":"B・C・Dから始める選択肢は、疑わしい製品の流通停止を後回しにしている。","example":"データロガー、車両予冷、扉開放、冷却機警報、積載図を確認し、許容判断の根拠を記録する。","terms":"衛生輸送、温度逸脱、荷受け、物流","process":"輸送・荷受け","hazard":"生物的危害","scope":"具体的輸送要件は国・製品・契約条件に従う","sourceId":"S063","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-sanitary-transportation-human-and-animal-food","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第10回作成"},{"id":"Q181","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"混合ロットの追跡","difficulty":"レベル2","format":"四択","question":"複数の原料ロットを一つの製造バッチへ混合した場合、最も適切なロット管理はどれか。","options":[{"key":"A","text":"混合した時点で原料ロットの記録を削除する"},{"key":"B","text":"新しい製品ロットを設定し、使用したすべての原料ロット、数量、製造バッチとの関係を記録する"},{"key":"C","text":"最も使用量が多い原料ロットだけを記録する"},{"key":"D","text":"完成品ロットを設定せず、製造日だけを記録する"}],"correct":["B"],"conclusion":"混合工程では、新しい製品ロットとすべての投入原料ロットの関係を残す。","explanation":"一つの原料ロットだけを記録すると、問題原料が使われた製品範囲を特定できない。分割、混合、再加工がある場合も、前後のロット関係と数量を追跡できるようにする。","wrongReason":"Cは他の原料ロットを追跡できない。Dは同日の複数バッチを区別できない。Aは追跡情報を失わせる。","example":"混合タンクのバッチ記録へ、各原料のロット、投入量、投入時刻を登録し、充填後の製品ロットへ結び付ける。","terms":"ロット混合、バッチ、原料ロット、数量","process":"混合・製造・出荷","hazard":"共通","scope":"国際共通の原則／具体的追加記録は対象国・食品に従う","sourceId":"S060,S061,S065","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods\nhttps://www.fda.gov/food/food-safety-modernization-act-fsma/traceability-lot-code\nhttps://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX%3A02002R0178-20220701","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q182","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"数量照合の不一致","difficulty":"レベル3","format":"現場判断","question":"模擬回収で、対象ロットの受入数量と、製造・在庫・出荷・廃棄数量の合計に説明できない差が見つかりました。最も適切な対応はどれか。","options":[{"key":"A","text":"出荷数量だけが分かれば十分とする"},{"key":"B","text":"差が小さければ、理由を確認せず回収完了とする"},{"key":"C","text":"計量単位、歩留まり、サンプル、再加工、廃棄、入力漏れを調べ、差を説明できるまで追跡記録と手順を是正する"},{"key":"D","text":"受入数量を合計値へ書き換える"}],"correct":["C"],"conclusion":"数量照合の不一致は、未把握製品や記録欠落の可能性として調査する。","explanation":"原料から完成品までの数量収支は、ロット範囲を確認する重要な手段である。自然な歩留まりや単位換算を考慮しつつ、説明できない差は流出・在庫・再加工・記録漏れを調査する。","wrongReason":"Bは未追跡製品を残す可能性がある。Dは原記録を改変している。Aは後方追跡と在庫確認ができない。","example":"kg、箱、個数の換算表を統一し、試験品、保管サンプル、廃棄、委託倉庫在庫も数量照合へ含める。","terms":"数量照合、マスバランス、模擬回収、在庫","process":"模擬回収・在庫管理","hazard":"共通","scope":"許容差は工程特性と社内手順で定め、説明不能差を放置しない","sourceId":"S060,S062","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.139","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q183","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"委託倉庫・運送会社の管理","difficulty":"レベル3","format":"複数選択","question":"外部の冷蔵倉庫と運送会社を使用する場合、食品事業者が確認すべき項目をすべて選んでください。","options":[{"key":"A","text":"ロット識別、入出庫、在庫、出荷先の記録を共有できること"},{"key":"B","text":"外部委託した時点で、自社の食品安全責任はすべてなくなると考えること"},{"key":"C","text":"温度・衛生・破損・異常時の連絡と製品保留手順があること"},{"key":"D","text":"責任分担、記録保存、再委託、回収訓練を契約・手順で明確にすること"}],"correct":["A","C","D"],"conclusion":"物流を委託しても、要求事項と記録・異常対応を管理する必要がある。","explanation":"倉庫・運送会社はサプライチェーンの一部である。温度、衛生、ロット、セキュリティ、異常時連絡、回収協力などを評価し、契約と実績確認を行う。","wrongReason":"Bは委託先管理と食品事業者の責任を放棄している。","example":"委託倉庫を含む模擬回収を行い、休日でも対象ロットの在庫と出荷先を迅速に提出できるか確認する。","terms":"委託倉庫、3PL、衛生輸送、責任分担","process":"保管・輸送・回収","hazard":"共通","scope":"具体的責任は法令・契約・取引条件に従う","sourceId":"S063,S065","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-sanitary-transportation-human-and-animal-food\nhttps://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX%3A02002R0178-20220701","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q184","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"一段階前後の追跡","difficulty":"レベル1","format":"○×","question":"仕入先と直接の納入先だけを把握していれば、すべての国・すべての食品で必要なトレーサビリティ要件を必ず満たす。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"基本的な前後追跡に加え、対象国・食品ではロット単位の追加情報が求められる場合がある。","explanation":"一段階前後の追跡は重要な基礎であるが、加工・混合・分割・輸送に関するロットコード、数量、場所、時刻などの追加記録が必要な制度もある。適用範囲を個別に確認する。","wrongReason":"Aは国・食品・制度による記録要件の違いを無視している。","example":"輸出製品では、仕向国のロット・保存期間・提出期限・電子データ要求を確認し、社内記録とのギャップを埋める。","terms":"一段階前後、追加記録、ロット追跡","process":"サプライチェーン全体","hazard":"共通","scope":"対象国・食品・免除条件を個別確認","sourceId":"S060,S065","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods\nhttps://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX%3A02002R0178-20220701","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q185","categoryCode":"M","category":"トレーサビリティ・回収・供給者・物流","subtheme":"実回収の初動順序","difficulty":"レベル4","format":"手順並べ替え","question":"出荷済み製品に重大な未表示アレルゲンが判明しました。回収初動を論理的な順序に並べてください。A：出荷・販売を止め、在庫と対象ロットを保留する　B：危害、ロット、流通国、出荷先、数量を評価して回収範囲を決める　C：適用法令に従い当局・顧客・消費者へ連絡し、回収を実行する　D：回収の有効性と数量を確認し、原因是正と再発防止を行う","options":[{"key":"A","text":"C→A→D→B"},{"key":"B","text":"A→B→C→D"},{"key":"C","text":"D→C→B→A"},{"key":"D","text":"B→D→A→C"}],"correct":["B"],"conclusion":"重大危害の回収は、流通停止、範囲評価、通知・回収、有効性確認の順で進める。","explanation":"最初に追加流出を止め、製品・国・顧客の範囲を特定する。その後、法令と回収計画に基づいて通知し、回収数量と到達状況を確認する。","wrongReason":"A・C・Dから始める選択肢は、追加流出防止を後回しにしている。","example":"休日を含む連絡網、各国輸入者、物流在庫、ECサイト販売、回収品処分を一つの管理表で追跡する。","terms":"実回収、未表示アレルゲン、通知、有効性確認","process":"出荷後・回収","hazard":"化学的危害（アレルゲン）","scope":"通知先・期限・分類は販売国の法令に従う","sourceId":"S046,S062,S065","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-questions-and-answers-regarding-food-allergen-labeling-edition-5\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.139\nhttps://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX%3A02002R0178-20220701","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q186","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"米国FSVP輸入者の責任","difficulty":"レベル2","format":"四択","question":"米国へ食品を輸出する際のFSVPについて、最も適切な説明はどれか。","options":[{"key":"A","text":"米国税関へ製品名を申告すればFSVPは完了する"},{"key":"B","text":"海外製造者がHACCP認証を持てば、米国側輸入者のFSVPは常に不要である"},{"key":"C","text":"運送会社だけがFSVPを作成する"},{"key":"D","text":"原則としてFSVP輸入者が、輸入食品と外国供給者についてリスクに基づく検証プログラムを作成・実施する"}],"correct":["D"],"conclusion":"FSVPは、米国側のFSVP輸入者が外国供給者と食品の安全性を検証する制度である。","explanation":"免除や修正要件が適用される場合を除き、FSVP輸入者は食品ごと・外国供給者ごとに危害分析、供給者評価、検証活動、是正、記録を管理する。","wrongReason":"Bは民間認証を法令の代替にしている。CとAはFSVP輸入者の役割を誤っている。","example":"日本の製造者は、米国輸入者が必要とする危害分析、工程管理、監査・試験・是正記録を提供できるよう準備する。","terms":"FSVP、米国輸入者、外国供給者、検証","process":"米国向け輸出","hazard":"共通","scope":"米国制度／免除・修正要件を個別確認","sourceId":"S066","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/final-rule-foreign-supplier-verification-programs-fsvp-glance","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q187","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"EU向け動物性食品の輸入条件","difficulty":"レベル3","format":"現場判断","question":"日本の工場がEU向けに動物性食品を初めて輸出します。顧客から注文書を受け取ったため、すぐ出荷しようとしています。最も適切な対応はどれか。","options":[{"key":"A","text":"製品区分に応じて、輸出国・地域のリスト、施設承認、公式証明書、TRACESや国境検査などの条件を当局・輸入者と確認する"},{"key":"B","text":"日本国内で販売できることだけを確認する"},{"key":"C","text":"顧客の注文があれば、国・施設・証明書の条件を確認せず出荷する"},{"key":"D","text":"ISO 22000認証書だけを添付する"}],"correct":["A"],"conclusion":"EU向け動物性食品は、製品別の国・施設・証明・輸入手続を事前確認する。","explanation":"動物性食品は、関係する第三国リスト、承認施設、モデル証明書、輸入検査などが必要になる場合がある。製品、原料、加工、HS分類だけでなく衛生・動物衛生条件を確認する。","wrongReason":"Cは法的輸入条件を無視している。Dは民間認証を公式輸入要件の代替にしている。Bは日本法への適合だけでEU適合とみなしている。","example":"水産、乳、卵、肉、複合食品では条件が異なるため、製品仕様と原料構成を輸入者・所管当局へ提示して確認する。","terms":"EU輸入、承認施設、公式証明書、TRACES","process":"EU向け輸出","hazard":"共通","scope":"製品・原料・輸出国・適用日ごとに最新条件を確認","sourceId":"S067","sourceUrl":"https://food.ec.europa.eu/animals/animal-products-movements/products-animal-origin-human-consumption_en","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q188","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"ISO 22000認証と法令","difficulty":"レベル1","format":"○×","question":"ISO 22000認証を取得すれば、輸出先を含むすべての国の食品法令へ自動的に適合したことになる。","options":[{"key":"A","text":"正しい"},{"key":"B","text":"誤り"}],"correct":["B"],"conclusion":"ISO 22000認証は食品安全マネジメントシステムの適合を示すが、各国法令の自動適合を保証しない。","explanation":"認証範囲内のマネジメントシステムが規格要求へ適合していることと、個別製品・輸入・表示・施設承認などの法令適合は別に確認する必要がある。","wrongReason":"Aは民間の管理システム認証を、すべての国の法的承認と同一視している。","example":"証明書があっても、輸出先のアレルゲン表示、添加物、微生物基準、輸入証明を個別確認する。","terms":"ISO 22000、法令適合、認証","process":"国際取引・認証","hazard":"共通","scope":"国際共通の説明","sourceId":"S015,S016","sourceUrl":"https://www.iso.org/standard/65464.html\nhttps://www.iso.org/certification.html","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q189","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"FSSC 22000 Version 7移行","difficulty":"レベル2","format":"四択","question":"2026年7月時点でFSSC 22000 Version 6認証を持つ組織の対応として、最も適切なものはどれか。","options":[{"key":"A","text":"公式移行日程と認証機関の計画を確認し、ギャップ分析・教育・内部監査を行って移行監査へ備える"},{"key":"B","text":"Version 7公開日にVersion 6証明書が直ちに無効になる"},{"key":"C","text":"Version 7は任意情報なので永久に無視する"},{"key":"D","text":"自社判断で証明書の版番号だけ書き換える"}],"correct":["A"],"conclusion":"FSSCの版移行は、公式期間と認証機関の計画に基づいて準備する。","explanation":"Version 7は2026年5月に公開され、Version 6監査とVersion 7移行監査には公式の移行期間が設定されている。証明書の有効性と監査時期を認証機関と確認する。","wrongReason":"Bは移行期間を無視している。Cはスキーム更新を放置している。Dは認証機関の審査なしに証明書を変更している。","example":"追加要求、PRP、文書、内部監査、マネジメントレビューを移行計画へ反映する。","terms":"FSSC 22000、Version 7、移行監査","process":"FSSC認証・版管理","hazard":"共通","scope":"2026年7月時点／監査前に公式日程を再確認","sourceId":"S017,S018","sourceUrl":"https://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf\nhttps://www.fssc.com/insights/fssc-22000-version-7-key-changes/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q190","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"GFSI承認と事業所認証","difficulty":"レベル2","format":"四択","question":"GFSIと食品工場の認証の関係として、最も適切な説明はどれか。","options":[{"key":"A","text":"GFSIは食品機械の安全認証制度である"},{"key":"B","text":"GFSIが各工場を直接監査し、証明書を発行する"},{"key":"C","text":"GFSIは認証プログラムをベンチマークし、要件を満たすプログラムを承認する。工場はGFSI承認プログラムに基づき認証機関の審査を受ける"},{"key":"D","text":"GFSI承認があれば、顧客要求や法令確認は不要である"}],"correct":["C"],"conclusion":"GFSIは認証プログラムを承認し、工場を直接認証する機関ではない。","explanation":"事業所は、GFSI承認（recognition）を受けたCertification Programme Ownerが運営するプログラムを選び、第三者認証機関の審査を受ける。GFSI自身が事業所を監査・認証するわけではない。","wrongReason":"BはGFSIと認証機関の役割を混同している。DはGFSI承認を法令・契約の代替にしている。Aは制度の対象を誤っている。","example":"顧客がGFSI承認プログラムを求める場合、製造カテゴリと事業所に合うプログラム・版を確認する。","terms":"GFSI、CPO、第三者認証、ベンチマーキング、recognition","process":"認証選定","hazard":"共通","scope":"国際的な民間認証の仕組み","sourceId":"S068,S069","sourceUrl":"https://mygfsi.com/how-to-implement/recognition/\nhttps://mygfsi.com/how-to-implement/certification/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"確認第2回でGFSI公式用語へ修正"},{"id":"Q191","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"認証範囲の確認","difficulty":"レベル3","format":"現場判断","question":"供給者からFSSC 22000証明書が届きましたが、原料を製造する工場所在地と製品カテゴリが証明書の範囲に見当たりません。最も適切な対応はどれか。","options":[{"key":"A","text":"証明書のロゴだけを確認する"},{"key":"B","text":"供給者が口頭で対象内と言えば十分とする"},{"key":"C","text":"会社名が同じなので、範囲を確認せず承認する"},{"key":"D","text":"証明書の事業所、活動、製品カテゴリ、版、有効期限、認証機関と公開登録情報を確認し、対象外なら別の証拠で評価する"}],"correct":["D"],"conclusion":"認証は証明書に記載された事業所・活動・カテゴリの範囲内で確認する。","explanation":"同じ企業でも複数工場や製品カテゴリがあり、すべてが認証範囲とは限らない。証明書の真正性と公開登録、認証停止・失効も確認する。","wrongReason":"A・B・Cは認証範囲と真正性を確認していない。","example":"供給者台帳へ証明書番号、スコープ、サイト、期限を登録し、更新前に自動通知する。","terms":"認証範囲、サイト、カテゴリ、公開登録","process":"供給者承認・監査","hazard":"共通","scope":"認証プログラムの公式登録・証明書で確認","sourceId":"S017,S073","sourceUrl":"https://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf\nhttps://www.fssc.com/public-register/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q192","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"顧客監査と第三者認証","difficulty":"レベル2","format":"四択","question":"第三者認証を取得している工場へ顧客が独自監査を求めています。最も適切な考え方はどれか。","options":[{"key":"A","text":"第三者認証と顧客監査は、どちらも法令確認を不要にする"},{"key":"B","text":"認証は信頼性向上や監査重複削減に役立つが、顧客が契約・製品固有の要求を別に確認する場合がある"},{"key":"C","text":"認証があれば、顧客は追加要求や監査を絶対に行えない"},{"key":"D","text":"顧客監査を受けると認証が自動的に無効になる"}],"correct":["B"],"conclusion":"第三者認証と顧客監査は目的・範囲が異なり、両方が必要な場合がある。","explanation":"GFSIの調和は監査重複の削減を目指すが、顧客は製品仕様、ブランド要求、供給能力、特定リスクを追加確認することがある。","wrongReason":"Cは契約上の要求を否定している。Dは認証と顧客監査の関係を誤っている。Aは法令適合を別に確認していない。","example":"顧客要求一覧と認証スキーム要求を対照し、重複資料を共通化しつつ固有要求を管理する。","terms":"顧客監査、第三者認証、契約要求","process":"顧客・認証監査","hazard":"共通","scope":"顧客契約と認証スキームに従う","sourceId":"S069","sourceUrl":"https://mygfsi.com/how-to-implement/certification/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q193","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"監査不適合への対応","difficulty":"レベル3","format":"複数選択","question":"監査で重大な記録欠落が指摘された場合、適切な対応をすべて選んでください。","options":[{"key":"A","text":"監査報告書の表現だけを変更し、現場は変えない"},{"key":"B","text":"なぜ起きたか根本原因を分析し、仕組み・責任・教育・設備を是正する"},{"key":"C","text":"是正措置が再発を防いだか有効性を確認し、証拠を残す"},{"key":"D","text":"直ちに欠落による製品・食品安全への影響を評価し、必要な修正を行う"}],"correct":["B","C","D"],"conclusion":"不適合は、修正、影響評価、根本原因、是正措置、有効性確認まで行う。","explanation":"書類を埋めるだけでは、管理が実施されていなかった期間の製品影響や再発原因は解決しない。期限、責任者、証拠を明確にする。","wrongReason":"Aは原因と現場運用を改善していない。","example":"記録頻度が実行困難なら、手順・人員・自動化・確認アラームを見直し、一定期間後に再監査する。","terms":"不適合、修正、根本原因、是正措置、有効性確認","process":"監査・是正","hazard":"共通","scope":"認証スキーム・顧客手順に従う","sourceId":"S017","sourceUrl":"https://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q194","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"食品安全文化の証拠","difficulty":"レベル2","format":"四択","question":"食品安全文化が機能している証拠として、最も適切なものはどれか。","options":[{"key":"A","text":"不具合を報告した従業員を評価しないこと"},{"key":"B","text":"入口に「食品安全第一」と掲示していることだけ"},{"key":"C","text":"監査の日だけ現場を清掃すること"},{"key":"D","text":"経営者の関与、明確な責任、教育、報告しやすさ、目標・測定、問題への対応が実際の行動と記録に表れていること"}],"correct":["D"],"conclusion":"食品安全文化は、標語ではなく、経営・行動・報告・改善の仕組みで示す。","explanation":"従業員が異常を早く報告でき、管理者が資源を投入し、目標と結果をレビューすることが重要である。教育の理解度や再発状況も評価する。","wrongReason":"BとCは表面的な対応である。Aは問題の早期発見を妨げる。","example":"ヒヤリハット報告、停止権限、経営レビュー、教育効果、是正完了率を指標として確認する。","terms":"食品安全文化、経営者、報告、指標","process":"組織全体","hazard":"共通","scope":"FSSCの追加要求など適用スキームを確認","sourceId":"S070","sourceUrl":"https://www.fssc.com/fssc-22000/fssc-22000-v7-additional-requirements/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q195","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"フードディフェンスと食品偽装","difficulty":"レベル2","format":"四択","question":"フードディフェンスと食品偽装（フードフラウド）の違いとして、最も適切なものはどれか。","options":[{"key":"A","text":"フードディフェンスは意図的な危害・改ざんから守る取組みで、食品偽装は主に経済的利益を目的とする不正を評価・軽減する取組みである"},{"key":"B","text":"食品偽装は品質問題だけで食品安全へ影響しない"},{"key":"C","text":"HACCP計画があれば、どちらの評価も不要である"},{"key":"D","text":"どちらも偶発的な微生物汚染だけを扱う"}],"correct":["A"],"conclusion":"意図的危害と経済的動機による不正は、目的と評価方法を分けて管理する。","explanation":"フードディフェンスは故意の危害や改ざんへの脆弱性を扱う。食品偽装は代替、希釈、虚偽表示など経済的動機の脆弱性を扱い、健康危害につながる場合もある。","wrongReason":"Dは意図性を無視している。Bは偽装によるアレルゲン・有害物質リスクを否定している。CはHACCPだけで意図的リスクを十分扱えると誤解している。","example":"アクセス管理と脅威評価はフードディフェンス、原料価格・供給不足・真正性検査は食品偽装対策として整理する。","terms":"フードディフェンス、食品偽装、VACCP、意図的混入","process":"組織・サプライチェーン","hazard":"共通","scope":"適用法令・認証スキームに従う","sourceId":"S070,S071","sourceUrl":"https://www.fssc.com/fssc-22000/fssc-22000-v7-additional-requirements/\nhttps://www.fda.gov/food/food-defense","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q196","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"バルク原料受入れのフードディフェンス","difficulty":"レベル4","format":"現場判断","question":"屋外のバルク液体原料受入口が無施錠で、ホース接続部へ誰でも近づけます。最も適切な対応はどれか。","options":[{"key":"A","text":"注意書きを一枚貼るだけにする"},{"key":"B","text":"脆弱性を評価し、アクセス制限、施錠・封印、受入本人確認、監視、異常時の製品保留などの緩和策を設定する"},{"key":"C","text":"HACCPの微生物危害分析だけで管理済みとする"},{"key":"D","text":"原料は後で加熱するため、意図的混入の評価は不要である"}],"correct":["B"],"conclusion":"意図的混入の機会と影響を評価し、実行可能な緩和策を設定する。","explanation":"バルク受入口は大量製品へ物質を投入できる可能性がある。施設・工程の適用範囲を確認し、アクセス、監視、封印、受入手順、教育を組み合わせる。","wrongReason":"Dは後工程で除去できない物質や広範な危害を無視している。Aは物理的な防止にならない。Cは偶発的危害と意図的危害を混同している。","example":"予約車両、運転者確認、封印番号、ホース保管、受入中の立会い、異常封印時の保留を記録する。","terms":"フードディフェンス、脆弱性、バルク受入れ、アクセス管理","process":"原料受入れ・施設防護","hazard":"意図的危害","scope":"米国IA Ruleなどの適用可否は施設・免除条件を確認","sourceId":"S071","sourceUrl":"https://www.fda.gov/food/food-defense","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q197","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"食品偽装脆弱性評価","difficulty":"レベル3","format":"複数選択","question":"食品偽装の脆弱性評価で考慮すべき項目をすべて選んでください。","options":[{"key":"A","text":"供給者管理、真正性試験、証明書・産地情報の信頼性"},{"key":"B","text":"原料価格、供給不足、取引の複雑さなどの経済的動機"},{"key":"C","text":"過去の偽装事例、原料の代替しやすさ、検出しにくさ"},{"key":"D","text":"第三者認証があれば、偽装の可能性は必ずゼロになると考える"}],"correct":["A","B","C"],"conclusion":"食品偽装は、動機、機会、検出性、供給者管理を評価する。","explanation":"高価な原料、供給不安、複雑な仲介、外観で判別しにくい原料は脆弱性が高まる。評価結果に応じて供給源、試験、契約、情報確認を強化する。","wrongReason":"Dは認証を偽装リスクの完全排除と誤解している。","example":"香辛料、蜂蜜、油、魚種などについて、価格変動と供給者変更時に脆弱性評価を更新する。","terms":"食品偽装、経済的動機、真正性、供給者管理","process":"調達・供給者管理","hazard":"化学的・生物的・アレルゲン等","scope":"適用スキーム・製品リスクに応じて実施","sourceId":"S070","sourceUrl":"https://www.fssc.com/fssc-22000/fssc-22000-v7-additional-requirements/","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q198","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"FDAトレーサビリティ規則の執行時期","difficulty":"レベル3","format":"現場判断","question":"2026年7月、担当者が「FDAはFood Traceability Ruleを2028年7月20日より前は執行しない方針なので、準備をすべて中止する」と提案しました。最も適切な対応はどれか。","options":[{"key":"A","text":"公式情報を継続確認し、対象食品・免除・CTE・KDEを評価して、サプライチェーンと実装準備を続ける"},{"key":"B","text":"2028年までロットコードを使用しない"},{"key":"C","text":"自社だけで独自の適用日を決める"},{"key":"D","text":"規則が廃止されたと判断し、記録整備を削除する"}],"correct":["A"],"conclusion":"執行延期は規則の廃止ではないため、公式情報を追跡しながら準備を進める。","explanation":"FDAは議会の指示に従い、2028年7月20日より前はFood Traceability Ruleを執行しない方針を示している。一方、対象範囲とサプライチェーン連携には時間が必要である。","wrongReason":"DとBは将来の義務と既存の追跡管理を放棄している。Cは法的日程を自社判断で変更している。","example":"Food Traceability List、免除、CTE・KDE、システム連携、取引先データを段階的に確認する。","terms":"Food Traceability Rule、執行延期、CTE、KDE","process":"米国向けトレーサビリティ","hazard":"共通","scope":"2026年7月24日時点／今後の法令・FDA発表を再確認","sourceId":"S060","sourceUrl":"https://www.fda.gov/food/food-safety-modernization-act-fsma/fsma-final-rule-requirements-additional-traceability-records-certain-foods","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q199","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"翻訳文書の版不一致","difficulty":"レベル4","format":"現場判断","question":"海外工場で使用する英語版HACCP手順が、日本語原本より一版古く、管理基準も異なっています。最も適切な対応はどれか。","options":[{"key":"A","text":"英語で書かれていれば、そのまま使用する"},{"key":"B","text":"旧版を使用停止し、原本との内容照合、専門的レビュー、版番号・承認・配布先を管理して現場を再教育する"},{"key":"C","text":"数値だけ手書きで修正し、版番号は変えない"},{"key":"D","text":"監査時だけ最新版を提示する"}],"correct":["B"],"conclusion":"翻訳文書も管理文書として、原本との一致と版・承認・配布を管理する。","explanation":"翻訳の誤りや旧版使用は、異なる管理基準や逸脱対応につながる。言語ごとの責任者、改訂連絡、現場回収、理解確認を設定する。","wrongReason":"Aは内容の正確性を確認していない。Cは正式な変更管理がない。Dは現場運用と監査資料を分離している。","example":"HACCP表、警報値、記録様式を多言語で同時改訂し、旧版を回収して教育記録を残す。","terms":"翻訳、文書管理、版管理、教育","process":"海外工場・監査","hazard":"共通","scope":"認証スキーム・顧客・法令の文書管理要件に従う","sourceId":"S015,S017","sourceUrl":"https://www.iso.org/standard/65464.html\nhttps://www.fssc.com/wp-content/uploads/2026/04/FSSC-22000-Scheme-Version-7.pdf","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"},{"id":"Q200","categoryCode":"N","category":"海外制度・監査・総合ケース","subtheme":"多国間回収の総合対応","difficulty":"レベル4","format":"手順並べ替え","question":"未表示アレルゲン製品が米国・EU・アジアへ出荷済みであることが判明しました。対応を論理的な順序に並べてください。A：全市場への追加出荷を止め、対象ロット・在庫・流通国を保留・特定する　B：各国の危害・表示・通知・回収要件と輸入者責任を確認し、回収範囲を決定する　C：輸入者・当局・顧客・消費者へ必要な通知を行い、回収と数量追跡を実行する　D：回収の有効性を確認し、配合・表示・版管理・出荷承認の根本原因を是正する","options":[{"key":"A","text":"D→C→B→A"},{"key":"B","text":"B→D→A→C"},{"key":"C","text":"A→B→C→D"},{"key":"D","text":"C→A→D→B"}],"correct":["C"],"conclusion":"多国間回収は、流出停止、国別要件評価、通知・回収、有効性確認と是正の順で進める。","explanation":"国ごとに表示対象、通知先、期限、回収区分が異なる可能性がある。共通のロット情報を基礎に、各国輸入者・当局と連携して対応する。","wrongReason":"A・B・Dから始める選択肢は、追加流出の停止と対象製品の確保を後回しにしている。","example":"グローバル回収チームを設置し、国別連絡先、翻訳文、EC販売、委託倉庫、回収数量を一元管理する。","terms":"多国間回収、アレルゲン、当局通知、輸入者","process":"国際出荷・回収","hazard":"化学的危害（アレルゲン）","scope":"各販売国の法令と当局指示に従う","sourceId":"S046,S062,S065","sourceUrl":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/guidance-industry-questions-and-answers-regarding-food-allergen-labeling-edition-5\nhttps://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-117/subpart-C/section-117.139\nhttps://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX%3A02002R0178-20220701","checkedDate":"2026-07-24","status":"完成","audit":"監査済","note":"第11回補完"}]};
